    public MipsR5000Core(VegasMemoryMap memory)
    {
        _memory = memory;
    }

    public ulong Pc { get; private set; }
    public uint LastFetchedInstruction { get; private set; }
    public ulong Cp0Status => _cp0[12];
    public ulong Cp0Cause => _cp0[13];
    public ulong Cp0Epc => _cp0[14];
    public ulong Cp0ErrorEpc => _cp0[30];
    public ulong TileWriteCount => _tileWriteCount;
    public ulong TileWriteMin => _tileWriteMin;
    public ulong TileWriteMax => _tileWriteMax;
    public string LastRuntimeText { get; private set; } = "";
    public string RuntimeDiagnosticStatus
        => $"rtxt={_runtimeTextCallCount}@0x{_lastRuntimeTextPc:X8}/ra=0x{_lastRuntimeTextRa:X8}" +
           (string.IsNullOrWhiteSpace(LastRuntimeText) ? "" : $" \"{LastRuntimeText}\"") +
           GetTileWriteStatus();
    public string HotPcStatus => GetHotPcStatus();

    public void Reset()
    {
        Array.Clear(_gpr);
        Array.Clear(_cp0);
        Array.Clear(_fpr);
        Array.Clear(_fcr);
        _cp0[9] = 0; // Count
        _cp0[11] = 0xffffffff; // Compare
        _cp0[12] = 0x00400004; // Status: BEV | ERL after reset
        _cp0[15] = 0x00002300; // PRId: R5000
        _cp0[16] = 0x00026030; // Config: 32-byte cache lines, 2x system clock
        Pc = 0xffffffffbfc00000UL;
        LastFetchedInstruction = 0xffffffff;
        LastRuntimeText = "";
        _halted = false;
        _hasPendingBranch = false;
        _pendingBranchTarget = 0;
        _hasImmediatePcOverride = false;
        _immediatePcOverride = 0;
        _instructionCounter = 0;
        _traceInstructionCount = 0;
        _runtimeLogTraceCount = 0;
        _runtimeTextCallCount = 0;
        _lastRuntimeTextPc = 0;
        _lastRuntimeTextRa = 0;
        _timerInterruptPending = false;
        _hi = 0;
        _lo = 0;
    }

    public void RunProbeFrame()
        => RunProbeSteps(_stepBudget);

    public void RunProbeFrameAfterSteps(int completedSteps)
        => RunProbeSteps(Math.Max(0, _stepBudget - Math.Max(0, completedSteps)));

    public void RunProbeSteps(int stepCount)
    {
        if (_halted)
            return;

        for (int i = 0; i < stepCount && !_halted; i++)
        {
            _remainingProbeSteps = stepCount - i;
            Step();
            if (_probeStepDebt > 0)
            {
                int consumed = Math.Min(_probeStepDebt, stepCount - i - 1);
                _probeStepDebt -= consumed;
                i += consumed;
            }
        }

        _remainingProbeSteps = 0;
    }

    private void Step()
    {
        ulong pc = Pc;
        if (_profileHotPcs)
            CountHotPc(pc);
        _memory.SetTraceCpuPc(pc);
        TraceKnownRuntimeBgLoadModelStateDelta(pc, "step");
        TraceSuspiciousS8DeadState(pc, "step");
        TraceKnownRuntimeLoadingResetHelper(pc);
        ApplyKnownRuntimeWorldDataTableRepair(pc);
        ApplyKnownRuntimeWorldSelectedPointerRepair(pc);
        ApplyKnownRuntimeUiCommandCompletion(pc);
        ApplyKnownRuntimeWaitForQioCompletion(pc);
        TraceKnownLateRenderPump(pc);
        if (TryFastPathKnownRuntimeDiagnosticTextPumpSkip(pc))
            return;
        if (TryFastPathKnownRuntimeWaitForQioReadyLoop(pc))
            return;
        if (TryFastPathKnownRuntimeUiCommandCompleteWait(pc))
            return;
        ApplyKnownRuntimeBgLoadModelIndexedTextureQioPreStatusMetadataRepair(pc);
        ApplyKnownRuntimeBgLoadModelIndexedTextureQioStatusStackLimitRepair(pc);
        TraceKnownRuntimeBgLoadModelIndexedStatusHelper(pc);
        TraceKnownRuntimeBgLoadModelIndexedPrepareHelper(pc);
        TraceKnownRuntimeBgLoadModelIndexedQioObjectState(pc);
        if (TryFastPathKnownRuntimeBgLoadModelIndexedPrepareDetailPreserve(pc))
            return;
        ApplyKnownRuntimeBgLoadModelQioRequestMetadataRepair(pc);
        ApplyKnownRuntimeBgLoadModelQioCreateAliasRepair(pc);
        TraceKnownRuntimeBgLoadModelQioRequests(pc, "pre-qio-complete");
        ApplyKnownRuntimeBgLoadModelQioCompletion(pc);
        TraceKnownRuntimeBgLoadModelStateDelta(pc, "post-qio-complete");
        TraceKnownRuntimeWorldDataLoader(pc);
        TraceKnownRuntimeWorldDataFlags(pc);
        TraceKnownRuntimeWorldValidity(pc);
        ApplyKnownRuntimeWorldStaticDataLinkRepair(pc);
        ApplyKnownRuntimeWorldSelectionRepair(pc);
        ApplyKnownRuntimeDiagnosticOverlaySuppress(pc);
        TraceKnownRuntimeWorldDataAllocation(pc);
        ApplyKnownRuntimeWorldDataAllocationRepair(pc);
        ApplyKnownRuntimeWorldDataReadBufferRepair(pc);
        ApplyKnownRuntimeWorldValidityBitsetRepair(pc);
        ApplyKnownRuntimeRenderListSaturationRepair(pc);
        ApplyKnownRuntimeBgLoadModelQioAliasRepair(pc);
        ApplyKnownRuntimeBgLoadModelAssetPointerNormalize(pc);
        ApplyKnownRuntimeBgLoadModelAssetNameRepair(pc);
        ApplyKnownRuntimeBgLoadModelDistinctSourcesRepair(pc);
        ApplyKnownRuntimeBgLoadModelIndexedTextureQioStreamLimitRepair(pc);
        TraceKnownRuntimeBgLoadModelLookupHelpers(pc);
        TraceKnownRuntimeBgLoadModelAssetParser(pc);
        TraceKnownRuntimeBgLoadModelQioRequests(pc, "post-alias");
        TraceKnownRuntimeBgLoadModelLoop(pc);
        TraceKnownRuntimeBgLoadModelRecords(pc);
        if (TryFastPathKnownRuntimeBgLoadModelLateStreamScan(pc))
            return;
        if (TryFastPathKnownRuntimeBgLoadModelDispatchReadyRecord(pc))
            return;
        if (TryFastPathKnownRuntimeBgLoadModelStreamCopyTail(pc))
            return;
        if (TryFastPathKnownRuntimeBgLoadModelDispatchFinalFlagTail(pc))
            return;
        if (TryFastPathKnownRuntimeBgLoadModelDispatchBodyTail(pc))
            return;
        if (TryFastPathKnownRuntimeBgLoadModelQioPoll(pc))
            return;
        if (TryFastPathKnownBootA420Handshake(pc))
            return;
        UpdateInterruptPendingBits();
        if (!_hasPendingBranch && TryEnterPendingInterrupt(pc))
            return;
        ApplyKnownRd0SyncReadCompletion(pc);
        ApplyKnownRd0HomeTableParse(pc);
        ApplyKnownRd0HomeBlockStatusRepair(pc);
        ApplyKnownRd0Stage4BootReadCompletion(pc);
        ApplyKnownRd0CallbackRaRestore(pc);
        TraceKnownRd0HomePc(pc);
        if (TryFastPathKnownRd0HomeCounterWait(pc))
            return;
        if (TryFastPathKnownRd0HomeSecondCounterWait(pc))
            return;
        if (TryFastPathKnownGauntletGlideHotPath(pc))
            return;
        if (TryFastPathKnownRd0BootHeaderRead(pc))
            return;
        if (TryFastPathKnownRd0BootFileRead(pc))
            return;
        ApplyKnownBootLoaderAddressBase(pc);
        TraceKnownExceptionRestoreTail(pc);
