        ulong end = source + length;
        _gpr[16] = end;
        _gpr[17] = end;
        _gpr[18] = 0x00000000a1600000UL;
        _gpr[7] = 0;
        _memory.MarkFpgaConfigDone();
        Pc = (pc & 0xffffffffe0000000UL) | 0x1fc00800UL;
        CompleteFastPathStep();
        return true;
    }

