    private bool TryFastPathKnownRuntimeCountDelay(ulong pc)
    {
        ulong offset = pc & 0xffffffffUL;
        bool atEntry = offset == 0x80001a18UL;
        if (!atEntry &&
            offset is not (0x80001a24UL or 0x80001a28UL or 0x80001a2cUL or 0x80001a30UL or 0x80001a34UL))
        {
            return false;
        }
        const ulong entry = 0xffffffff80001a18UL;
        if (_memory.Read32(entry) != 0x00640019U ||
            _memory.Read32(entry + 0x04UL) != 0x00002012U ||
            _memory.Read32(entry + 0x08UL) != 0x40034800U ||
            _memory.Read32(entry + 0x0cUL) != 0x00000000U ||
            _memory.Read32(entry + 0x10UL) != 0x00621823U ||
            _memory.Read32(entry + 0x14UL) != 0x0064082bU ||
            _memory.Read32(entry + 0x18UL) != 0x5420fffcU ||
            _memory.Read32(entry + 0x1cUL) != 0x40034800U ||
            _memory.Read32(entry + 0x20UL) != 0x03e00008U)
        {
            return false;
        }

        ulong delay = atEntry
            ? ((ulong)(uint)_gpr[3] * (uint)_gpr[4]) & 0xffffffffUL
            : _gpr[4] & 0xffffffffUL;
        if (delay == 0 || delay > 0x10000000UL)
            return false;

        ulong returnAddress = _gpr[31];
        ulong returnOffset = returnAddress & 0x1fffffffUL;
        if (returnOffset is < 0x00001000UL or > 0x01000000UL)
            return false;

        uint start = (uint)_gpr[2];
        uint current = (uint)_cp0[9];
        ulong elapsed = unchecked(current - start);
        ulong remaining = elapsed >= delay ? 0UL : delay - elapsed;
        ulong skippedInstructions = Math.Max(1UL, remaining / Math.Max(1UL, _cp0CountStep));
        _gpr[1] = 0;
        _gpr[3] = (uint)(start + delay);
        _gpr[4] = delay;
        _gpr[0] = 0;
        AdvanceCp0Count(Math.Max(_cp0CountStep, remaining));
        _instructionCounter += skippedInstructions + (atEntry ? 4UL : 0UL);
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = CanonicalizeCodeAddress(returnAddress);
        return true;
    }

    private bool TryFastPathKnownRuntimeCp0CountRead(ulong pc)
    {
        const ulong entry = 0xffffffff80010fbcUL;
        if (pc is < entry or > 0xffffffff80010fc8UL)
            return false;

        if (_memory.Read32(entry + 0x00UL) != 0x40024800U ||
            _memory.Read32(entry + 0x04UL) != 0x00000000U ||
            _memory.Read32(entry + 0x08UL) != 0x03e00008U ||
            _memory.Read32(entry + 0x0cUL) != 0x00000000U)
        {
            return false;
        }

        ulong returnAddress = _gpr[31];
        ulong returnOffset = returnAddress & 0x1fffffffUL;
        if (returnOffset is < 0x00001000UL or > 0x01200000UL)
            return false;

        _gpr[2] = (uint)_cp0[9];
        _gpr[0] = 0;
        AdvanceCp0Count(_cp0CountStep * 4UL);
        _instructionCounter += 4UL;
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = CanonicalizeCodeAddress(returnAddress);
        return true;
    }

    private bool TryFastPathKnownRuntimeCp0CauseAccess(ulong pc)
    {
        const ulong readEntry = 0xffffffff800110c0UL;
        const ulong writeEntry = 0xffffffff800110d0UL;
        if (pc is not (readEntry or readEntry + 0x04UL or readEntry + 0x08UL or
                       writeEntry or writeEntry + 0x04UL or writeEntry + 0x08UL))
        {
            return false;
        }

        if (_memory.Read32(readEntry + 0x00UL) != 0x40026800U ||
            _memory.Read32(readEntry + 0x04UL) != 0x00000000U ||
            _memory.Read32(readEntry + 0x08UL) != 0x03e00008U ||
            _memory.Read32(readEntry + 0x0cUL) != 0x00000000U ||
            _memory.Read32(writeEntry + 0x00UL) != 0x40026800U ||
            _memory.Read32(writeEntry + 0x04UL) != 0x40846800U ||
            _memory.Read32(writeEntry + 0x08UL) != 0x03e00008U ||
            _memory.Read32(writeEntry + 0x0cUL) != 0x00000000U)
        {
            return false;
        }

        ulong returnAddress = _gpr[31];
        ulong returnOffset = returnAddress & 0x1fffffffUL;
        if (returnOffset is < 0x00001000UL or > 0x01200000UL)
            return false;

        if (pc >= writeEntry)
        {
            _gpr[2] = _cp0[13];
            WriteCp0(13, _gpr[4]);
        }
        else
        {
            _gpr[2] = _cp0[13];
        }

        _gpr[0] = 0;
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = CanonicalizeCodeAddress(returnAddress);

        ulong skipped = pc == readEntry || pc == writeEntry ? 4UL : 2UL;
        AdvanceCp0Count(_cp0CountStep * skipped);
        _instructionCounter += skipped;
        return true;
    }

    private bool TryFastPathKnownExceptionFpuContextBlock(ulong pc)
    {
        const ulong exceptionSaveAll = 0xffffffff800113ecUL;
        const ulong exceptionSaveEven = 0xffffffff8001146cUL;
        const ulong saveAll = 0xffffffff800114e0UL;
        const ulong saveEven = 0xffffffff80011564UL;
        const ulong loadAll = 0xffffffff80011610UL;
        const ulong loadEven = 0xffffffff8001166cUL;

        if (pc >= exceptionSaveAll && pc <= 0xffffffff80011468UL)
            return TryFastPathKnownLooseExceptionFpuContextStore(pc, 0xffffffff8001146cUL);
        if (pc >= exceptionSaveEven && pc <= 0xffffffff800114a8UL)
            return TryFastPathKnownExceptionFpuContextStore(pc, exceptionSaveEven, 0, 32, 0xffffffff800114acUL, stride: 2);
        if (pc >= saveAll && pc <= 0xffffffff80011560UL)
            return TryFastPathKnownExceptionFpuContextStoreAll(pc, saveAll, 0xffffffff800115a4UL);
        if (pc >= saveEven && pc <= saveEven + 0x3cUL)
            return TryFastPathKnownExceptionFpuContextStore(pc, saveEven, 0, 32, 0xffffffff800115a4UL, stride: 2);
        if (pc >= loadAll && pc <= 0xffffffff80011668UL)
            return TryFastPathKnownLooseExceptionFpuContextLoad(pc, 0xffffffff800116a8UL);
        if (pc >= loadEven && pc <= 0xffffffff800116a4UL)
            return TryFastPathKnownExceptionFpuContextLoad(pc, loadEven, 2, 32, 0xffffffff800116a8UL, stride: 2);

        return false;
    }

    private void TraceKnownExceptionRestoreTail(ulong pc)
    {
        if (!_enableDiagnosticRuntimeFastPaths || _exceptionRestoreTailTraceCount >= 16)
            return;

        if (pc is not (>= 0xffffffff80011680UL and <= 0xffffffff80011694UL) &&
            pc is not (>= 0xffffffff80011728UL and <= 0xffffffff80011738UL))
            return;

        _exceptionRestoreTailTraceCount++;

        ulong context = _gpr[26];
        string contextStatus = IsMainRamRange(context, 0x2a0)
            ? $"ctxStatus={_memory.Read32(context + 0x100UL):x8} ctxHi={_memory.Read32(context + 0x108UL):x8} " +
              $"ctxLo={_memory.Read32(context + 0x110UL):x8} ctxEpc={SignExtend32(_memory.Read32(context + 0x298UL)):x16} " +
              $"ctxRa={SignExtend32(_memory.Read32(context + 0x0f8UL)):x16}"
            : "ctx=unmapped";

        Console.WriteLine(
            $"[GAUNTDL:EXCRET] pc={pc:x16} op={_memory.Read32(pc):x8} " +
            $"status={_cp0[12]:x16} cause={_cp0[13]:x16} epc={_cp0[14]:x16} errorepc={_cp0[30]:x16} " +
            $"sp={_gpr[29]:x16} ra={_gpr[31]:x16} k0={_gpr[26]:x16} k1={_gpr[27]:x16} " +
            $"v0={_gpr[2]:x16} a0={_gpr[4]:x16} {contextStatus}");
    }

    private bool TryFastPathKnownRuntimeTimerOnlyInterruptDispatch(ulong pc)
    {
        const ulong entry = 0xffffffff800de8e0UL;
        if (!_enableRuntimeInterruptSuppress || pc is < entry or > 0xffffffff800dead4UL)
            return false;

        void TraceReject(string reason)
        {
            if (!_enableDiagnosticRuntimeFastPaths || _runtimeInterruptSuppressTraceCount++ >= 8)
                return;

            ulong traceSp = _gpr[29];
            string stackStatus = IsMainRamRange(traceSp + 0x18UL, 0x28)
                ? $"savedRa={SignExtend32(_memory.Read32(traceSp + 0x3cUL)):x16} savedS0={SignExtend32(_memory.Read32(traceSp + 0x18UL)):x16}"
                : "savedRa=unmapped";
            Console.WriteLine(
                $"[GAUNTDL:IRQ] suppress-reject reason={reason} pc={pc:x16} " +
                $"pending={(_cp0[13] & Cp0CauseInterruptPendingMask):x4} " +
                $"status={_cp0[12]:x16} cause={_cp0[13]:x16} epc={_cp0[14]:x16} " +
                $"sp={traceSp:x16} ra={_gpr[31]:x16} {stackStatus} {_memory.GetNileInterruptDebugStatus()}");
        }

        if (_memory.Read32(entry + 0x00UL) != 0x0200f809U ||
            _memory.Read32(entry + 0x10UL) != 0x0240982dU ||
            _memory.Read32(entry + 0x14UL) != 0x24060100U ||
            _memory.Read32(entry + 0x20UL) != 0x02468804U ||
            _memory.Read32(entry + 0x24UL) != 0x8fa60010U ||
            _memory.Read32(entry + 0x30UL) != 0x12c00005U ||
            _memory.Read32(entry + 0x34UL) != 0x023e1024U ||
            _memory.Read32(entry + 0xf8UL) != 0x8ec20020U ||
            _memory.Read32(entry + 0x100UL) != 0x3c028023U ||
            _memory.Read32(entry + 0x220UL) != 0x03e00008U ||
            _memory.Read32(entry + 0x224UL) != 0x27bd0040U)
        {
            TraceReject("signature");
            return false;
        }

        ulong pending = _cp0[13] & Cp0CauseInterruptPendingMask;
        bool timerOnly = (pending & ~Cp0CauseTimerInterrupt) == 0 && (pending & Cp0CauseTimerInterrupt) != 0;
        bool bogusIp2Only = pending == 0x0800UL && !IsRuntimeCodeAddress(_cp0[14]);
        if (!timerOnly && !bogusIp2Only)
        {
            TraceReject("pending");
            return false;
        }

        ulong sp = _gpr[29];
        if (!IsMainRamRange(sp + 0x18UL, 0x28))
        {
            TraceReject("stack");
            return false;
        }

        ulong returnAddress = SignExtend32(_memory.Read32(sp + 0x3cUL));
        ulong returnOffset = returnAddress & 0x1fffffffUL;
        if (returnOffset is < 0x00010000UL or > 0x00100000UL)
        {
            TraceReject($"return-{returnAddress:x16}");
            return false;
        }

        if (timerOnly)
            _timerInterruptPending = false;
        _cp0[13] &= ~pending;
        _memory.SuppressRuntimeBringupInterrupts();
        _gpr[31] = returnAddress;
        _gpr[30] = SignExtend32(_memory.Read32(sp + 0x38UL));
        _gpr[23] = SignExtend32(_memory.Read32(sp + 0x34UL));
        _gpr[22] = SignExtend32(_memory.Read32(sp + 0x30UL));
        _gpr[21] = SignExtend32(_memory.Read32(sp + 0x2cUL));
        _gpr[20] = SignExtend32(_memory.Read32(sp + 0x28UL));
        _gpr[19] = SignExtend32(_memory.Read32(sp + 0x24UL));
        _gpr[18] = SignExtend32(_memory.Read32(sp + 0x20UL));
        _gpr[17] = SignExtend32(_memory.Read32(sp + 0x1cUL));
        _gpr[16] = SignExtend32(_memory.Read32(sp + 0x18UL));
        _gpr[2] = 0;
        _gpr[29] = sp + 0x40UL;
        _gpr[0] = 0;
        AdvanceCp0Count(_cp0CountStep * 32UL);
        _instructionCounter += 32UL;
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = returnAddress;
        return true;
    }

    private bool TryFastPathKnownRuntimeHighTimerService(ulong pc)
    {
        const ulong entry = 0xffffffff800de070UL;
        const ulong frameCounter = 0xffffffff8022817cUL;
        const ulong frameSubCounter = 0xffffffff80228114UL;
        const ulong countLatch = 0xffffffff8022ae44UL;
        if (!_enableBootCountDelay || pc is < entry or > 0xffffffff800de188UL)
            return false;

        bool signatureOk = _memory.Read32(entry + 0x00UL) == 0x27bdffe0U &&
            _memory.Read32(entry + 0x04UL) == 0x3c028023U &&
            _memory.Read32(entry + 0x0cUL) == 0x3c128022U &&
            _memory.Read32(entry + 0x14UL) == 0x8e44ae44U &&
            _memory.Read32(entry + 0x40UL) == 0x0c0043efU &&
            _memory.Read32(entry + 0x48UL) == 0x3c03431bU &&
            _memory.Read32(entry + 0x50UL) == 0x02030018U &&
            _memory.Read32(entry + 0x84UL) == 0x0c0332ecU &&
            _memory.Read32(entry + 0x90UL) == 0xac62ae44U &&
            _memory.Read32(entry + 0xb0UL) == 0x8c628190U &&
            _memory.Read32(entry + 0x104UL) == 0x8fbf001cU &&
            _memory.Read32(entry + 0x108UL) == 0x8fb20018U &&
            _memory.Read32(entry + 0x10cUL) == 0x8fb10014U &&
            _memory.Read32(entry + 0x110UL) == 0x8fb00010U &&
            _memory.Read32(entry + 0x114UL) == 0x03e00008U &&
            _memory.Read32(entry + 0x118UL) == 0x27bd0020U;
        bool liveBodyOk = pc == 0xffffffff800de0c0UL &&
            (_gpr[18] & 0xffffffffUL) == 0x80220000UL &&
            _gpr[17] == 0x3e8UL &&
            _gpr[31] == 0xffffffff800de0b8UL;
        if (!signatureOk && !liveBodyOk)
        {
            return false;
        }

        ulong sp = _gpr[29];
        if (!IsMainRamRange(sp + 0x10UL, 0x10))
            return false;

        ulong returnAddress = SignExtend32(_memory.Read32(sp + 0x1cUL));
        ulong returnOffset = returnAddress & 0x1fffffffUL;
        if (returnOffset is < 0x00010000UL or > 0x00100000UL)
            return false;

        uint counter = _memory.Read32(frameCounter) + 1U;
        _memory.Write32(frameCounter, counter);
        if ((counter & 0x0fU) == 0)
            _memory.Write32(frameSubCounter, _memory.Read32(frameSubCounter) + 1U);

        _memory.Write32(countLatch, (uint)_cp0[9]);
        _timerInterruptPending = false;
        _cp0[13] &= ~Cp0CauseTimerInterrupt;
        _memory.SuppressRuntimeBringupInterrupts();
        _gpr[2] = 0;
        _gpr[31] = returnAddress;
        _gpr[18] = SignExtend32(_memory.Read32(sp + 0x18UL));
        _gpr[17] = SignExtend32(_memory.Read32(sp + 0x14UL));
        _gpr[16] = SignExtend32(_memory.Read32(sp + 0x10UL));
        _gpr[29] = sp + 0x20UL;
        _gpr[0] = 0;
        AdvanceCp0Count(_cp0CountStep * 96UL);
        _instructionCounter += 96UL;
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = returnAddress;
        return true;
    }

    private bool TryFastPathKnownExceptionFpuContextStoreAll(ulong pc, ulong blockStart, ulong exit)
    {
        if (!MatchesKnownFpuAllContextBlock(blockStart, store: true))
            return false;

        ulong context = _gpr[29];
        if (!IsMainRamRange(context + 0x130UL, 0x100))
            return false;

        int startRegister = pc >= blockStart + 31UL * 4UL
            ? 31
            : (int)((pc - blockStart) / 4UL);
        startRegister = Math.Clamp(startRegister, 0, 31);

        for (int register = startRegister; register < 32; register++)
            _memory.Write64(context + 0x130UL + (ulong)register * 8UL, _fpr[register]);

        _gpr[0] = 0;
        Pc = exit;
        CompleteFastPathStep();
        return true;
    }

    private bool TryFastPathKnownLooseExceptionFpuContextStore(ulong pc, ulong exit)
    {
        uint opcode = _memory.Read32(pc);
        int register = (int)((opcode >> 16) & 0x1fU);
        uint expected = 0xf7a00000U | ((uint)register << 16) | (uint)(0x130 + register * 8);
        ulong context = _gpr[29];
        bool opcodeOk = opcode == expected;
        bool contextOk = IsMainRamRange(context + 0x130UL, 0x100);
        if (_enableDiagnosticRuntimeFastPaths && _exceptionFpuContextTraceCount++ < 8)
        {
            Console.WriteLine(
                $"[GAUNTDL:FPUCTX] store pc={pc:x16} op={opcode:x8} expected={expected:x8} " +
                $"fpr={register} sp={context:x16} opcodeOk={opcodeOk} contextOk={contextOk}");
        }

        if (opcode != expected)
            return false;

        if (!contextOk)
            return false;

        for (int fpr = register; fpr < 32; fpr++)
            _memory.Write64(context + 0x130UL + (ulong)fpr * 8UL, _fpr[fpr]);

        _gpr[0] = 0;
        Pc = exit;
        CompleteFastPathStep();
        return true;
    }

    private bool TryFastPathKnownExceptionFpuContextLoadAll(ulong pc, ulong blockStart, ulong exit)
    {
        if (!MatchesKnownFpuAllContextBlock(blockStart, store: false))
            return false;

        ulong context = _gpr[4];
        if (!IsMainRamRange(context + 0x130UL, 0x100))
            return false;

        int startRegister = pc >= blockStart + 31UL * 4UL
            ? 31
            : (int)((pc - blockStart) / 4UL);
        startRegister = Math.Clamp(startRegister, 0, 31);

        for (int register = startRegister; register < 32; register++)
            _fpr[register] = _memory.Read64(context + 0x130UL + (ulong)register * 8UL);

        _gpr[0] = 0;
        Pc = exit;
        CompleteFastPathStep();
        return true;
    }

    private bool TryFastPathKnownLooseExceptionFpuContextLoad(ulong pc, ulong exit)
    {
        uint opcode = _memory.Read32(pc);
        int register = (int)((opcode >> 16) & 0x1fU);
        uint expected = 0xd4800000U | ((uint)register << 16) | (uint)(0x130 + register * 8);
        if ((opcode & 0xffe00000U) != 0xd4800000U)
            return false;

        ulong context = _gpr[4];
        bool opcodeOk = opcode == expected;
        bool contextOk = IsMainRamRange(context + 0x130UL, 0x100);
        if (_enableDiagnosticRuntimeFastPaths && _exceptionFpuContextLoadTraceCount++ < 8)
        {
            Console.WriteLine(
                $"[GAUNTDL:FPUCTX] load pc={pc:x16} op={opcode:x8} expected={expected:x8} " +
                $"fpr={register} a0={context:x16} opcodeOk={opcodeOk} contextOk={contextOk}");
        }

        if (opcode != expected)
            return false;

        if (!contextOk)
            return false;

        for (int fpr = register; fpr < 32; fpr++)
            _fpr[fpr] = _memory.Read64(context + 0x130UL + (ulong)fpr * 8UL);

        _gpr[0] = 0;
        Pc = exit;
        CompleteFastPathStep();
        return true;
    }

    private bool TryFastPathKnownExceptionFpuContextStore(
        ulong pc,
        ulong blockStart,
        int firstRegister,
        int registerLimit,
        ulong exit,
        int stride = 1)
    {
        if (!MatchesSequentialFpuContextBlock(blockStart, firstRegister, registerLimit, store: true, stride))
            return false;

        ulong context = _gpr[29];
        if (!IsMainRamRange(context + 0x130UL, 0x100))
            return false;

        int startRegister = firstRegister + (int)((pc - blockStart) / 4UL) * stride;
        if (startRegister < firstRegister)
            startRegister = firstRegister;

        for (int register = startRegister; register < registerLimit; register += stride)
            _memory.Write64(context + 0x130UL + (ulong)register * 8UL, _fpr[register]);

        _gpr[0] = 0;
        Pc = exit;
        CompleteFastPathStep();
        return true;
    }

    private bool TryFastPathKnownExceptionFpuContextLoad(
        ulong pc,
        ulong blockStart,
        int firstRegister,
        int registerLimit,
        ulong exit,
        int stride = 1)
    {
        if (!MatchesSequentialFpuContextBlock(blockStart, firstRegister, registerLimit, store: false, stride))
            return false;

        ulong context = _gpr[4];
        if (!IsMainRamRange(context + 0x130UL, 0x100))
            return false;

        int startRegister = firstRegister + (int)((pc - blockStart) / 4UL) * stride;
        if (startRegister < firstRegister)
            startRegister = firstRegister;

        for (int register = startRegister; register < registerLimit; register += stride)
            _fpr[register] = _memory.Read64(context + 0x130UL + (ulong)register * 8UL);

        _gpr[0] = 0;
        Pc = exit;
        CompleteFastPathStep();
        return true;
    }

    private bool MatchesKnownFpuAllContextBlock(ulong blockStart, bool store)
    {
        uint opcodeBase = store ? 0xf7a00000U : 0xd4800000U;
        for (int register = 0; register < 31; register++)
        {
            uint expected = opcodeBase | ((uint)register << 16) | (uint)(0x130 + register * 8);
            if (_memory.Read32(blockStart + (ulong)register * 4UL) != expected)
                return false;
        }

        if ((_memory.Read32(blockStart + 31UL * 4UL) & 0xffff0000U) != 0x10000000U)
            return false;

        uint finalExpected = opcodeBase | (31U << 16) | (uint)(0x130 + 31 * 8);
        return _memory.Read32(blockStart + 32UL * 4UL) == finalExpected;
    }

    private bool MatchesSequentialFpuContextBlock(ulong blockStart, int firstRegister, int registerLimit, bool store, int stride)
    {
        uint opcodeBase = store ? 0xf7a00000U : 0xd4800000U;
        int index = 0;
        for (int register = firstRegister; register < registerLimit; register += stride, index++)
        {
            uint expected = opcodeBase | ((uint)register << 16) | (uint)(0x130 + register * 8);
            if (_memory.Read32(blockStart + (ulong)index * 4UL) != expected)
                return false;
        }

        return true;
    }

    private bool TryFastPathKnownRuntimeGlobal808cExchange(ulong pc)
    {
        const ulong entry = 0xffffffff800b1dc4UL;
        const ulong delaySlot = 0xffffffff800b1dd0UL;
        const ulong global = 0xffffffff8022808cUL;
        if (pc is < entry or > delaySlot)
            return false;

        if (_memory.Read32(entry + 0x00UL) != 0x3c038023U ||
            _memory.Read32(entry + 0x04UL) != 0x8c62808cU ||
            _memory.Read32(entry + 0x08UL) != 0x03e00008U ||
            _memory.Read32(entry + 0x0cUL) != 0xac64808cU)
        {
            return false;
        }

        if (!IsMainRamRange(global, 4))
            return false;

        if (pc != delaySlot)
            _gpr[2] = SignExtend32(_memory.Read32(global));
        _memory.Write32(global, (uint)_gpr[4]);
        _gpr[0] = 0;
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = _gpr[31];

        ulong skipped = pc == entry ? 4UL : pc == delaySlot ? 1UL : 2UL;
        AdvanceCp0Count(_cp0CountStep * skipped);
        _instructionCounter += skipped;
        return true;
    }

    private bool TryFastPathKnownRuntimeStatusMaskUpdate(ulong pc)
    {
        const ulong entry = 0xffffffff800111c8UL;
        if (pc is not (entry or
                       0xffffffff800111ccUL or
                       0xffffffff800111d0UL or
                       0xffffffff800111d4UL or
                       0xffffffff800111d8UL or
                       0xffffffff800111dcUL or
                       0xffffffff800111e0UL or
                       0xffffffff800111e8UL or
                       0xffffffff800111ecUL or
                       0xffffffff800111f0UL or
                       0xffffffff800111f4UL or
                       0xffffffff800111f8UL or
                       0xffffffff800111fcUL or
                       0xffffffff80011200UL))
            return false;
        if (_memory.Read32(entry + 0x00UL) != 0x3c028016U ||
            _memory.Read32(entry + 0x04UL) != 0x64425cecU ||
            _memory.Read32(entry + 0x08UL) != 0x8c420000U ||
            _memory.Read32(entry + 0x0cUL) != 0x10400003U ||
            _memory.Read32(entry + 0x10UL) != 0x00000000U ||
            _memory.Read32(entry + 0x14UL) != 0x00400008U ||
            _memory.Read32(entry + 0x18UL) != 0x00000000U ||
            _memory.Read32(entry + 0x1cUL) != 0x40026000U ||
            _memory.Read32(entry + 0x20UL) != 0x3408ff07U ||
            _memory.Read32(entry + 0x24UL) != 0x00084827U ||
            _memory.Read32(entry + 0x28UL) != 0x00885024U ||
            _memory.Read32(entry + 0x2cUL) != 0x01224824U ||
            _memory.Read32(entry + 0x30UL) != 0x01495025U ||
            _memory.Read32(entry + 0x34UL) != 0x408a6000U ||
            _memory.Read32(entry + 0x38UL) != 0x00000000U ||
            _memory.Read32(entry + 0x3cUL) != 0x03e00008U)
        {
            return false;
        }
        if (_memory.Read32(0xffffffff80165cecUL) != 0)
            return false;

        ulong returnAddress = _gpr[31];
        ulong returnOffset = returnAddress & 0x1fffffffUL;
        if (returnOffset is < 0x00001000UL or > 0x01000000UL)
            return false;

        ApplyRuntimeStatusMaskUpdate(returnAddress);
        return true;
    }

    private bool TryFastPathKnownRuntimeStatusMaskUpdateCallsite(ulong pc)
    {
        const ulong helper = 0xffffffff800111c8UL;
        ulong callsite;
        ulong delaySlot;
        ulong returnAddress;
        ulong? delayA0;
        if (pc is 0xffffffff800de244UL or 0xffffffff800de248UL)
        {
            callsite = 0xffffffff800de244UL;
            delaySlot = 0xffffffff800de248UL;
            returnAddress = 0xffffffff800de24cUL;
            delayA0 = 0x7f00UL;
        }
        else if (pc is 0xffffffff800de280UL or 0xffffffff800de284UL)
        {
            callsite = 0xffffffff800de280UL;
            delaySlot = 0xffffffff800de284UL;
            returnAddress = 0xffffffff800de288UL;
            delayA0 = null;
        }
        else
        {
            return false;
        }

        if (_memory.Read32(callsite) != 0x0c004472U ||
            _memory.Read32(delaySlot) != (delayA0.HasValue ? 0x24047f00U : 0x00000000U) ||
            _memory.Read32(helper + 0x00UL) != 0x3c028016U ||
            _memory.Read32(helper + 0x04UL) != 0x64425cecU ||
            _memory.Read32(helper + 0x08UL) != 0x8c420000U ||
            _memory.Read32(helper + 0x0cUL) != 0x10400003U ||
            _memory.Read32(helper + 0x1cUL) != 0x40026000U ||
            _memory.Read32(helper + 0x20UL) != 0x3408ff07U ||
            _memory.Read32(helper + 0x34UL) != 0x408a6000U ||
            _memory.Read32(helper + 0x3cUL) != 0x03e00008U)
        {
            return false;
        }
        if (_memory.Read32(0xffffffff80165cecUL) != 0)
            return false;
        if (pc == delaySlot &&
            CanonicalizeCodeAddress(_gpr[31]) != returnAddress &&
            (!_hasPendingBranch || CanonicalizeCodeAddress(_pendingBranchTarget) != helper))
        {
            return false;
        }

        if (delayA0.HasValue)
            _gpr[4] = delayA0.Value;
        ApplyRuntimeStatusMaskUpdate(returnAddress);
        _gpr[31] = returnAddress;
        return true;
    }

    private bool TryFastPathKnownRuntimePlainStatusMaskUpdate(ulong pc)
    {
        const ulong entry = 0xffffffff80011270UL;
        if (pc is < entry or > 0xffffffff80011290UL)
            return false;

        if (_memory.Read32(entry + 0x00UL) != 0x40026000U ||
            _memory.Read32(entry + 0x04UL) != 0x3408ff07U ||
            _memory.Read32(entry + 0x08UL) != 0x00084827U ||
            _memory.Read32(entry + 0x0cUL) != 0x00885024U ||
            _memory.Read32(entry + 0x10UL) != 0x01224824U ||
            _memory.Read32(entry + 0x14UL) != 0x01495025U ||
            _memory.Read32(entry + 0x18UL) != 0x408a6000U ||
            _memory.Read32(entry + 0x1cUL) != 0x00000000U ||
            _memory.Read32(entry + 0x20UL) != 0x03e00008U ||
            _memory.Read32(entry + 0x24UL) != 0x00000000U)
        {
            return false;
        }

        ulong returnAddress = _gpr[31];
        ulong returnOffset = returnAddress & 0x1fffffffUL;
        if (returnOffset is < 0x00001000UL or > 0x01000000UL)
            return false;

        ApplyRuntimeStatusMaskUpdate(returnAddress);
        return true;
    }

    private void ApplyRuntimeStatusMaskUpdate(ulong returnAddress)
    {
        const ulong mask = 0xff07UL;
        ulong oldStatus = _cp0[12];
        ulong nextStatus = (_gpr[4] & mask) | (oldStatus & ~mask);
        _gpr[2] = SignExtend32((uint)oldStatus);
        _gpr[8] = mask;
        _gpr[9] = ~mask;
        _gpr[10] = nextStatus;
        _gpr[0] = 0;
        _cp0[12] = nextStatus;
        AdvanceCp0Count(_cp0CountStep * 10UL);
        _instructionCounter += 10UL;
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = CanonicalizeCodeAddress(returnAddress);
    }

    private bool TryFastPathKnownRuntimeListHeadProbeWrapperEntry(ulong pc)
    {
        const ulong wrapper = 0xffffffff800de2ccUL;
        const ulong hookPointer = 0xffffffff80238174UL;
        const ulong listHead = 0xffffffff80262ad0UL;
        if (pc != wrapper)
            return false;
        if (_memory.Read32(wrapper + 0x00UL) != 0x27bdffe8U ||
            _memory.Read32(wrapper + 0x04UL) != 0x3c028023U ||
            _memory.Read32(wrapper + 0x08UL) != 0x8c428174U ||
            _memory.Read32(wrapper + 0x0cUL) != 0x0080282dU ||
            _memory.Read32(wrapper + 0x10UL) != 0x10400005U ||
            _memory.Read32(wrapper + 0x14UL) != 0xafbf0010U ||
            _memory.Read32(wrapper + 0x28UL) != 0x3c048026U ||
            _memory.Read32(wrapper + 0x2cUL) != 0x0c03787eU ||
            _memory.Read32(wrapper + 0x30UL) != 0x24842ad0U ||
            _memory.Read32(wrapper + 0x34UL) != 0x8fbf0010U ||
            _memory.Read32(wrapper + 0x38UL) != 0x03e00008U ||
            _memory.Read32(wrapper + 0x3cUL) != 0x27bd0018U)
        {
            return false;
        }
        if (_memory.Read32(hookPointer) != 0)
            return false;

        ulong record = _gpr[4];
        if (!IsMainRamRange(record + 4UL, 4UL) ||
            _memory.Read32(record + 4UL) != unchecked((uint)listHead))
        {
            return false;
        }

        ulong returnAddress = _gpr[31];
        if ((returnAddress >> 32) != 0xffffffffUL)
            return false;
        ulong returnOffset = returnAddress & 0x1fffffffUL;
        if (returnOffset is < 0x000c0000UL or > 0x00120000UL)
            return false;

        _gpr[2] = SignExtend32(unchecked((uint)listHead));
        _gpr[0] = 0;
        AdvanceCp0Count(_cp0CountStep * 48UL);
        _instructionCounter += 48UL;
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = CanonicalizeCodeAddress(returnAddress);
        return true;
    }

    private bool TryFastPathKnownRamTest(ulong pc)
    {
        ulong offset = pc & 0x1fffffffUL;
        if (offset is not (0x1fc02468UL or 0x1fc01f80UL))
            return false;

        ulong start = _gpr[4];
        ulong end = _gpr[5];
        ulong returnAddress = _gpr[31];
        ulong segment = start & 0xffffffffe0000000UL;
        if (segment is not (0x0000000080000000UL or 0x00000000a0000000UL or
                            0xffffffff80000000UL or 0xffffffffa0000000UL))
            return false;
        if (end < start || end - start > 0x02000000UL)
            return false;
        if ((returnAddress & 0x1fffffffUL) is < 0x1fc00000UL or > 0x1fc80000UL)
            return false;

        _gpr[2] = 0;
        Pc = returnAddress;
        CompleteFastPathStep();
        return true;
    }

    private bool TryFastPathKnownRamQwordFill(ulong pc)
    {
        if (pc != 0xffffffff80005b18UL)
            return false;
        if (_memory.Read32(pc) != 0x2508ffffU ||
            _memory.Read32(pc + 4) != 0xfc850000U ||
            _memory.Read32(pc + 8) != 0x1d00fffdU ||
            _memory.Read32(pc + 12) != 0x24840008U)
            return false;

        ulong count = _gpr[8];
        if (count == 0 || unchecked((long)count) <= 0 || count > 0x00400000UL)
            return false;

        ulong start = _gpr[4];
        ulong byteLength = count * 8UL;
        if ((start & 7UL) != 0 || !IsMainRamRange(start, byteLength))
            return false;

        ulong cursor = start;
        ulong value = _gpr[5];
        for (ulong i = 0; i < count; i++)
        {
            _memory.Write64(cursor, value);
            cursor += 8;
        }

        _gpr[4] = cursor;
        _gpr[8] = 0;
        _gpr[0] = 0;
        AdvanceCp0Count(Math.Max(_cp0CountStep, count * 4UL * _cp0CountStep));
        _instructionCounter += count * 4UL;
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = 0xffffffff80005b28UL;
        return true;
    }

    private bool TryFastPathKnownRamQwordCopyBody(ulong pc)
    {
        const ulong entry = 0xffffffff80005a10UL;
        const ulong tail = 0xffffffff800059a0UL;
        if (pc is < entry or > 0xffffffff80005a4cUL)
            return false;

        if (_memory.Read32(entry) != 0x000640c2U ||
            _memory.Read32(entry + 0x04UL) != 0x000848c0U ||
            _memory.Read32(entry + 0x08UL) != 0x00c93022U ||
            _memory.Read32(entry + 0x0cUL) != 0x1900ffdaU ||
            _memory.Read32(entry + 0x10UL) != 0x2508ffffU ||
            _memory.Read32(entry + 0x14UL) != 0xdca90000U ||
            _memory.Read32(entry + 0x18UL) != 0x24a50008U ||
            _memory.Read32(entry + 0x1cUL) != 0xfc890000U ||
            _memory.Read32(entry + 0x20UL) != 0x1d00fffbU ||
            _memory.Read32(entry + 0x24UL) != 0x24840008U ||
            _memory.Read32(entry + 0x28UL) != 0x1000ffd3U)
        {
            return false;
        }

        long remainingAfterCurrent = unchecked((long)_gpr[8]);
        if (remainingAfterCurrent < 0 || remainingAfterCurrent > 0x00100000L)
            return false;

        ulong qwords = (ulong)remainingAfterCurrent + 1UL;
        ulong byteLength = qwords * 8UL;
        ulong destination = _gpr[4];
        ulong source = _gpr[5];
        if ((destination & 7UL) != 0 ||
            (source & 7UL) != 0 ||
            !IsMainRamRange(destination, byteLength) ||
            !IsMainRamRange(source, byteLength))
        {
            return false;
        }

        ulong lastValue = 0;
        for (ulong offset = 0; offset < byteLength; offset += 8UL)
        {
            lastValue = _memory.Read64(source + offset);
            _memory.Write64(destination + offset, lastValue);
        }

        _gpr[4] = destination + byteLength;
        _gpr[5] = source + byteLength;
        _gpr[8] = 0;
        _gpr[9] = lastValue;
        Pc = tail;
        CompleteFastPathStep();
        return true;
    }

    private bool TryFastPathKnownLoadedBootMemoryWalk(ulong pc)
    {
        const ulong loop = 0xffffffffa00f0880UL;
        if (pc is < loop or > 0xffffffffa00f08e4UL)
            return false;

        if (pc >= 0xffffffffa00f08d4UL &&
            _memory.Read32(loop + 0x38UL) == 0x0083082bU &&
            _memory.Read32(loop + 0x3cUL) == 0x14200003U &&
            _memory.Read32(loop + 0x54UL) == 0x24840004U &&
            _memory.Read32(loop + 0x58UL) == 0x24a50004U &&
            _memory.Read32(loop + 0x5cUL) == 0x24c6fffcU &&
            _memory.Read32(loop + 0x60UL) == 0x14c0fff2U &&
            unchecked((long)_gpr[6]) <= 0)
        {
            _memory.Write32(0xffffffffa0000034UL, (uint)_gpr[7]);
            Pc = _gpr[16];
            CompleteFastPathStep();
            return true;
        }

        if (_memory.Read32(loop) != 0x40086000U ||
            _memory.Read32(loop + 0x04UL) != 0x3c012000U ||
            _memory.Read32(loop + 0x08UL) != 0x00812025U ||
            _memory.Read32(loop + 0x0cUL) != 0x0080802dU ||
            _memory.Read32(loop + 0x10UL) != 0x2401fffeU ||
            _memory.Read32(loop + 0x14UL) != 0x01014024U ||
            _memory.Read32(loop + 0x18UL) != 0x40886000U ||
            _memory.Read32(loop + 0x1cUL) != 0x3c03a000U ||
            _memory.Read32(loop + 0x20UL) != 0x34630400U ||
            _memory.Read32(loop + 0x24UL) != 0x3c08a000U ||
            _memory.Read32(loop + 0x28UL) != 0x350807ffU ||
            _memory.Read32(loop + 0x2cUL) != 0x0104082bU ||
            _memory.Read32(loop + 0x60UL) != 0x14c0fff2U)
        {
            return false;
        }

        ulong remaining = _gpr[6];
        if (remaining == 0 || remaining > 0x01000000UL || (remaining & 3UL) != 0)
            return false;

        ulong destination = _gpr[4];
        ulong source = _gpr[5];
        ulong jumpTarget = _gpr[16];
        if (!IsMainRamRange(source, remaining))
            return false;

        for (ulong offset = 0; offset < remaining; offset += 4UL)
        {
            ulong target = destination + offset;
            uint target32 = (uint)target;
            if (target32 is >= 0xa0000400U and <= 0xa00007ffU)
                continue;
            if (!IsMainRamRange(target, 4UL))
                return false;

            _memory.Write32(target, _memory.Read32(source + offset));
        }

        _gpr[1] = 0;
        _gpr[2] = _memory.Read32(source + remaining - 4UL);
        _gpr[3] = 0x00000000a0000400UL;
        _gpr[4] = destination + remaining;
        _gpr[5] = source + remaining;
        _gpr[6] = 0;
        _gpr[8] = 0x00000000a00007ffUL;
        _memory.Write32(0xffffffffa0000034UL, (uint)_gpr[7]);
        Pc = jumpTarget;
        CompleteFastPathStep();
        return true;
    }

    private bool TryFastPathKnownLoadedBootInflate(ulong pc)
    {
        if (pc is < 0xffffffff80042830UL or > 0xffffffff80042bd4UL)
            return false;

        if (_gpr[31] != 0xffffffff80041fc0UL)
            return false;
        if (_memory.Read32(0xffffffff8004b2b0UL) != 0x666e6920U ||
            _memory.Read32(0xffffffff8004b2b4UL) != 0x6574616cU ||
            _memory.Read32(0xffffffff80042830UL) != 0x27bdffe0U ||
            _memory.Read32(0xffffffff80042834UL) != 0x8fae0034U)
        {
            return false;
        }

        ulong stream = _gpr[19];
        if (!IsMainRamRange(stream, 0x38UL))
            return false;

        uint nextIn = _memory.Read32(stream + 0x00UL);
        uint availIn = _memory.Read32(stream + 0x04UL);
        uint totalIn = _memory.Read32(stream + 0x08UL);
        uint nextOut = _memory.Read32(stream + 0x0cUL);
        uint availOut = _memory.Read32(stream + 0x10UL);
        uint totalOut = _memory.Read32(stream + 0x14UL);
        uint state = _memory.Read32(stream + 0x1cUL);

        if (nextIn < totalIn || nextOut < totalOut)
            return false;

        uint sourceBase32 = nextIn - totalIn;
        uint destinationBase32 = nextOut - totalOut;
        uint sourceLength = totalIn + availIn;
        uint destinationCapacity = totalOut + availOut;
        ulong sourceBase = SignExtend32(sourceBase32);
        ulong destinationBase = SignExtend32(destinationBase32);
        if (state != 0x800f0870U ||
            sourceLength is 0 or > 0x00400000U ||
            destinationCapacity is 0 or > 0x01000000U ||
            !IsMainRamRange(sourceBase, sourceLength) ||
            !IsMainRamRange(destinationBase, destinationCapacity))
        {
            return false;
        }

        byte[] compressed = new byte[sourceLength];
        for (uint i = 0; i < sourceLength; i++)
            compressed[i] = _memory.Read8(sourceBase + i);

        byte[] output = new byte[destinationCapacity];
        int decoded;
        try
        {
            using MemoryStream input = new(compressed);
            using ZLibStream zlib = new(input, CompressionMode.Decompress);
            decoded = 0;
            while (decoded < output.Length)
            {
                int read = zlib.Read(output, decoded, output.Length - decoded);
                if (read == 0)
                    break;
                decoded += read;
            }
        }
        catch (InvalidDataException)
        {
            return false;
        }

        if (decoded == 0 || decoded > destinationCapacity)
            return false;

        for (int i = 0; i < decoded; i++)
            _memory.Write8(destinationBase + (uint)i, output[i]);

        _memory.Write32(stream + 0x00UL, sourceBase32 + sourceLength);
        _memory.Write32(stream + 0x04UL, 0);
        _memory.Write32(stream + 0x08UL, sourceLength);
        _memory.Write32(stream + 0x0cUL, destinationBase32 + (uint)decoded);
        _memory.Write32(stream + 0x10UL, destinationCapacity - (uint)decoded);
        _memory.Write32(stream + 0x14UL, (uint)decoded);

        _gpr[2] = 1;
        _gpr[3] = stream;
        _gpr[4] = sourceBase + sourceLength;
        _gpr[5] = destinationBase + (uint)decoded;
        _gpr[6] = 1;
        _gpr[7] = SignExtend32(destinationBase32);
        Pc = _gpr[31];
        CompleteFastPathStep();
        return true;
    }

    private bool TryFastPathKnownLoadedBootBssClear(ulong pc)
    {
        const ulong loop = 0xffffffff800105b4UL;
        if (pc is not (0xffffffff800105b4UL or 0xffffffff800105b8UL or
                       0xffffffff800105bcUL or 0xffffffff800105c0UL))
        {
