        if (_memory.Read32(loop) != 0xac400000U ||
            _memory.Read32(loop + 0x04UL) != 0x24420004U ||
            _memory.Read32(loop + 0x08UL) != 0x0043082aU ||
            _memory.Read32(loop + 0x0cUL) != 0x1420fffdU ||
            _memory.Read32(loop + 0x10UL) != 0xac400000U)
        {
