        ulong cursor = _gpr[2];
        ulong end = _gpr[3];
        if (cursor >= end || ((cursor | end) & 3UL) != 0 || !IsMainRamRange(cursor, end - cursor))
            return false;

        for (ulong address = cursor; address < end; address += 4UL)
            _memory.Write32(address, 0);

        _gpr[1] = 0;
        _gpr[2] = end;
        Pc = 0xffffffff800105c8UL;
        CompleteFastPathStep();
        return true;
    }

