        AdvanceCp0Count(_cp0CountStep * (ulong)Math.Max(1, width + 8));
        _instructionCounter += (ulong)Math.Max(1, width + 8);
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = _gpr[31];
        return true;
    }

