        uint result = _memory.Read32(0xffffffff800a778cUL) & 1u;
        _gpr[2] = result;
        _gpr[31] = branchPc;
        _gpr[0] = 0;
        AdvanceCp0Count(_cp0CountStep * 8UL);
        _instructionCounter += 8UL;
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
