    private bool TryFastPathKnownRuntimeDiagnosticMenuScan(ulong pc)
    {
        const ulong loopEntry = 0xffffffff80019924UL;
        const ulong epilogue = 0xffffffff80019abcUL;
        if (!_experimentRuntimeDiagnosticMenuScanFastPath || pc != loopEntry)
            return false;

        if (_memory.Read32(loopEntry + 0x00UL) != 0x8fc20004U ||
            _memory.Read32(loopEntry + 0x04UL) != 0x8fb50054U ||
            _memory.Read32(loopEntry + 0x08UL) != 0x54400001U ||
            _memory.Read32(loopEntry + 0x0cUL) != 0x32b500aaU ||
            _memory.Read32(loopEntry + 0x10UL) != 0x0160902dU ||
            _memory.Read32(loopEntry + 0x14UL) != 0x0180b02dU ||
            _memory.Read32(loopEntry + 0x18UL) != 0x03c0b82dU ||
            _memory.Read32(loopEntry + 0x1cUL) != 0x8e510000U ||
            _memory.Read32(loopEntry + 0x38UL) != 0x8c700008U ||
            _memory.Read32(loopEntry + 0xe8UL) != 0x8c440010U ||
            _memory.Read32(loopEntry + 0x16cUL) != 0x258c00c8U ||
            _memory.Read32(loopEntry + 0x170UL) != 0x25080001U ||
            _memory.Read32(loopEntry + 0x174UL) != 0x2d02000dU ||
            _memory.Read32(loopEntry + 0x178UL) != 0x1440ffa1U ||
            _memory.Read32(loopEntry + 0x17cUL) != 0x256b0008U ||
            _memory.Read32(epilogue + 0x00UL) != 0x8fbf004cU ||
            _memory.Read32(epilogue + 0x28UL) != 0x0120102dU ||
            _memory.Read32(epilogue + 0x2cUL) != 0x03e00008U ||
            _memory.Read32(epilogue + 0x30UL) != 0x27bd0050U)
        {
            return false;
        }

        ulong sp = _gpr[29];
        if (!IsMainRamRange(sp + 0x54UL, 4UL))
            return false;

        ulong t0 = _gpr[8] & 0xffffffffUL;
        ulong t1 = _gpr[9] & 0xffffffffUL;
        ulong t2 = _gpr[10];
        ulong t3 = _gpr[11];
        ulong t4 = _gpr[12] & 0xffffffffUL;
        ulong t5 = _gpr[13];
        ulong s8 = _gpr[30];
        ulong s2 = _gpr[18];
        ulong s6 = _gpr[22];
        ulong s7 = _gpr[23];
        uint s0 = (uint)_gpr[16];
        uint s1 = (uint)_gpr[17];
        uint s3 = (uint)_gpr[19];
        uint s4 = (uint)_gpr[20];
        uint s5 = (uint)_gpr[21];
        uint v0 = (uint)_gpr[2];
        uint v1 = (uint)_gpr[3];
        var writes = new Dictionary<ulong, uint>();
        ulong skipped = 0;

        uint ReadOverlay32(ulong address)
            => writes.TryGetValue(address, out uint value) ? value : _memory.Read32(address);

        void WriteOverlay32(ulong address, uint value)
            => writes[address] = value;

        while (t1 == 0 && t0 < 13UL && skipped < 4096UL)
        {
            if (!IsMainRamRange(s8 + 0x04UL, 4UL) ||
                !IsMainRamRange(t3, 8UL))
            {
                return false;
            }

            v0 = _memory.Read32(s8 + 0x04UL);
            s5 = _memory.Read32(sp + 0x54UL);
            if (v0 != 0)
                s5 &= 0xaau;

            s2 = t3;
            s6 = t4;
            s7 = s8;

            bool repeatEntry;
            int entryRepeats = 0;
            do
            {
                repeatEntry = false;
                if (!IsMainRamRange(s2, 8UL))
                    return false;

                s1 = ReadOverlay32(s2 + 0x00UL);
                if ((int)s1 >= 16)
                    return false;

                ulong tableEntry = t2 + s6 + (ulong)s1 * 12UL;
                if (!IsMainRamRange(tableEntry + 0x10UL, 4UL))
                    return false;

                s0 = ReadOverlay32(tableEntry + 0x08UL);
                s3 = (s0 >> 15) & 1u;
                s4 = (s0 >> 14) & 1u;
                s0 &= 0xffff7fffu;

                bool intersects = (s5 & s0) != 0;
                bool useCountdownPath = s5 == s0 || (s3 != 0 && intersects) || (s4 != 0 && intersects);
                if (useCountdownPath)
                {
                    uint limit = ReadOverlay32(tableEntry + 0x10UL);
                    if (limit == 0xffffffffu)
                    {
                        t1 = ReadOverlay32(s7 + 0x00UL);
                        break;
                    }

                    uint counter = ReadOverlay32(s2 + 0x04UL) + 1u;
                    WriteOverlay32(s2 + 0x04UL, counter);
                    uint effectiveLimit = limit != 0 ? limit : 6u;
                    if (counter > effectiveLimit)
                    {
                        WriteOverlay32(s2 + 0x00UL, 0);
                        WriteOverlay32(s2 + 0x04UL, 0);
                    }
                }
                else
                {
                    uint counter = ReadOverlay32(s2 + 0x04UL);
                    uint limit = ReadOverlay32(tableEntry + 0x0cUL);
                    if (counter < limit)
                    {
                        WriteOverlay32(s2 + 0x00UL, 0);
                        WriteOverlay32(s2 + 0x04UL, 0);
                    }
                    else
                    {
                        uint nextState = ReadOverlay32(s2 + 0x00UL) + 1u;
                        WriteOverlay32(s2 + 0x04UL, 0);
                        WriteOverlay32(s2 + 0x00UL, nextState);
                        repeatEntry = true;
                    }
                }

                skipped += 48UL;
            } while (repeatEntry && ++entryRepeats < 64);

            if (entryRepeats >= 64)
                return false;

            s8 += 0xc8UL;
            if (t1 != 0)
                break;

            t4 += 0xc8UL;
            t0++;
            t3 += 8UL;
            skipped += 8UL;
        }

        if (t1 != 0 || t0 < 13UL)
            return false;

        foreach (KeyValuePair<ulong, uint> write in writes)
        {
            if (!IsMainRamRange(write.Key, 4UL))
                return false;
            _memory.Write32(write.Key, write.Value);
        }

        _gpr[2] = v0;
        _gpr[3] = v1;
        _gpr[8] = t0;
        _gpr[9] = t1;
        _gpr[10] = t2;
        _gpr[11] = t3;
        _gpr[12] = t4;
        _gpr[13] = t5;
        _gpr[16] = SignExtend32(s0);
        _gpr[17] = SignExtend32(s1);
        _gpr[18] = s2;
        _gpr[19] = s3;
        _gpr[20] = s4;
        _gpr[21] = SignExtend32(s5);
        _gpr[22] = s6;
        _gpr[23] = s7;
        _gpr[30] = s8;
        _gpr[0] = 0;
        AdvanceCp0Count(_cp0CountStep * Math.Max(1UL, skipped));
        _instructionCounter += Math.Max(1UL, skipped);
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = epilogue;

        if (_runtimeDiagnosticMenuScanFastPathTraceCount++ < 8)
        {
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] diagnostic-menu-scan pc={pc:x16} " +
                $"writes={writes.Count} skipped={skipped} t0={t0} s8={s8:x16}");
        }

        return true;
    }

    private bool TryFastPathKnownRuntimeDiagnosticStateZeroMask(ulong pc)
    {
        const ulong loopEntry = 0xffffffff80019d20UL;
        const ulong loopExit = 0xffffffff80019dbcUL;
        if (!_experimentRuntimeDiagnosticStateZeroMaskFastPath || pc != loopEntry)
            return false;

        if (_memory.Read32(loopEntry + 0x00UL) != 0x8dc20000U ||
            _memory.Read32(loopEntry + 0x04UL) != 0x240f0001U ||
            _memory.Read32(loopEntry + 0x08UL) != 0x010f4804U ||
            _memory.Read32(loopEntry + 0x0cUL) != 0x00491024U ||
            _memory.Read32(loopEntry + 0x10UL) != 0x1040001aU ||
            _memory.Read32(loopEntry + 0x14UL) != 0x00f72821U ||
            _memory.Read32(loopEntry + 0x7cUL) != 0x00eb1021U ||
            _memory.Read32(loopEntry + 0x80UL) != 0xac400000U ||
            _memory.Read32(loopEntry + 0x84UL) != 0x00f71021U ||
            _memory.Read32(loopEntry + 0x88UL) != 0xac400000U ||
            _memory.Read32(loopEntry + 0x8cUL) != 0x25080001U ||
            _memory.Read32(loopEntry + 0x90UL) != 0x2902000cU ||
            _memory.Read32(loopEntry + 0x94UL) != 0x1440ffdaU ||
            _memory.Read32(loopEntry + 0x98UL) != 0x24e70004U)
        {
            return false;
        }

        ulong t0 = _gpr[8] & 0xffffffffUL;
        ulong a3 = _gpr[7] & 0xffffffffUL;
        ulong t3 = _gpr[11];
        ulong t6 = _gpr[14];
        ulong s7 = _gpr[23];
        if (t0 >= 12UL || a3 != t0 * 4UL)
            return false;
        if (!IsMainRamRange(t6, 4UL))
            return false;

        uint mask = _memory.Read32(t6);
        if (mask != 0)
            return false;

        ulong remaining = 12UL - t0;
        if (!IsMainRamRange(t3 + a3, remaining * 4UL) ||
            !IsMainRamRange(s7 + a3, remaining * 4UL))
        {
            return false;
        }

        ulong offset = a3;
        for (ulong i = t0; i < 12UL; i++)
        {
            _memory.Write32(t3 + offset, 0);
            _memory.Write32(s7 + offset, 0);
            offset += 4UL;
        }

        _gpr[2] = 0;
        _gpr[7] = offset;
        _gpr[8] = 12;
        _gpr[9] = 0x800;
        _gpr[15] = 1;
        _gpr[0] = 0;
        ulong skipped = remaining * 8UL;
        AdvanceCp0Count(_cp0CountStep * Math.Max(1UL, skipped));
        _instructionCounter += Math.Max(1UL, skipped);
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = loopExit;

        if (_runtimeDiagnosticStateZeroMaskFastPathTraceCount++ < 8)
        {
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] diagnostic-state-zero-mask pc={pc:x16} " +
                $"remaining={remaining} t3={t3:x16} s7={s7:x16}");
        }

        return true;
    }

    private bool TryFastPathKnownRuntimeSchedulerCallbackEnqueue(ulong pc)
    {
        const ulong entry = 0xffffffff8003aaacUL;
        const ulong node = 0xffffffff800a74b8UL;
        const ulong listHead = 0xffffffff800b2f60UL;
        const uint callback = 0x8003aa04U;
        if (!_enableBootCountDelay || pc != entry)
            return false;

        if (_memory.Read32(entry + 0x00UL) != 0x27bdffe8U ||
            _memory.Read32(entry + 0x04UL) != 0x3c04800aU ||
            _memory.Read32(entry + 0x08UL) != 0x248474b8U ||
            _memory.Read32(entry + 0x0cUL) != 0x3c028004U ||
            _memory.Read32(entry + 0x10UL) != 0x2442aa04U ||
            _memory.Read32(entry + 0x14UL) != 0xafbf0010U ||
            _memory.Read32(entry + 0x18UL) != 0x0c005140U ||
            _memory.Read32(entry + 0x1cUL) != 0xac820008U ||
            _memory.Read32(entry + 0x20UL) != 0x8fbf0010U ||
            _memory.Read32(entry + 0x24UL) != 0x03e00008U ||
            _memory.Read32(entry + 0x28UL) != 0x27bd0018U)
        {
            return false;
        }

        if (!IsMainRamRange(node, 0x20UL) || !IsMainRamRange(listHead, 0x10UL))
            return false;

        ulong returnAddress = _gpr[31];
        ulong returnOffset = returnAddress & 0x1fffffffUL;
        if (returnOffset is < 0x00010000UL or > 0x00100000UL)
            return false;

        uint currentHead = _memory.Read32(listHead);
        if (currentHead != 0 && currentHead != unchecked((uint)node))
