    private bool TryFastPathKnownRuntimeBitfieldUpdate(ulong pc)
    {
        const ulong entry = 0xffffffff800eafdcUL;
        const ulong midBody = 0xffffffff800eb020UL;

        bool atEntry = pc == entry;
        bool atMidBody = pc == midBody;
        if (!atEntry && !atMidBody)
            return false;

        if (_memory.Read32(entry) != 0x0080302dU ||
            _memory.Read32(entry + 0x04UL) != 0x8cc20000U ||
            _memory.Read32(entry + 0x08UL) != 0x8cc40008U ||
            _memory.Read32(entry + 0x0cUL) != 0x8cc3000cU ||
            _memory.Read32(entry + 0x10UL) != 0xacc50000U ||
            _memory.Read32(entry + 0x14UL) != 0x00833826U ||
            _memory.Read32(entry + 0x18UL) != 0x00451026U ||
            _memory.Read32(entry + 0x1cUL) != 0x00022027U ||
            _memory.Read32(entry + 0x20UL) != 0x00a42824U ||
            _memory.Read32(entry + 0x24UL) != 0x8cc30004U ||
            _memory.Read32(entry + 0x28UL) != 0x8cc40010U ||
            _memory.Read32(entry + 0x2cUL) != 0x00431024U ||
            _memory.Read32(entry + 0x30UL) != 0x00451825U ||
            _memory.Read32(entry + 0x34UL) != 0x00e33824U ||
            _memory.Read32(entry + 0x38UL) != 0x00441024U ||
            _memory.Read32(entry + 0x3cUL) != 0x1440000fU ||
            _memory.Read32(entry + 0x40UL) != 0xacc30004U ||
            _memory.Read32(entry + 0x44UL) != 0x00641024U ||
            _memory.Read32(entry + 0x48UL) != 0x1040000cU ||
            _memory.Read32(entry + 0x7cUL) != 0x94c20016U ||
            _memory.Read32(entry + 0x80UL) != 0xa4c20014U ||
            _memory.Read32(entry + 0x84UL) != 0x8cc2000cU ||
            _memory.Read32(entry + 0x88UL) != 0x00471026U ||
            _memory.Read32(entry + 0x8cUL) != 0xacc20008U ||
            _memory.Read32(entry + 0x90UL) != 0x8cc20004U ||
            _memory.Read32(entry + 0x94UL) != 0x03e00008U ||
            _memory.Read32(entry + 0x98UL) != 0x00000000U)
        {
            return false;
        }

        ulong record = atEntry ? _gpr[4] : _gpr[6];
        ulong returnAddress = _gpr[31];
        ulong returnOffset = returnAddress & 0x1fffffffUL;
        if (!IsMainRamRange(record, 0x1cUL) ||
            returnOffset is < 0x000e0000UL or > 0x000ec000UL)
        {
            return false;
        }

        uint a0;
        uint v1;
        uint a3;
        if (atEntry)
        {
            uint newValue = (uint)_gpr[5];
            uint oldValue = _memory.Read32(record);
            uint oldBits = _memory.Read32(record + 0x08UL);
            uint sourceBits = _memory.Read32(record + 0x0cUL);
            _memory.Write32(record, newValue);

            a3 = oldBits ^ sourceBits;
            uint toggled = oldValue ^ newValue;
            a0 = ~toggled;
            uint unchangedNewBits = newValue & a0;
            uint maskedToggle = toggled & _memory.Read32(record + 0x04UL);
            v1 = maskedToggle | unchangedNewBits;
            a3 &= v1;
            uint delayedBits = maskedToggle & _memory.Read32(record + 0x10UL);
            _memory.Write32(record + 0x04UL, v1);
            if (delayedBits != 0)
                return false;
        }
        else
        {
            a0 = (uint)_gpr[4];
            v1 = (uint)_gpr[3];
            a3 = (uint)_gpr[7];
        }

        uint activeBits = v1 + a0;
        if (activeBits != 0)
        {
            ushort countdown = (ushort)(_memory.Read16(record + 0x14UL) - 1);
            _memory.Write16(record + 0x14UL, countdown);
            if (countdown == 0)
            {
                a3 &= ~a0;
                _memory.Write16(record + 0x14UL, _memory.Read16(record + 0x18UL));
            }
        }
        else
        {
            _memory.Write16(record + 0x14UL, _memory.Read16(record + 0x16UL));
        }

        uint nextBits = _memory.Read32(record + 0x0cUL) ^ a3;
        _memory.Write32(record + 0x08UL, nextBits);
        uint result = _memory.Read32(record + 0x04UL);

        _gpr[2] = result;
        _gpr[3] = v1;
        _gpr[4] = a0;
        _gpr[6] = record;
        _gpr[7] = a3;
        Pc = returnAddress;
        CompleteFastPathStep();
        return true;
    }

    private bool TryFastPathKnownRuntimeStatusBitfieldRead(ulong pc)
    {
        const ulong entry = 0xffffffff800eb834UL;
        const ulong wrapper = 0xffffffff800eb8a4UL;
        const ulong table = 0xffffffff80262b90UL;

        bool atEntry = pc == entry;
        bool atWrapper = pc == wrapper;
        if (!atEntry && !atWrapper)
            return false;

        if (_memory.Read32(entry + 0x00UL) != 0x2c820007U ||
            _memory.Read32(entry + 0x04UL) != 0x14400003U ||
            _memory.Read32(entry + 0x08UL) != 0x000418c0U ||
            _memory.Read32(entry + 0x14UL) != 0x00641823U ||
            _memory.Read32(entry + 0x18UL) != 0x00031880U ||
            _memory.Read32(entry + 0x1cUL) != 0x3c028026U ||
            _memory.Read32(entry + 0x20UL) != 0x24422b90U ||
            _memory.Read32(entry + 0x24UL) != 0x00623821U ||
            _memory.Read32(entry + 0x28UL) != 0x8ce80008U ||
            _memory.Read32(entry + 0x2cUL) != 0x8ce3000cU ||
            _memory.Read32(entry + 0x30UL) != 0x8ce40004U ||
            _memory.Read32(entry + 0x34UL) != 0x8ce20000U ||
            _memory.Read32(entry + 0x38UL) != 0x01033026U ||
            _memory.Read32(entry + 0x3cUL) != 0x10a0000aU ||
            _memory.Read32(entry + 0x40UL) != 0x00822025U ||
            _memory.Read32(entry + 0x44UL) != 0x00061827U ||
            _memory.Read32(entry + 0x48UL) != 0x00641824U ||
            _memory.Read32(entry + 0x4cUL) != 0x00651824U ||
            _memory.Read32(entry + 0x50UL) != 0x00c33025U ||
            _memory.Read32(entry + 0x54UL) != 0x01061026U ||
            _memory.Read32(entry + 0x58UL) != 0xace2000cU ||
            _memory.Read32(entry + 0x5cUL) != 0x00051027U ||
            _memory.Read32(entry + 0x60UL) != 0x00821024U ||
            _memory.Read32(entry + 0x64UL) != 0x00432025U ||
            _memory.Read32(entry + 0x68UL) != 0x03e00008U ||
            _memory.Read32(entry + 0x6cUL) != 0x0080102dU ||
            _memory.Read32(wrapper + 0x00UL) != 0x27bdffe8U ||
            _memory.Read32(wrapper + 0x04UL) != 0x0080282dU ||
            _memory.Read32(wrapper + 0x08UL) != 0xafbf0010U ||
            _memory.Read32(wrapper + 0x0cUL) != 0x0c03ae0dU ||
            _memory.Read32(wrapper + 0x10UL) != 0x24040005U ||
            _memory.Read32(wrapper + 0x14UL) != 0x8fbf0010U ||
            _memory.Read32(wrapper + 0x18UL) != 0x03e00008U ||
            _memory.Read32(wrapper + 0x1cUL) != 0x27bd0018U)
        {
            return false;
        }

        uint index = atWrapper ? 5u : (uint)_gpr[4];
        uint mask = atWrapper ? (uint)_gpr[4] : (uint)_gpr[5];
        ulong returnAddress = _gpr[31];
        if (atWrapper)
        {
            ulong returnOffset = returnAddress & 0x1fffffffUL;
            if (returnOffset is < 0x000c0000UL or > 0x00110000UL)
                return false;

            // The runtime scheduler expects this tick/event bit to pulse; without
            // it the diagnostic menu parks in the "IS STUCK" wait loop.
            if (returnOffset == 0x000cda70UL && mask == 0x00140000u)
            {
                _gpr[2] = SignExtend32(mask);
                _gpr[3] = 0;
                _gpr[4] = mask;
                _gpr[5] = mask;
                _gpr[6] = mask;
                _gpr[7] = table + 5UL * 28UL;
                _gpr[8] = 0;
                _gpr[0] = 0;
                Pc = returnAddress;
                CompleteFastPathStep();
                return true;
            }
        }

        if (index >= 7u)
        {
            _gpr[2] = 0;
            _gpr[0] = 0;
            Pc = returnAddress;
            CompleteFastPathStep();
            return true;
        }

        ulong record = table + index * 28UL;
        if (!IsMainRamRange(record, 0x10UL))
            return false;

        uint oldBits = _memory.Read32(record + 0x08UL);
        uint sourceBits = _memory.Read32(record + 0x0cUL);
        uint combined = _memory.Read32(record + 0x04UL) | _memory.Read32(record);
        uint changed = oldBits ^ sourceBits;
        uint result;

        if (mask == 0)
        {
            result = combined;
        }
        else
        {
            uint selected = ~changed & combined & mask;
            _memory.Write32(record + 0x0cUL, oldBits ^ (changed | selected));
            result = (~mask & combined) | selected;
        }

        if (_traceRuntimeStatusBitfieldRead && _runtimeStatusBitfieldReadTraceCount++ < 128)
        {
            Console.WriteLine(
                $"[GAUNTDL:STATUSBIT] pc={pc:x16} index={index} mask={mask:x8} " +
                $"record={record:x16} value={_memory.Read32(record):x8} latch={_memory.Read32(record + 0x04UL):x8} " +
                $"old={oldBits:x8} source={sourceBits:x8} changed={changed:x8} combined={combined:x8} result={result:x8} " +
                $"ra={returnAddress:x16}");
        }

        _gpr[2] = SignExtend32(result);
        _gpr[3] = changed;
        _gpr[4] = combined;
        _gpr[5] = mask;
        _gpr[6] = changed | (~changed & combined & mask);
        _gpr[7] = record;
        _gpr[8] = SignExtend32(oldBits);
        _gpr[0] = 0;
        Pc = returnAddress;
        CompleteFastPathStep();
        return true;
    }

    private bool TryFastPathKnownRuntimeInputPoll(ulong pc)
    {
        const ulong entry = 0xffffffff800eb078UL;
        if (!_enableBootCountDelay || pc != entry)
            return false;

        if (_memory.Read32(entry + 0x00UL) != 0x27bdffa0U ||
            _memory.Read32(entry + 0x04UL) != 0x3c028026U ||
            _memory.Read32(entry + 0x08UL) != 0xafb70054U ||
            _memory.Read32(entry + 0x0cUL) != 0x24572b90U ||
            _memory.Read32(entry + 0x10UL) != 0x3c03a4a0U ||
            _memory.Read32(entry + 0x14UL) != 0x3463000cU ||
            _memory.Read32(entry + 0x18UL) != 0x3c02a4a0U ||
            _memory.Read32(entry + 0x1cUL) != 0x3442000aU ||
            _memory.Read32(entry + 0x20UL) != 0x3c04a4a0U ||
            _memory.Read32(entry + 0x24UL) != 0x3484000eU ||
            _memory.Read32(entry + 0x28UL) != 0x3c06a4a0U ||
            _memory.Read32(entry + 0x2cUL) != 0x34c60008U ||
            _memory.Read32(entry + 0x30UL) != 0x24070001U ||
            _memory.Read32(entry + 0x34UL) != 0xafbf005cU ||
            _memory.Read32(0xffffffff800eb780UL) != 0x8fbf005cU ||
            _memory.Read32(0xffffffff800eb7a8UL) != 0x03e00008U ||
            _memory.Read32(0xffffffff800eb7acUL) != 0x27bd0060U)
        {
            return false;
        }

        ulong returnAddress = _gpr[31];
        ulong returnOffset = returnAddress & 0x1fffffffUL;
        if (returnOffset is < 0x000e0000UL or > 0x000e3000UL)
            return false;

        // Bringup-only: this runtime helper polls the A4A0 input ports and
        // fans the result into the debounced bitfield table at 0x80262b90.
        // The IOASIC shuffle is active here, so use the logical input bridge
        // instead of letting the guest re-read packed ports.
        _memory.RecordRuntimeInputPollEffects();

        _gpr[2] = 0;
        _gpr[3] = 0;
        _gpr[0] = 0;
        AdvanceCp0Count(_cp0CountStep * 32UL);
        _instructionCounter += 32UL;
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = returnAddress;
        return true;
    }

    private bool TryFastPathKnownRuntimeLowBitfieldUpdate(ulong pc)
    {
        const ulong entry = 0xffffffff8001fa20UL;
        if (pc != entry)
            return false;

        if (_memory.Read32(entry + 0x00UL) != 0x0080302dU ||
            _memory.Read32(entry + 0x04UL) != 0x8cc30000U ||
            _memory.Read32(entry + 0x08UL) != 0x8cc20004U ||
            _memory.Read32(entry + 0x0cUL) != 0xacc50000U ||
            _memory.Read32(entry + 0x10UL) != 0x00651826U ||
            _memory.Read32(entry + 0x14UL) != 0x00032027U ||
            _memory.Read32(entry + 0x18UL) != 0x00621824U ||
            _memory.Read32(entry + 0x1cUL) != 0x00a42824U ||
            _memory.Read32(entry + 0x20UL) != 0x8cc20008U ||
            _memory.Read32(entry + 0x24UL) != 0x8cc4000cU ||
            _memory.Read32(entry + 0x28UL) != 0x00652825U ||
            _memory.Read32(entry + 0x2cUL) != 0xacc50004U ||
            _memory.Read32(entry + 0x30UL) != 0x00451024U ||
            _memory.Read32(entry + 0x34UL) != 0x00641824U ||
            _memory.Read32(entry + 0x38UL) != 0x14600013U ||
            _memory.Read32(entry + 0x3cUL) != 0xacc20008U ||
            _memory.Read32(entry + 0x40UL) != 0x00a0102dU ||
            _memory.Read32(entry + 0x44UL) != 0x00441024U ||
            _memory.Read32(entry + 0x48UL) != 0x1040000fU ||
            _memory.Read32(entry + 0x50UL) != 0x94c20010U ||
            _memory.Read32(entry + 0x54UL) != 0x2442ffffU ||
            _memory.Read32(entry + 0x58UL) != 0xa4c20010U ||
            _memory.Read32(entry + 0x5cUL) != 0x3042ffffU ||
            _memory.Read32(entry + 0x60UL) != 0x1440000bU ||
            _memory.Read32(entry + 0x68UL) != 0x94c20014U ||
            _memory.Read32(entry + 0x6cUL) != 0x8cc30008U ||
            _memory.Read32(entry + 0x70UL) != 0xa4c20010U ||
            _memory.Read32(entry + 0x74UL) != 0x0080102dU ||
            _memory.Read32(entry + 0x78UL) != 0x00021027U ||
            _memory.Read32(entry + 0x7cUL) != 0x00621824U ||
            _memory.Read32(entry + 0x80UL) != 0x08007eacU ||
            _memory.Read32(entry + 0x84UL) != 0xacc30008U ||
            _memory.Read32(entry + 0x88UL) != 0x94c20012U ||
            _memory.Read32(entry + 0x8cUL) != 0xa4c20010U ||
            _memory.Read32(entry + 0x90UL) != 0x8cc20004U ||
            _memory.Read32(entry + 0x94UL) != 0x03e00008U ||
            _memory.Read32(entry + 0x98UL) != 0x00000000U)
        {
            return false;
        }

        ulong record = _gpr[4];
        ulong returnAddress = _gpr[31];
        ulong returnOffset = returnAddress & 0x1fffffffUL;
        if (!IsMainRamRange(record, 0x18UL) ||
            returnOffset is < 0x0001f000UL or > 0x00020000UL)
        {
            return false;
        }

        uint newValue = (uint)_gpr[5];
        uint oldValue = _memory.Read32(record);
        uint oldLatch = _memory.Read32(record + 0x04UL);
        uint sourceMask = _memory.Read32(record + 0x0cUL);
        _memory.Write32(record, newValue);

        uint toggled = oldValue ^ newValue;
        uint unchangedMask = ~toggled;
        uint maskedToggle = toggled & oldLatch;
        uint nextLatch = maskedToggle | (newValue & unchangedMask);
        _memory.Write32(record + 0x04UL, nextLatch);

        uint nextBits = _memory.Read32(record + 0x08UL) & nextLatch;
        uint delayedBits = maskedToggle & sourceMask;
        _memory.Write32(record + 0x08UL, nextBits);

        if (delayedBits == 0)
        {
            if ((nextLatch & sourceMask) != 0)
            {
                ushort countdown = (ushort)(_memory.Read16(record + 0x10UL) - 1);
                _memory.Write16(record + 0x10UL, countdown);
                if (countdown == 0)
                {
                    _memory.Write16(record + 0x10UL, _memory.Read16(record + 0x14UL));
                    nextBits &= ~sourceMask;
                    _memory.Write32(record + 0x08UL, nextBits);
                }
            }
            else
            {
                _memory.Write16(record + 0x10UL, _memory.Read16(record + 0x12UL));
            }
        }

        uint result = _memory.Read32(record + 0x04UL);
        _gpr[2] = SignExtend32(result);
        _gpr[3] = maskedToggle;
        _gpr[4] = sourceMask;
        _gpr[5] = nextLatch;
        _gpr[6] = record;
        _gpr[0] = 0;
        Pc = returnAddress;
        CompleteFastPathStep();
        return true;
    }

    private bool TryFastPathKnownRuntimeLowIoasicInputPoll(ulong pc)
    {
        const ulong entry = 0xffffffff8001fabcUL;
        bool atEntry = pc == entry;
        if (!atEntry && pc is (< 0xffffffff8001fac0UL or > 0xffffffff8001fb44UL))
            return false;

        if (_memory.Read32(entry + 0x00UL) != 0x27bdffe8U ||
            _memory.Read32(entry + 0x04UL) != 0xafb00010U ||
            _memory.Read32(entry + 0x08UL) != 0x3c10800bU ||
            _memory.Read32(entry + 0x0cUL) != 0x8e022e50U ||
            _memory.Read32(entry + 0x10UL) != 0x1440001aU ||
            _memory.Read32(entry + 0x14UL) != 0xafbf0014U ||
            _memory.Read32(entry + 0x18UL) != 0x3c03a180U ||
            _memory.Read32(entry + 0x1cUL) != 0x3463000eU ||
            _memory.Read32(entry + 0x20UL) != 0x3c02a180U ||
            _memory.Read32(entry + 0x24UL) != 0x34420008U ||
            _memory.Read32(entry + 0x28UL) != 0x3c04800bU ||
            _memory.Read32(entry + 0x2cUL) != 0x94630000U ||
            _memory.Read32(entry + 0x30UL) != 0x94450000U ||
            _memory.Read32(entry + 0x34UL) != 0x24843020U ||
            _memory.Read32(entry + 0x38UL) != 0x00052c00U ||
            _memory.Read32(entry + 0x3cUL) != 0x0c007e88U ||
            _memory.Read32(entry + 0x40UL) != 0x00a32827U ||
            _memory.Read32(entry + 0x44UL) != 0x3c03a180U ||
            _memory.Read32(entry + 0x48UL) != 0x3463000cU ||
            _memory.Read32(entry + 0x4cUL) != 0x3c02a180U ||
            _memory.Read32(entry + 0x50UL) != 0x3442000aU ||
            _memory.Read32(entry + 0x54UL) != 0x3c04800bU ||
            _memory.Read32(entry + 0x58UL) != 0x94630000U ||
            _memory.Read32(entry + 0x5cUL) != 0x94450000U ||
            _memory.Read32(entry + 0x60UL) != 0x24843040U ||
            _memory.Read32(entry + 0x64UL) != 0x00052c00U ||
            _memory.Read32(entry + 0x68UL) != 0x0c007e88U ||
            _memory.Read32(entry + 0x6cUL) != 0x00a32827U ||
            _memory.Read32(entry + 0x70UL) != 0x3c03800bU ||
            _memory.Read32(entry + 0x74UL) != 0x08007edbU ||
            _memory.Read32(entry + 0x78UL) != 0xac622e4cU ||
            _memory.Read32(entry + 0xb0UL) != 0x8fbf0014U ||
            _memory.Read32(entry + 0xb4UL) != 0x8fb00010U ||
            _memory.Read32(entry + 0xb8UL) != 0x03e00008U ||
            _memory.Read32(entry + 0xbcUL) != 0x27bd0018U)
        {
            return false;
        }

        if (_memory.Read32(0xffffffff800b2e50UL) != 0 ||
            !IsMainRamRange(0xffffffff800b3020UL, 28UL) ||
            !IsMainRamRange(0xffffffff800b3040UL, 28UL))
        {
            return false;
        }

        if (_memory.Read32(0xffffffff800b3020UL) != 0x80000000u ||
            _memory.Read32(0xffffffff800b3040UL) != 0)
        {
            return false;
        }

        UpdateRuntimeStatusBitfieldRecord(0xffffffff800b3020UL, 0x80000000u);
        UpdateRuntimeStatusBitfieldRecord(0xffffffff800b3040UL, 0);
        _memory.Write32(0xffffffff800b2e4cUL, 0);

        ulong sp = _gpr[29];
        if (!atEntry && !IsMainRamRange(sp + 0x18UL, 4))
            return false;

        ulong returnAddress = atEntry ? _gpr[31] : SignExtend32(_memory.Read32(sp + 0x14UL));
        ulong returnOffset = returnAddress & 0x1fffffffUL;
        if (returnOffset is < 0x00010000UL or > 0x00110000UL)
            return false;

        _gpr[2] = 0;
        _gpr[3] = 0xffffffff800b0000UL;
        _gpr[4] = 0;
        _gpr[5] = 0;
        if (!atEntry)
        {
            _gpr[16] = SignExtend32(_memory.Read32(sp + 0x10UL));
            _gpr[29] = sp + 0x18UL;
        }
        _gpr[31] = returnAddress;
        _gpr[0] = 0;
        AdvanceCp0Count(_cp0CountStep * 96UL);
        _instructionCounter += 96UL;
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = returnAddress;
        return true;
    }

    private bool TryFastPathKnownRuntimeDwordCopyTail(ulong pc)
    {
        const ulong loop = 0xffffffff800d1380UL;
        const ulong store = 0xffffffff800d138cUL;
        if (pc != loop && pc != store)
            return false;

        if (_memory.Read32(loop) != 0x2508ffffU ||
            _memory.Read32(loop + 0x04UL) != 0xdca90000U ||
            _memory.Read32(loop + 0x08UL) != 0x24a50008U ||
            _memory.Read32(loop + 0x0cUL) != 0xfc890000U ||
            _memory.Read32(loop + 0x10UL) != 0x1d00fffbU ||
            _memory.Read32(loop + 0x14UL) != 0x24840008U ||
            _memory.Read32(loop + 0x18UL) != 0x1000ffd3U ||
            _memory.Read32(loop + 0x1cUL) != 0x00000000U)
        {
            return false;
        }

        long counter = unchecked((long)_gpr[8]);
        ulong destination = _gpr[4];
        ulong source = _gpr[5];
        ulong copied = 0;
        ulong lastValue;

        if (pc == store)
        {
            long extraCopies = Math.Max(counter, 0);
            if (extraCopies > 0x80000)
                return false;
            ulong extraBytes = (ulong)extraCopies * 8UL;
            ulong totalBytes = extraBytes + 8UL;
            if (totalBytes > 0x00400000UL ||
                !IsMainRamRange(destination, totalBytes) ||
                (extraBytes != 0 && !IsMainRamRange(source, extraBytes)))
            {
                return false;
            }

            lastValue = _gpr[9];
            _memory.Write64(destination, lastValue);
            destination += 8UL;
            copied += 8UL;
            for (ulong offset = 0; offset < extraBytes; offset += 8UL)
            {
                lastValue = _memory.Read64(source + offset);
                _memory.Write64(destination + offset, lastValue);
            }
            source += extraBytes;
            destination += extraBytes;
            _gpr[8] = counter > 0 ? 0UL : unchecked((ulong)counter);
        }
        else
        {
            if (counter <= 0 || counter > 0x80000)
                return false;

            ulong bytes = (ulong)counter * 8UL;
            if (bytes > 0x00400000UL ||
                !IsMainRamRange(source, bytes) ||
                !IsMainRamRange(destination, bytes))
            {
                return false;
            }

            lastValue = 0;
            for (ulong offset = 0; offset < bytes; offset += 8UL)
            {
                lastValue = _memory.Read64(source + offset);
                _memory.Write64(destination + offset, lastValue);
            }
            source += bytes;
            destination += bytes;
            copied = bytes;
            _gpr[8] = 0;
        }

        if (copied != 0)
            _gpr[9] = lastValue;
        _gpr[4] = destination;
        _gpr[5] = source;
        Pc = 0xffffffff800d12e8UL;
        CompleteFastPathStep();
        return true;
    }

    private bool TryFastPathKnownRuntimeVertexFifoEmit(ulong pc)
    {
        const ulong entry = 0xffffffff800c4e5cUL;
        const ulong unalignedBody = 0xffffffff800c4e64UL;
        const ulong alignedBody = 0xffffffff800c4f0cUL;
        if (!_enableRuntimeVertexFifoEmitFastPath || pc != entry)
            return false;
        if (_hasPendingBranch)
            return TraceVertexFifoFastPathReject("pending-branch");

        if (_memory.Read32(entry + 0x00UL) != 0x1160002bU ||
            _memory.Read32(entry + 0x04UL) != 0xad09037cU ||
            _memory.Read32(unalignedBody + 0x00UL) != 0x3c0c0180U ||
            _memory.Read32(unalignedBody + 0x04UL) != 0x358ca8cbU ||
            _memory.Read32(unalignedBody + 0x08UL) != 0xad4c0000U ||
            _memory.Read32(unalignedBody + 0x0cUL) != 0xdc8c0000U ||
            _memory.Read32(unalignedBody + 0x9cUL) != 0x214a004cU ||
            _memory.Read32(unalignedBody + 0xa0UL) != 0x03e00008U ||
            _memory.Read32(unalignedBody + 0xa4UL) != 0xad0a0374U ||
            _memory.Read32(alignedBody + 0x00UL) != 0x3c0c0180U ||
            _memory.Read32(alignedBody + 0x04UL) != 0x358ca8cbU ||
            _memory.Read32(alignedBody + 0xbcUL) != 0xad4c0048U ||
            _memory.Read32(alignedBody + 0xc0UL) != 0x214a004cU ||
            _memory.Read32(alignedBody + 0xc4UL) != 0x03e00008U ||
            _memory.Read32(alignedBody + 0xc8UL) != 0xad0a0374U)
        {
            return TraceVertexFifoFastPathReject("signature");
        }

        ulong context = _gpr[8];
        ulong destination = _gpr[10];
        ulong source0 = _gpr[4];
        ulong source1 = _gpr[5];
        ulong source2 = _gpr[6];
        ulong returnAddress = _gpr[31];
        uint destinationPhysical = (uint)destination;
        ulong returnOffset = returnAddress & 0x1fffffffUL;
        if (!IsMainRamRange(context + 0x37cUL, 4) ||
            !IsMainRamRange(source0, 0x18) ||
            !IsMainRamRange(source1, 0x18) ||
            !IsMainRamRange(source2, 0x18) ||
            destinationPhysical is < 0xa8000000U or > 0xa83fffb4U ||
            returnOffset is < 0x000b0000UL or > 0x000c0000UL)
        {
            return TraceVertexFifoFastPathReject(
                $"range ctx={context:x16} dst={destination:x16} s0={source0:x16} s1={source1:x16} s2={source2:x16} ra={returnAddress:x16}");
        }

        _memory.Write32(context + 0x37cUL, unchecked((uint)_gpr[9]));
        if ((_gpr[11] & 0xffffffffUL) != 0)
        {
            _memory.Write32(destination + 0x00UL, 0x0180a8cbU);
            _memory.Write64(destination + 0x04UL, _memory.Read64(source0 + 0x00UL));
            _memory.Write64(destination + 0x0cUL, PackLwuPair(source0 + 0x08UL, source0 + 0x14UL));
            _memory.Write64(destination + 0x14UL, PackLwuPair(source0 + 0x0cUL, source0 + 0x10UL));
            _memory.Write64(destination + 0x1cUL, _memory.Read64(source1 + 0x00UL));
            _memory.Write64(destination + 0x24UL, PackLwuPair(source1 + 0x08UL, source1 + 0x14UL));
            _memory.Write64(destination + 0x2cUL, PackLwuPair(source1 + 0x0cUL, source1 + 0x10UL));
            _memory.Write64(destination + 0x34UL, _memory.Read64(source2 + 0x00UL));
            _memory.Write64(destination + 0x3cUL, PackLwuPair(source2 + 0x08UL, source2 + 0x14UL));
            _memory.Write64(destination + 0x44UL, PackLwuPair(source2 + 0x0cUL, source2 + 0x10UL));
            _gpr[12] = PackLwuPair(source2 + 0x0cUL, source2 + 0x10UL);
        }
        else
        {
            _memory.Write64(destination + 0x00UL, PackConstantAndLwu(0x0180a8cbU, source0 + 0x00UL));
            _memory.Write64(destination + 0x08UL, PackLwuPair(source0 + 0x04UL, source0 + 0x08UL));
            _memory.Write64(destination + 0x10UL, PackLwuPair(source0 + 0x14UL, source0 + 0x0cUL));
            _memory.Write64(destination + 0x18UL, PackLwuPair(source0 + 0x10UL, source1 + 0x00UL));
            _memory.Write64(destination + 0x20UL, PackLwuPair(source1 + 0x04UL, source1 + 0x08UL));
            _memory.Write64(destination + 0x28UL, PackLwuPair(source1 + 0x14UL, source1 + 0x0cUL));
            _memory.Write64(destination + 0x30UL, PackLwuPair(source1 + 0x10UL, source2 + 0x00UL));
            _memory.Write64(destination + 0x38UL, PackLwuPair(source2 + 0x04UL, source2 + 0x08UL));
            _memory.Write64(destination + 0x40UL, PackLwuPair(source2 + 0x14UL, source2 + 0x0cUL));
            _memory.Write32(destination + 0x48UL, _memory.Read32(source2 + 0x10UL));
            _gpr[12] = SignExtend32(_memory.Read32(source2 + 0x10UL));
        }

        ulong updatedDestination = destination + 0x4cUL;
        _memory.Write32(context + 0x374UL, unchecked((uint)updatedDestination));
        _gpr[10] = SignExtend32(unchecked((uint)updatedDestination));
        _gpr[13] = SignExtend32(_memory.Read32(source2 + 0x10UL));
        Pc = returnAddress;
        CompleteFastPathStep();
        return true;
    }

    private bool TraceVertexFifoFastPathReject(string reason)
    {
        if (_traceVertexFifoFastPath && _vertexFifoFastPathTraceCount++ < 32)
        {
            Console.WriteLine(
                $"[GAUNTDL:VERTEX-FIFO] reject {reason} " +
                $"pc={Pc:x16} t0={_gpr[8]:x16} t1={_gpr[9]:x16} t2={_gpr[10]:x16} t3={_gpr[11]:x16} " +
                $"a0={_gpr[4]:x16} a1={_gpr[5]:x16} a2={_gpr[6]:x16} ra={_gpr[31]:x16}");
        }

        return false;
    }

    private bool TryFastPathKnownRuntimeBgLoadModelCharWrapperFrame(ulong pc)
    {
        const ulong entry = 0xffffffff8011ce40UL;
        const ulong callee = 0xffffffff8011d590UL;
        const ulong returnFromCallee = 0xffffffff8011ce80UL;
        if (!_enableRuntimeBgLoadModelDispatchFastPath || pc is not (entry or returnFromCallee))
            return false;

        if (_memory.Read32(entry + 0x00UL) != 0x27bdffc8U ||
            _memory.Read32(entry + 0x04UL) != 0xafb00030U ||
            _memory.Read32(entry + 0x08UL) != 0x0080802dU ||
            _memory.Read32(entry + 0x0cUL) != 0x27a20028U ||
            _memory.Read32(entry + 0x10UL) != 0x24030001U ||
            _memory.Read32(entry + 0x14UL) != 0xafa20020U ||
            _memory.Read32(entry + 0x18UL) != 0x27a20020U ||
            _memory.Read32(entry + 0x1cUL) != 0x00a0202dU ||
            _memory.Read32(entry + 0x20UL) != 0x27a50010U ||
            _memory.Read32(entry + 0x24UL) != 0xafbf0034U ||
            _memory.Read32(entry + 0x28UL) != 0xa3b00028U ||
            _memory.Read32(entry + 0x2cUL) != 0xafa30018U ||
            _memory.Read32(entry + 0x30UL) != 0xafa30024U ||
            _memory.Read32(entry + 0x34UL) != 0xafa20010U ||
            _memory.Read32(entry + 0x38UL) != 0x0c047564U ||
            _memory.Read32(entry + 0x3cUL) != 0xafa30014U ||
            _memory.Read32(returnFromCallee + 0x00UL) != 0x2403ffffU ||
            _memory.Read32(returnFromCallee + 0x04UL) != 0x0202180aU ||
            _memory.Read32(returnFromCallee + 0x08UL) != 0x8fbf0034U ||
            _memory.Read32(returnFromCallee + 0x0cUL) != 0x8fb00030U ||
            _memory.Read32(returnFromCallee + 0x10UL) != 0x0060102dU ||
            _memory.Read32(returnFromCallee + 0x14UL) != 0x03e00008U ||
            _memory.Read32(returnFromCallee + 0x18UL) != 0x27bd0038U)
        {
            return false;
        }

        if (pc == entry)
        {
            if (_hasPendingBranch)
                return false;

            ulong newSp = _gpr[29] - 0x38UL;
            if (!IsMainRamRange(newSp + 0x10UL, 0x28UL))
                return false;

            ulong originalChar = _gpr[4];
            ulong originalRecord = _gpr[5];
            _memory.Write32(newSp + 0x30UL, (uint)_gpr[16]);
            _memory.Write32(newSp + 0x34UL, (uint)_gpr[31]);
            _memory.Write8(newSp + 0x28UL, (byte)originalChar);
            _memory.Write32(newSp + 0x18UL, 1);
            _memory.Write32(newSp + 0x24UL, 1);
            _memory.Write32(newSp + 0x20UL, (uint)(newSp + 0x28UL));
            _memory.Write32(newSp + 0x10UL, (uint)(newSp + 0x20UL));
            _memory.Write32(newSp + 0x14UL, 1);

            _gpr[16] = originalChar;
            _gpr[29] = newSp;
            _gpr[4] = originalRecord;
            _gpr[5] = newSp + 0x10UL;
            _gpr[31] = returnFromCallee;
            _gpr[0] = 0;
            AdvanceCp0Count(_cp0CountStep * 16UL);
            _instructionCounter += 16UL;
            _hasImmediatePcOverride = false;
            Pc = callee;
            return true;
        }

        ulong sp = _gpr[29];
        if (!IsMainRamRange(sp + 0x30UL, 8))
            return false;

        ulong result = ulong.MaxValue;
        if (_gpr[2] == 0)
            result = _gpr[16];

        ulong returnAddress = SignExtend32(_memory.Read32(sp + 0x34UL));
        _gpr[31] = returnAddress;
        _gpr[16] = SignExtend32(_memory.Read32(sp + 0x30UL));
        _gpr[2] = result;
        _gpr[29] = sp + 0x38UL;
        _gpr[0] = 0;
        AdvanceCp0Count(_cp0CountStep * 7UL);
        _instructionCounter += 7UL;
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = returnAddress;
        return true;
    }

    private ulong PackLwuPair(ulong lowWordAddress, ulong highWordAddress)
        => _memory.Read32(lowWordAddress) | ((ulong)_memory.Read32(highWordAddress) << 32);

    private ulong PackConstantAndLwu(uint lowWord, ulong highWordAddress)
        => lowWord | ((ulong)_memory.Read32(highWordAddress) << 32);

    private bool TryFastPathKnownRuntimeAlignedQwordCopy(ulong pc)
    {
        const ulong entry = 0xffffffff800d1370UL;
        if (pc != entry)
            return false;

        if (_memory.Read32(entry) != 0x000640c2U ||
            _memory.Read32(entry + 0x04UL) != 0x000848c0U ||
            _memory.Read32(entry + 0x08UL) != 0x00c93022U ||
            _memory.Read32(entry + 0x0cUL) != 0x1900ffdaU ||
            _memory.Read32(entry + 0x10UL) != 0x2508ffffU ||
            _memory.Read32(entry + 0x14UL) != 0xdca90000U ||
            _memory.Read32(entry + 0x18UL) != 0x24a50008U ||
            _memory.Read32(entry + 0x1cUL) != 0xfc890000U ||
            _memory.Read32(entry + 0x20UL) != 0x1d00fffbU ||
            _memory.Read32(entry + 0x24UL) != 0x24840008U ||
            _memory.Read32(entry + 0x28UL) != 0x1000ffd3U ||
            _memory.Read32(entry + 0x2cUL) != 0x00000000U)
        {
            return false;
        }

        ulong destination = _gpr[4];
        ulong source = _gpr[5];
        ulong byteCount = _gpr[6];
        ulong originalDestination = _gpr[7];
        ulong returnAddress = _gpr[31];
        ulong returnOffset = returnAddress & 0x1fffffffUL;
        if ((destination | source | byteCount) == 0 ||
            (destination & 7UL) != 0 ||
            (source & 7UL) != 0 ||
            (byteCount & 7UL) != 0 ||
            byteCount > 0x00400000UL ||
            originalDestination != destination ||
            returnOffset is < 0x000d0000UL or > 0x00110000UL ||
            !IsMainRamRange(source, byteCount) ||
            !IsMainRamRange(destination, byteCount))
        {
            return false;
        }

        ulong lastValue = 0;
        for (ulong offset = 0; offset < byteCount; offset += 8UL)
        {
            lastValue = _memory.Read64(source + offset);
            _memory.Write64(destination + offset, lastValue);
        }

        _gpr[2] = originalDestination;
        _gpr[4] = destination + byteCount;
        _gpr[5] = source + byteCount;
        _gpr[6] = 0;
        _gpr[7] = originalDestination;
        _gpr[8] = 0;
        _gpr[9] = lastValue;
        Pc = returnAddress;
        CompleteFastPathStep();
        return true;
    }

    private bool TryFastPathKnownRuntimeZeroQwordFillTail(ulong pc)
    {
        const ulong loop = 0xffffffff800d1470UL;
        if (!_enableBootCountDelay || pc != loop)
            return false;

        if (_memory.Read32(loop) != 0x2508ffffU ||
            _memory.Read32(loop + 0x04UL) != 0xfc850000U ||
            _memory.Read32(loop + 0x08UL) != 0x1d00fffdU ||
            _memory.Read32(loop + 0x0cUL) != 0x24840008U ||
            _memory.Read32(loop + 0x10UL) != 0x1000ffcfU ||
            _memory.Read32(loop + 0x14UL) != 0x00000000U)
        {
            return false;
        }

        long count = unchecked((long)_gpr[8]);
        ulong destination = _gpr[4];
        if (count <= 0 || count > 0x100000 || _gpr[5] != 0)
            return false;

        ulong bytes = (ulong)count * 8UL;
        if (bytes > 0x00800000UL || !IsMainRamRange(destination, bytes))
            return false;

        for (ulong offset = 0; offset < bytes; offset += 8UL)
            _memory.Write64(destination + offset, 0);

        _gpr[4] = destination + bytes;
        _gpr[8] = 0;
        _gpr[0] = 0;
        Pc = 0xffffffff800d13c0UL;
        CompleteFastPathStep();
        return true;
    }

    private bool TryFastPathKnownRuntimeStackRecordCopy(ulong pc)
    {
        const ulong loop = 0xffffffff800b1edcUL;
        const ulong exit = 0xffffffff800b1f08UL;
        if (!_enableRuntimeStackRecordCopyFastPath || pc < loop || pc > loop + 0x1cUL)
            return false;

        if (_memory.Read32(loop + 0x00UL) != 0x8c680000U ||
            _memory.Read32(loop + 0x04UL) != 0x8c690004U ||
            _memory.Read32(loop + 0x08UL) != 0x8c6a0008U ||
            _memory.Read32(loop + 0x0cUL) != 0x8c67000cU ||
            _memory.Read32(loop + 0x10UL) != 0xac880000U ||
            _memory.Read32(loop + 0x14UL) != 0xac890004U ||
            _memory.Read32(loop + 0x18UL) != 0xac8a0008U ||
            _memory.Read32(loop + 0x1cUL) != 0xac87000cU ||
            _memory.Read32(loop + 0x20UL) != 0x24630010U ||
            _memory.Read32(loop + 0x24UL) != 0x1462fff6U ||
            _memory.Read32(loop + 0x28UL) != 0x24840010U)
        {
            return false;
        }

        ulong source = _gpr[3];
        ulong end = _gpr[2];
        ulong destination = _gpr[4];
        if (source >= end ||
            ((source | end | destination) & 3UL) != 0)
        {
            return false;
        }

        ulong byteLength = end - source;
        if ((byteLength & 0x0fUL) != 0 ||
            byteLength > 0x100UL ||
            !IsMainRamRange(source, byteLength) ||
            !IsMainRamRange(destination, byteLength))
        {
            return false;
        }

        uint last0 = 0;
        uint last1 = 0;
        uint last2 = 0;
        uint last3 = 0;
        for (ulong offset = 0; offset < byteLength; offset += 0x10UL)
        {
            last0 = _memory.Read32(source + offset);
            last1 = _memory.Read32(source + offset + 0x04UL);
            last2 = _memory.Read32(source + offset + 0x08UL);
            last3 = _memory.Read32(source + offset + 0x0cUL);
            _memory.Write32(destination + offset, last0);
            _memory.Write32(destination + offset + 0x04UL, last1);
            _memory.Write32(destination + offset + 0x08UL, last2);
            _memory.Write32(destination + offset + 0x0cUL, last3);
        }

        _gpr[3] = end;
        _gpr[4] = destination + byteLength;
        _gpr[7] = SignExtend32(last3);
        _gpr[8] = SignExtend32(last0);
        _gpr[9] = SignExtend32(last1);
        _gpr[10] = SignExtend32(last2);
        Pc = exit;
        CompleteFastPathStep();
        return true;
    }

    private bool TryFastPathKnownRuntimeRenderRecordSkip(ulong pc)
    {
        const ulong entry = 0xffffffff800b1e54UL;
        const ulong activeRecordBody = 0xffffffff800b1e7cUL;
        const ulong scanExit = 0xffffffff800b2000UL;
        const ulong listBase = 0xffffffff80210270UL;
        const ulong listCount = 0xffffffff80213600UL;
        const ulong listOwner = 0xffffffff80210000UL;
        const ulong recordStride = 0x2cUL;
        if (!_enableRuntimeRenderRecordSkipFastPath || pc != entry)
            return false;

        if (_memory.Read32(entry + 0x00UL) != 0x9602002aU ||
            _memory.Read32(entry + 0x04UL) != 0x30420040U ||
            _memory.Read32(entry + 0x08UL) != 0x10400005U ||
            _memory.Read32(entry + 0x0cUL) != 0x00000000U ||
            _memory.Read32(entry + 0x10UL) != 0x12600005U ||
            _memory.Read32(entry + 0x14UL) != 0x3c078021U ||
            _memory.Read32(entry + 0x18UL) != 0x0802c7fbU ||
            _memory.Read32(entry + 0x1cUL) != 0x24130001U ||
            _memory.Read32(entry + 0x20UL) != 0x1260005dU ||
            _memory.Read32(entry + 0x24UL) != 0x3c078021U ||
            _memory.Read32(0xffffffff800b1fecUL) != 0x8fc23600U ||
            _memory.Read32(0xffffffff800b1ff0UL) != 0x26940001U ||
            _memory.Read32(0xffffffff800b1ff4UL) != 0x0282102aU ||
            _memory.Read32(0xffffffff800b1ff8UL) != 0x1440ff96U ||
            _memory.Read32(0xffffffff800b1ffcUL) != 0x2610002cU)
        {
            return false;
        }

        if (_gpr[30] != listOwner)
            return false;

        uint count = _memory.Read32(listCount);
        if (count == 0 || count > 0x12aU)
            return false;

        ulong record = _gpr[16];
        ulong index = _gpr[20];
        if (index >= count ||
            record < listBase ||
            (record - listBase) / recordStride != index ||
            (record - listBase) % recordStride != 0)
        {
            return false;
        }

        ulong skipped = 0;
        uint flagBit = 0;
        while (index < count && skipped < 0x12aUL)
        {
            if (!IsMainRamRange(record + 0x2aUL, 2))
                return false;

            flagBit = (uint)(_memory.Read16(record + 0x2aUL) & 0x40U);
            bool flagSet = flagBit != 0;
            bool s3Zero = _gpr[19] == 0;
            bool entersActiveBody = flagSet == s3Zero;
            if (entersActiveBody)
                break;

            if (flagSet)
                _gpr[19] = 1;

            index++;
            record += recordStride;
            skipped++;
        }

        if (skipped == 0)
            return false;

        _gpr[7] = listOwner;
        _gpr[16] = record;
        _gpr[20] = index;
        if (index >= count)
        {
            _gpr[2] = 0;
            Pc = scanExit;
        }
        else
        {
            _gpr[2] = flagBit;
            Pc = activeRecordBody;
        }

        CompleteFastPathStep();
        return true;
    }

    private bool TryFastPathKnownRuntimeRenderRecordNullBody(ulong pc)
    {
        const ulong body = 0xffffffff800b1e7cUL;
        const ulong tail = 0xffffffff800b1fecUL;
        if (!_enableRuntimeRenderRecordSkipFastPath || pc != body)
            return false;

        if (_memory.Read32(body + 0x00UL) != 0x24e7f1d8U ||
            _memory.Read32(body + 0x04UL) != 0x8e110000U ||
            _memory.Read32(body + 0x08UL) != 0x8e12000cU ||
            _memory.Read32(body + 0x0cUL) != 0x8e020020U ||
            _memory.Read32(body + 0x10UL) != 0x8e170004U ||
            _memory.Read32(body + 0x14UL) != 0x00022880U ||
            _memory.Read32(body + 0x18UL) != 0x00a71821U ||
            _memory.Read32(body + 0x1cUL) != 0x92440000U ||
            _memory.Read32(body + 0x20UL) != 0x82420000U ||
            _memory.Read32(body + 0x24UL) != 0x8c760000U ||
            _memory.Read32(body + 0x28UL) != 0x10400051U ||
            _memory.Read32(body + 0x2cUL) != 0x00041600U ||
            _memory.Read32(tail + 0x00UL) != 0x8fc23600U ||
            _memory.Read32(tail + 0x04UL) != 0x26940001U ||
            _memory.Read32(tail + 0x08UL) != 0x0282102aU ||
            _memory.Read32(tail + 0x0cUL) != 0x1440ff96U ||
            _memory.Read32(tail + 0x10UL) != 0x2610002cU)
        {
            return false;
        }

        ulong record = _gpr[16];
        if (!IsMainRamRange(record, 0x24UL))
            return false;

        ulong tableBase = unchecked(_gpr[7] + 0xfffffffffffff1d8UL);
        ulong s1 = SignExtend32(_memory.Read32(record + 0x00UL));
        ulong s2 = SignExtend32(_memory.Read32(record + 0x0cUL));
        ulong slotIndex = _memory.Read32(record + 0x20UL);
        ulong s7 = SignExtend32(_memory.Read32(record + 0x04UL));
        ulong tableOffset = (slotIndex & 0xffffffffUL) << 2;
        ulong tableEntry = tableBase + tableOffset;
        if (!IsMainRamRange(s2, 1UL) || !IsMainRamRange(tableEntry, 4UL))
            return false;

        uint unsignedFirst = _memory.Read8(s2);
        int signedFirst = unchecked((sbyte)unsignedFirst);
        ulong s6 = SignExtend32(_memory.Read32(tableEntry));
        if (signedFirst != 0)
            return false;

        _gpr[2] = (unsignedFirst << 24) & 0xffffffffUL;
        _gpr[3] = tableEntry;
        _gpr[4] = unsignedFirst;
        _gpr[5] = tableOffset;
        _gpr[7] = tableBase;
        _gpr[17] = s1;
        _gpr[18] = s2;
        _gpr[22] = s6;
        _gpr[23] = s7;
        _gpr[0] = 0;
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = tail;

        AdvanceCp0Count(_cp0CountStep * 12UL);
        _instructionCounter += 12UL;
        if (_runtimeRenderRecordNullBodyTraceCount++ < 8)
        {
            Console.WriteLine(
                $"[GAUNTDL:FIX] render-record-null-body pc={pc:x16} " +
                $"record={record:x16} s2={s2:x16} slot={slotIndex:x8}");
        }

        return true;
    }

    private bool TryFastPathKnownRuntimeRecordScanAllocate(ulong pc)
    {
        const ulong prologue = 0xffffffff800b1264UL;
        const ulong entry = 0xffffffff800b1268UL;
        const ulong loopStart = 0xffffffff800b128cUL;
        const ulong loopEnd = 0xffffffff800b12a4UL;
        const ulong countAddress = 0xffffffff80228088UL;
        const ulong tableBase = 0xffffffff80255f20UL;
        const ulong recordStride = 0x50UL;
        const uint maxRecords = 0x17fU;
        bool inLoop = pc >= loopStart && pc <= loopEnd;
        if (!_enableRuntimeRenderRecordSkipFastPath || (pc != prologue && pc != entry && !inLoop))
            return false;

        if (_memory.Read32(prologue) != 0x27bdffe8U ||
            _memory.Read32(entry + 0x00UL) != 0x3c028023U ||
            _memory.Read32(entry + 0x04UL) != 0x8c428088U ||
            _memory.Read32(entry + 0x08UL) != 0x0000282dU ||
            _memory.Read32(entry + 0x0cUL) != 0x1840000cU ||
            _memory.Read32(entry + 0x10UL) != 0xafbf0010U ||
            _memory.Read32(entry + 0x14UL) != 0x24060002U ||
            _memory.Read32(entry + 0x18UL) != 0x0040202dU ||
            _memory.Read32(entry + 0x1cUL) != 0x3c028025U ||
            _memory.Read32(entry + 0x20UL) != 0x24435f20U ||
            _memory.Read32(0xffffffff800b12dcUL) != 0xac828088U ||
            _memory.Read32(0xffffffff800b12ecUL) != 0x3c028025U ||
            _memory.Read32(0xffffffff800b12f0UL) != 0x24425f20U ||
            _memory.Read32(0xffffffff800b12f4UL) != 0x00621021U ||
            _memory.Read32(0xffffffff800b12f8UL) != 0x8fbf0010U ||
            _memory.Read32(0xffffffff800b12fcUL) != 0x03e00008U ||
            _memory.Read32(0xffffffff800b1300UL) != 0x27bd0018U)
        {
            TraceKnownRuntimeRecordScanAllocateReject(
                pc,
                $"signature p={_memory.Read32(prologue):x8} e0={_memory.Read32(entry):x8} e20={_memory.Read32(entry + 0x20UL):x8} " +
                $"dc={_memory.Read32(0xffffffff800b12dcUL):x8} ec={_memory.Read32(0xffffffff800b12ecUL):x8} " +
                $"f0={_memory.Read32(0xffffffff800b12f0UL):x8} f4={_memory.Read32(0xffffffff800b12f4UL):x8} " +
                $"f8={_memory.Read32(0xffffffff800b12f8UL):x8} fc={_memory.Read32(0xffffffff800b12fcUL):x8} " +
                $"1300={_memory.Read32(0xffffffff800b1300UL):x8}");
            return false;
        }

        uint count = _memory.Read32(countAddress);
        uint startIndex = 0;
        if (inLoop)
        {
            if (_gpr[6] != 2)
            {
                TraceKnownRuntimeRecordScanAllocateReject(pc, $"a2={_gpr[6]:x16}");
                return false;
            }

            uint registerCount = (uint)_gpr[4];
            startIndex = (uint)_gpr[5];
            if (registerCount != count || startIndex > count)
            {
                TraceKnownRuntimeRecordScanAllocateReject(pc, $"state registerCount={registerCount} memoryCount={count} start={startIndex}");
                return false;
            }
        }

        if (count > maxRecords)
        {
            TraceKnownRuntimeRecordScanAllocateReject(pc, $"count={count}");
            return false;
        }

        uint selectedIndex = count;
        bool foundActive = false;
        for (uint index = startIndex; index < count; index++)
        {
            ulong record = tableBase + index * recordStride;
            if (!IsMainRamRange(record + 4UL, 1UL))
            {
                TraceKnownRuntimeRecordScanAllocateReject(pc, $"range record={record:x16}");
                return false;
            }

            if (unchecked((sbyte)_memory.Read8(record + 4UL)) == 2)
            {
                selectedIndex = index;
                foundActive = true;
                break;
            }
        }

        if (!foundActive)
        {
            if (count >= maxRecords)
            {
                TraceKnownRuntimeRecordScanAllocateReject(pc, "full");
                return false;
            }

            _memory.Write32(countAddress, count + 1U);
        }

        ulong offset = selectedIndex * recordStride;
        ulong result = tableBase + offset;
        _gpr[2] = SignExtend32((uint)result);
        _gpr[3] = SignExtend32((uint)offset);
        _gpr[4] = 0xffffffff80230000UL;
        _gpr[5] = selectedIndex;
        _gpr[6] = 2;
        if (pc == entry || inLoop)
            _gpr[29] = unchecked(_gpr[29] + 0x18UL);
        _gpr[0] = 0;
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = _gpr[31];

        ulong scannedInstructions = count == 0 ? 24UL : 24UL + Math.Min(count, maxRecords) * 7UL;
        AdvanceCp0Count(_cp0CountStep * scannedInstructions);
        _instructionCounter += scannedInstructions;
        if (_runtimeRecordScanAllocateTraceCount++ < 8)
        {
            Console.WriteLine(
                $"[GAUNTDL:FIX] record-scan-allocate pc={pc:x16} " +
                $"start={startIndex} count={count} selected={selectedIndex} foundActive={foundActive} result={result:x16}");
        }

        return true;
    }

