            return false;
        }

        if (_gpr[21] != fixedStringCompare30)
            return false;
        if (afterEmptyLookupMiss &&
            (_gpr[18] != 0 || _gpr[2] != 0 || _gpr[31] != loop + 0x18UL))
        {
            return false;
        }

        ulong sp = _gpr[29];
        if (!IsMainRamRange(sp + 0x18UL, 0x20UL))
            return false;

        string key = ReadAsciiTraceString(sp + 0x18UL, 0x20);
        if (_enableRuntimeBgLoadModelCloneDistinctSourcesExperiment && key.Length == 0)
            return false;

        long index = unchecked((long)_gpr[17]);
        long count = unchecked((long)_gpr[19]);
        if (index < 0 || count < 0 || index >= count || count > 0x10000)
            return false;

        ulong remaining = (ulong)(count - index);
        if (!afterEmptyLookupMiss && key != "EMPTY_BOX")
        {
