        ulong streamIndex = _gpr[3];
        uint sourceCursor = _memory.Read32(stateBase + 0xf17cUL);
        if (streamIndex < _gpr[20])
            return;

        ulong loadedSource = loadedSourceBase + Math.Min(streamIndex, 8UL) * sourceStride;
        bool knownLoadedSource =
            streamIndex <= 8UL &&
            IsMainRamRange(loadedSource, 0x80UL) &&
            !IsKnownRuntimeBgLoadModelSourceWindowEmpty(loadedSource);
        if (streamIndex > 8UL || !knownLoadedSource)
            return;

        ulong oldLimit = _gpr[20];
        _gpr[20] = (ulong)_runtimeBgLoadModelIndexedTextureQioStreamLimit;
        _gpr[0] = 0;

        if (_runtimeBgLoadModelIndexedTextureQioStreamLimitTraceCount++ < 16)
        {
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] bgloadmodel-indexed-texture-qio-stream-limit pc={pc:x16} " +
                $"streamIndex={streamIndex} sourceCursor={sourceCursor} limit={oldLimit}->{_gpr[20]} " +
                $"loadedSource={loadedSource:x16}");
        }
    }

    private int HydrateKnownRuntimeBgLoadModelRemainingIndexedTextureSources(uint requestedBytes, ulong sourceStride = 0)
    {
        const ulong destinationBase = 0xffffffff802e1718UL;
        if (sourceStride == 0)
            sourceStride = requestedBytes;

        int hydrated = 0;
        for (ulong index = 1; index <= 8UL; index++)
        {
            ulong destination = destinationBase + index * sourceStride;
            if (!IsKnownRuntimeBgLoadModelSourceWindowEmpty(destination))
                continue;
            if (!TryHydrateKnownRuntimeBgLoadModelIndexedTextureSource(index, destination, requestedBytes, out _, out _, out _))
                continue;

            hydrated++;
        }

        return hydrated;
    }

    private bool TryHydrateKnownRuntimeBgLoadModelIndexedTextureSource(
        ulong index,
        ulong destination,
        uint requestedBytes,
        out string code,
        out ulong textureByteOffset,
        out uint firstWord)
    {
        code = "";
        textureByteOffset = 0;
        firstWord = 0;
        if (!TryGetKnownRuntimeBgLoadModelTexturePayload(index, out code, out textureByteOffset, out uint textureByteLength))
            return false;

        if (textureByteLength < requestedBytes)
        {
            for (uint offset = 0; offset < requestedBytes; offset++)
                _memory.Write8(destination + offset, 0);
        }

        uint copyBytes = Math.Min(requestedBytes, textureByteLength);
        return _memory.TryReadDiskByteOffsetToMemory(textureByteOffset, destination, copyBytes, out firstWord, out _);
    }

    private bool IsKnownRuntimeBgLoadModelSourceWindowEmpty(ulong source)
    {
        if (!IsMainRamRange(source, 0x80UL))
            return false;

        for (ulong offset = 0; offset < 0x80UL; offset += 4UL)
        {
            if (_memory.Read32(source + offset) != 0)
                return false;
        }

        return true;
    }

    private bool IsKnownRuntimeBgLoadModelIndexedSourceHeaderSeedable(ulong source)
    {
        if (!IsMainRamRange(source, 0x80UL))
            return false;

        for (ulong offset = 0; offset < 0x40UL; offset += 4UL)
        {
            if (_memory.Read32(source + offset) != 0)
                return false;
        }

        return true;
    }

    private void ApplyKnownRuntimeBgLoadModelQioCreateAliasRepair(ulong pc)
    {
        const ulong returnSlotLoadPc = 0xffffffff800c9944UL;
        const ulong recordBase = 0xffffffff80252da0UL;
        const ulong recordStride = 0x18UL;
        const ulong qioBase = 0xffffffff80217c58UL;
        const ulong qioStride = 0x118UL;

        if (!_enableRuntimeBgLoadModelQioCreateAliasExperiment || pc != returnSlotLoadPc)
            return;
        if (_memory.Read32(returnSlotLoadPc) != 0x8fc20020U)
            return;

        if (!TryGetKnownRuntimeBgLoadModelRecordFromRegisters(out ulong record, out ulong recordIndex, out _))
            return;
        if (recordIndex == 0 || recordIndex >= 0x40)
            return;

        ulong returnSlot = _gpr[30] + 0x20UL;
        if (!IsMainRamRange(returnSlot, 4))
            return;

        uint returnedQio = _memory.Read32(returnSlot);
        if (returnedQio != unchecked((uint)qioBase))
            return;

        ulong expectedQio = qioBase + recordIndex * qioStride;
        if (!IsMainRamRange(expectedQio + 0x18UL, 4))
            return;

        _memory.Write32(returnSlot, unchecked((uint)expectedQio));
        if (_runtimeBgLoadModelQioCreateAliasTraceCount++ < 16)
        {
            Console.WriteLine(
                $"[GAUNTDL:FIX] bgloadmodel-qio-create-alias pc={pc:x16} " +
                $"index={recordIndex} record={record:x16} slot={returnSlot:x16} " +
                $"old={qioBase:x16} new={expectedQio:x16}");
        }
    }

    private void ApplyKnownRuntimeBgLoadModelQioAliasRepair(ulong pc)
    {
        const ulong recordBase = 0xffffffff80252da0UL;
        const ulong recordStride = 0x18UL;
        const ulong qioBase = 0xffffffff80217c58UL;
        const ulong qioStride = 0x118UL;

        if (!_enableRuntimeBgLoadModelDispatchFastPath)
            return;
        if (_memory.Read32(0xffffffff800abaa0UL) != 0x27bdffd8U)
            return;

        ulong qioArrayLimit = qioBase + qioStride * 0x40UL;
        for (ulong recordIndex = 1; recordIndex < 0x10UL; recordIndex++)
        {
            ulong record = recordBase + recordIndex * recordStride;
            if (!IsMainRamRange(record + 0x08UL, 4))
                return;

            uint currentQio = _memory.Read32(record + 0x08UL);
            ulong currentQioAddress = SignExtend32(currentQio);
            if (currentQioAddress < qioBase || currentQioAddress >= qioArrayLimit)
                continue;

            ulong expectedQio = qioBase + recordIndex * qioStride;
            if (!IsMainRamRange(expectedQio + 0x18UL, 4) || currentQioAddress == expectedQio)
                continue;

            _memory.Write32(record + 0x08UL, unchecked((uint)expectedQio));
            if (_runtimeBgLoadModelQioAliasTraceCount++ < 16)
            {
                Console.WriteLine(
                    $"[GAUNTDL:FIX] bgloadmodel-qio-alias pc={pc:x16} " +
                    $"index={recordIndex} record={record:x16} old={currentQioAddress:x16} new={expectedQio:x16}");
            }
        }
    }

    private void ApplyKnownRuntimeBgLoadModelAssetPointerNormalize(ulong pc)
    {
        if (!_enableRuntimeBgLoadModelAssetPointerNormalize)
            return;
        if (pc != 0xffffffff800aacb4UL)
            return;
        if (_memory.Read32(0xffffffff800aa958UL) != 0x27a40018U ||
            _memory.Read32(0xffffffff800ac350UL) != 0x00400008U)
        {
            return;
        }

        const ulong assetTableBase = 0xffffffff8024f9a0UL;
        const ulong assetTableStride = 0x30UL;
        const ulong pointerBias = 0x3f800000UL;

        for (ulong index = 0; index < 0x40UL; index++)
        {
            ulong entry = assetTableBase + index * assetTableStride;
            if (!IsMainRamRange(entry + 0x2fUL, 1))
                return;

            uint raw = _memory.Read32(entry);
            if (raw < pointerBias)
                continue;

            uint normalized = unchecked(raw - (uint)pointerBias);
            ulong normalizedAddress = SignExtend32(normalized);
            if (!IsMainRamRange(normalizedAddress, 0x20UL))
                continue;

            _memory.Write32(entry, normalized);
            if (_runtimeBgLoadModelAssetPointerNormalizeTraceCount++ < 16)
            {
                Console.WriteLine(
                    $"[GAUNTDL:FIX] bgloadmodel-asset-pointer-normalize pc={pc:x16} " +
                    $"index={index} entry={entry:x16} ptr={raw:x8}->{normalized:x8} " +
                    $"name={ReadAsciiTraceString(entry + 0x10UL, 24)}");
            }
        }
    }

    private void TraceKnownRuntimeBgLoadModelAssetParser(ulong pc)
    {
        if (!_traceRuntimeBgLoadModelAssetParser || _runtimeBgLoadModelAssetParserTraceCount >= 128)
            return;

        string label = pc switch
        {
            0xffffffff800aada8UL => "caller-source-lookup-call",
            0xffffffff800aadb0UL => "caller-source-table-base",
            0xffffffff800aadb8UL => "caller-source-table-loaded",
            0xffffffff800aaddcUL => "caller-source-selected",
            0xffffffff800aadf0UL => "caller-source-table-store",
            0xffffffff800aae60UL => "caller-after-path-lookup",
            0xffffffff800aae70UL => "caller-side-source-select",
            0xffffffff800aae8cUL => "caller-side-store-branch",
            0xffffffff800aae98UL => "caller-before-parser-call",
            0xffffffff800aac10UL => "source-writer-index",
            0xffffffff800aac18UL => "source-writer-source-store",
            0xffffffff800aac24UL => "source-writer-side-store",
            0xffffffff800aac48UL => "entry",
            0xffffffff800aac80UL => "pre-index",
            0xffffffff800aac90UL => "asset-table-base",
            0xffffffff800aacb4UL => "after-source-pointer-store",
            0xffffffff800aacd0UL => "after-count-load",
            0xffffffff800aaea8UL => "caller-return",
            _ => ""
        };
        if (label.Length == 0)
            return;
        ulong source = _gpr[5];
        ulong index = _gpr[7] & 0xffffffffUL;
        ulong assetEntry = 0xffffffff8024f9a0UL + Math.Min(index, 0xffUL) * 0x30UL;
        string selectorWords = TraceKnownRuntimeBgLoadModelAssetParserSelectorWords(_gpr[3]);
        string sourceWords = TraceKnownRuntimeBgLoadModelAssetParserWords(source);
        string assetSummary = IsMainRamRange(assetEntry, 0x30)
            ? TraceKnownRuntimeBgLoadModelAssetTableSummary((long)Math.Min(index, 0x3fUL))
            : "";
        string callerState = TraceKnownRuntimeBgLoadModelAssetParserCallerState();
        string callerSelectState = TraceKnownRuntimeBgLoadModelAssetParserCallerSelectState(pc);
        string callerSourceState = TraceKnownRuntimeBgLoadModelAssetParserCallerSourceState(pc);
        string writerState = TraceKnownRuntimeBgLoadModelAssetParserWriterState(pc);

        _runtimeBgLoadModelAssetParserTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:TRACE] bgloadmodel-asset-parser {label} pc={pc:x16} op={_memory.Read32(pc):x8} " +
            $"ra={_gpr[31]:x16} sp={_gpr[29]:x16} v0={_gpr[2]:x16} v1={_gpr[3]:x16} " +
            $"a0={_gpr[4]:x16} a1={source:x16} a2={_gpr[6]:x16} a3={_gpr[7]:x16} " +
            $"s0={_gpr[16]:x16} s1={_gpr[17]:x16} s2={_gpr[18]:x16} s3={_gpr[19]:x16} s5={_gpr[21]:x16} " +
            $"assetEntry={assetEntry:x16} selector={selectorWords} sourceWords={sourceWords} sourceText=\"{ReadAsciiTraceString(source, 48)}\" " +
            $"asset={assetSummary} source={callerSourceState} select={callerSelectState} writer={writerState} caller={callerState}");
    }

    private void TraceKnownRuntimeBgLoadModelLookupHelpers(ulong pc)
    {
        if (!_traceRuntimeBgLoadModelAssetParser || _runtimeBgLoadModelLookupHelperTraceCount >= 128)
            return;

        string label = pc switch
        {
            0xffffffff800b72fcUL => "size-alloc-entry",
            0xffffffff800b7338UL => "size-alloc-return",
            0xffffffff800c9088UL => "lookup-entry",
            0xffffffff800c909cUL => "lookup-global-check",
            0xffffffff800c90b4UL => "lookup-index-fold",
            0xffffffff800c90d4UL => "lookup-return",
            _ => ""
        };
        if (label.Length == 0)
            return;
        if (pc == 0xffffffff800b72fcUL &&
            _gpr[31] is not (0xffffffff800aad84UL or 0xffffffff800aae68UL))
        {
            return;
        }
        if (pc is >= 0xffffffff800c9088UL and <= 0xffffffff800c90d4UL &&
            _gpr[31] != 0xffffffff800aade4UL)
        {
            return;
        }

        _runtimeBgLoadModelLookupHelperTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:TRACE] bgloadmodel-lookup-helper {label} pc={pc:x16} op={_memory.Read32(pc):x8} " +
            $"ra={_gpr[31]:x16} sp={_gpr[29]:x16} v0={_gpr[2]:x16} v1={_gpr[3]:x16} " +
            $"a0={_gpr[4]:x16}({ReadAsciiTraceString(_gpr[4], 48)}) " +
            $"a1={_gpr[5]:x16}({ReadAsciiTraceString(_gpr[5], 48)}) " +
            $"a2={_gpr[6]:x16}({ReadAsciiTraceString(_gpr[6], 48)}) " +
            $"a3={_gpr[7]:x16}({ReadAsciiTraceString(_gpr[7], 48)}) " +
            $"s0={_gpr[16]:x16} s1={_gpr[17]:x16} s2={_gpr[18]:x16} s3={_gpr[19]:x16} s5={_gpr[21]:x16} " +
            $"pathSlot={TraceKnownRuntimeBgLoadModelPathSlot(_gpr[16])} " +
            $"lookupGlobals={TraceKnownRuntimeBgLoadModelLookupGlobals()}");
