    }

    private bool TryFastPathKnownGauntletGlideRuntimeStateInitTail(ulong pc)
    {
        const ulong entry = 0xffffffff80108fe0UL;
        const ulong tail = 0xffffffff80109074UL;
        bool atEntry = pc == entry;
        bool atTail = pc == tail;
        if (!atEntry && !atTail)
            return false;

        if (_memory.Read32(entry) != 0x27bdffe0U ||
            _memory.Read32(entry + 0x04UL) != 0xafbf001cU ||
            _memory.Read32(entry + 0x08UL) != 0xafbe0018U ||
            _memory.Read32(entry + 0x0cUL) != 0x03a0f02dU ||
            _memory.Read32(entry + 0x10UL) != 0xafc40020U ||
            _memory.Read32(entry + 0x94UL) != 0x8fc20010U ||
            _memory.Read32(entry + 0x98UL) != 0x8c430008U ||
            _memory.Read32(entry + 0x9cUL) != 0x3c018026U ||
            _memory.Read32(entry + 0xa0UL) != 0xac232c90U ||
            _memory.Read32(entry + 0xa4UL) != 0x3c028026U ||
            _memory.Read32(entry + 0xa8UL) != 0x8c422c90U ||
            _memory.Read32(entry + 0xacUL) != 0x3c030060U ||
            _memory.Read32(entry + 0xb0UL) != 0x00431021U ||
            _memory.Read32(entry + 0xb4UL) != 0x3c018026U ||
            _memory.Read32(entry + 0xb8UL) != 0xac222c90U ||
            _memory.Read32(entry + 0xbcUL) != 0x3c028026U ||
            _memory.Read32(entry + 0xc0UL) != 0x8c422c90U ||
            _memory.Read32(entry + 0xc4UL) != 0x3c030002U ||
            _memory.Read32(entry + 0xc8UL) != 0x00431021U ||
            _memory.Read32(entry + 0xccUL) != 0x3c018026U ||
            _memory.Read32(entry + 0xd0UL) != 0xac222c90U ||
            _memory.Read32(entry + 0xd4UL) != 0x0c040ff3U ||
            _memory.Read32(entry + 0xd8UL) != 0x00000000U ||
            _memory.Read32(entry + 0xdcUL) != 0x03c0e82dU ||
            _memory.Read32(entry + 0xe0UL) != 0x8fbf001cU ||
            _memory.Read32(entry + 0xe4UL) != 0x8fbe0018U ||
            _memory.Read32(entry + 0xe8UL) != 0x27bd0020U ||
            _memory.Read32(entry + 0xecUL) != 0x03e00008U)
        {
            return false;
        }

        if (atEntry)
        {
            if (_gpr[4] != 0)
                return false;

            ulong entryReturnAddress = _gpr[31];
            ulong entryReturnOffset = entryReturnAddress & 0x1fffffffUL;
            if (entryReturnOffset is < 0x000e0000UL or > 0x00110000UL)
                return false;

            const ulong entryState = 0xffffffff80262d64UL;
            if (!IsMainRamRange(entryState + 0x384UL, 4))
                return false;

            _memory.Write32(0xffffffff80262c84UL, 0);
            _memory.Write32(0xffffffff80262c8cUL, unchecked((uint)entryState));
            uint entryStateWord = _memory.Read32(entryState + 0x08UL) + 0x00620000u;
            _memory.Write32(0xffffffff80262c90UL, entryStateWord);
            NormalizeGlideFifoState(entryState);

            _gpr[2] = _memory.Read32(entryState + 0x37cUL);
            _gpr[3] = entryState + 8UL;
            _gpr[4] = entryState;
            _gpr[31] = entryReturnAddress;
            _gpr[0] = 0;
            AdvanceCp0Count(_cp0CountStep * 64UL);
            _instructionCounter += 64UL;
            _hasPendingBranch = false;
            _hasImmediatePcOverride = false;
            Pc = entryReturnAddress;
            return true;
        }

        ulong framePointer = _gpr[30];
        if (!IsMainRamRange(framePointer + 0x1cUL, 4))
            return false;

        ulong state = SignExtend32(_memory.Read32(framePointer + 0x10UL));
        if (state != 0xffffffff80262d64UL || !IsMainRamRange(state + 0x384UL, 4))
            return false;

        uint stateWord = _memory.Read32(state + 0x08UL) + 0x00620000u;
        _memory.Write32(0xffffffff80262c90UL, stateWord);
        NormalizeGlideFifoState(state);

        ulong returnAddress = SignExtend32(_memory.Read32(framePointer + 0x1cUL));
        ulong returnOffset = returnAddress & 0x1fffffffUL;
        if (returnOffset is < 0x000e0000UL or > 0x00110000UL)
            return false;

        _gpr[2] = _memory.Read32(state + 0x37cUL);
        _gpr[3] = state + 8UL;
        _gpr[4] = state;
        _gpr[31] = returnAddress;
        _gpr[30] = SignExtend32(_memory.Read32(framePointer + 0x18UL));
        _gpr[29] = framePointer + 0x20UL;
        Pc = returnAddress;
        CompleteFastPathStep();
        return true;
    }

    private bool TryFastPathKnownGauntletRuntimeGlideIdlePump(ulong pc)
    {
        const ulong entry = 0xffffffff800e12f8UL;
        if (pc != entry)
            return false;

        if (_memory.Read32(entry + 0x00UL) != 0x27bdffe0U ||
            _memory.Read32(entry + 0x04UL) != 0x3c028023U ||
            _memory.Read32(entry + 0x08UL) != 0xafb00010U ||
            _memory.Read32(entry + 0x0cUL) != 0x8c508114U ||
            _memory.Read32(entry + 0x10UL) != 0xafbf001cU ||
            _memory.Read32(entry + 0x14UL) != 0xafb20018U ||
            _memory.Read32(entry + 0x18UL) != 0xafb10014U ||
            _memory.Read32(entry + 0x1cUL) != 0x0c0417c4U ||
            _memory.Read32(entry + 0x24UL) != 0x1440fffdU ||
            _memory.Read32(entry + 0x28UL) != 0x3c038023U ||
            _memory.Read32(entry + 0x2cUL) != 0x8c628114U ||
            _memory.Read32(entry + 0x30UL) != 0x16020013U ||
            _memory.Read32(entry + 0x88UL) != 0x0440001eU ||
            _memory.Read32(entry + 0x98UL) != 0x0c0423f8U ||
            _memory.Read32(entry + 0x9cUL) != 0x0200202dU ||
            _memory.Read32(entry + 0xe8UL) != 0x0c040993U ||
            _memory.Read32(entry + 0xecUL) != 0x3406ffffU ||
            _memory.Read32(entry + 0xf0UL) != 0x26100001U ||
            _memory.Read32(entry + 0xf4UL) != 0x1a00ffe8U ||
            _memory.Read32(entry + 0xfcUL) != 0x0c0423f8U ||
            _memory.Read32(entry + 0x100UL) != 0x0000202dU ||
            _memory.Read32(entry + 0x104UL) != 0x8fbf001cU ||
            _memory.Read32(entry + 0x108UL) != 0x8fb20018U ||
            _memory.Read32(entry + 0x10cUL) != 0x8fb10014U ||
            _memory.Read32(entry + 0x110UL) != 0x8fb00010U ||
            _memory.Read32(entry + 0x114UL) != 0x03e00008U ||
            _memory.Read32(entry + 0x118UL) != 0x27bd0020U)
        {
            return false;
        }

        ulong returnAddress = _gpr[31];
        ulong returnOffset = returnAddress & 0x1fffffffUL;
        if (returnOffset is < 0x000e0000UL or > 0x000e2000UL)
            return false;

        if (!TryApplyKnownGauntletRuntimeGlideIdlePumpEffects(out uint room))
            return false;

        _gpr[2] = room;
        _gpr[3] = 0xffffffff80262d64UL + 8UL;
        _gpr[4] = 0xffffffff80262d64UL;
        _gpr[31] = returnAddress;
        _gpr[0] = 0;
        AdvanceCp0Count(_cp0CountStep * 192UL);
        _instructionCounter += 192UL;
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = returnAddress;
        return true;
    }

    private bool TryFastPathKnownGauntletRuntimeGlideIdleLoop(ulong pc)
    {
        const ulong entry = 0xffffffff800dc6d0UL;
        if (pc != entry)
            return false;

        if (_memory.Read32(entry + 0x00UL) != 0x0c03ae29U ||
            _memory.Read32(entry + 0x04UL) != 0x3c040060U ||
            _memory.Read32(entry + 0x08UL) != 0x00501024U ||
            _memory.Read32(entry + 0x0cUL) != 0x14400006U ||
            _memory.Read32(entry + 0x10UL) != 0x2402ffffU ||
            _memory.Read32(entry + 0x14UL) != 0x0c038505U ||
            _memory.Read32(entry + 0x18UL) != 0x0000202dU ||
            _memory.Read32(entry + 0x1cUL) != 0x080371b4U ||
            _memory.Read32(entry + 0x20UL) != 0x00000000U)
        {
            return false;
        }

        uint callback = _memory.Read32(0xffffffff802281acUL);
        if (callback != 0x800e12f8U || _gpr[16] != 0x00600000UL)
            return false;

        if (ReadRuntimeStatusBitfield(index: 5u, mask: 0x00600000u) != 0)
            return false;

        bool hasProbeBudget = _remainingProbeSteps >= 12;
        int skippedInstructions = hasProbeBudget ? Math.Min(_remainingProbeSteps, 1024 * 1024) : 12;
        int iterations = hasProbeBudget ? Math.Max(1, skippedInstructions / 12) : 1;
        skippedInstructions = iterations * 12;
        if (!TryApplyKnownGauntletRuntimeGlideIdlePumpEffects(out _, iterations))
            return false;

        _memory.Write8(0xffffffffa4207000UL, 0);
        _gpr[2] = 0;
        _gpr[3] = 0;
        _gpr[4] = 0;
        _gpr[31] = 0xffffffff800dc6ecUL;
        _gpr[0] = 0;
        AdvanceCp0Count(_cp0CountStep * (ulong)skippedInstructions);
        _instructionCounter += (ulong)skippedInstructions;
        if (hasProbeBudget)
            _probeStepDebt += skippedInstructions - 1;
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = entry;
        return true;
    }

    private uint ReadRuntimeStatusBitfield(uint index, uint mask)
    {
        const ulong table = 0xffffffff80262b90UL;
        if (index >= 7u)
            return 0;

        ulong record = table + index * 28UL;
        uint oldBits = _memory.Read32(record + 0x08UL);
        uint sourceBits = _memory.Read32(record + 0x0cUL);
        uint combined = _memory.Read32(record + 0x04UL) | _memory.Read32(record);
        uint changed = oldBits ^ sourceBits;
        if (mask == 0)
            return combined;

        uint selected = ~changed & combined & mask;
        return (~mask & combined) | selected;
    }

    private bool TryApplyKnownGauntletRuntimeGlideIdlePumpEffects(out uint room, int iterations = 1)
    {
        room = 0;
        if (iterations <= 0)
            return false;

        const ulong state = 0xffffffff80262d64UL;
        if (_memory.Read32(0xffffffff8022af7cUL) != 0 ||
            _memory.Read32(0xffffffff8022af10UL + 0x18UL) != 0 ||
            SignExtend32(_memory.Read32(0xffffffff80262c8cUL)) != state ||
            SignExtend32(_memory.Read32(state + 0x04UL)) != 0xffffffffa8000000UL ||
            !IsMainRamRange(state + 0x384UL, 4))
        {
            return false;
        }

        // The polled helper emits a type1 write of register 0x48 to zero when
        // the previous latch is zero. It is a no-op for this bringup backend,
        // and the state normalization below keeps the guest FIFO room sane.
        _memory.Write32(0xffffffff8022f5b4UL, 0);

        uint tick = _memory.Read32(0xffffffff80228114UL);
        _memory.Write32(0xffffffff80228114UL, tick + (uint)iterations);
        ApplyKnownGauntletRuntimeInputPollEffects();

        _memory.Write32(0xffffffff80262c84UL, 0);
        _memory.Write32(0xffffffff80262c8cUL, unchecked((uint)state));
        uint stateWord = _memory.Read32(state + 0x08UL) + 0x00620000u;
        _memory.Write32(0xffffffff80262c90UL, stateWord);
        NormalizeGlideFifoState(state);
        room = _memory.Read32(state + 0x37cUL);
        return true;
    }

    private void ApplyKnownGauntletRuntimeInputPollEffects()
    {
        _memory.RecordRuntimeInputPollEffects();
    }

    private void UpdateRuntimeStatusBitfieldRecord(ulong record, uint value)
    {
        uint previousValue = _memory.Read32(record);
        uint oldBits = _memory.Read32(record + 0x08UL);
