            _memory.Read32(callsitePc + 0x08UL) != 0xafab001cU ||
            _memory.Read32(callsitePc + 0x0cUL) != 0xafac0020U ||
            _memory.Read32(callsitePc + 0x10UL) != 0x0c00e1e3U ||
            _memory.Read32(callsitePc + 0x14UL) != 0xafad0024U ||
