           $"lfb={_lfbWriteCount} tex={_textureWriteCount} buf={_frontBufferIndex}/{_backBufferIndex}/{GetColorBufferCount()} " +
           GetBufferCountDebugStatus() +
           GetTmuDebugStatus() +
