           $"ffo={_fastFillOtherBufferCounts[0]}/{_fastFillOtherBufferCounts[1]}/{_fastFillOtherBufferCounts[2]} " +
           $"ffs={_fastFillSuppressedWhiteCount}/{_fastFillSuppressedBlackCount}/{_fastFillSuppressedOtherCount} " +
