    private uint PeekCommandFifoWord() => _cmdFifoRam[CommandFifoStorageIndex(_cmdFifoReadIndex)];

    private string GetCommandFifoDecodeStopDebugStatus()
    {
        if (_commandFifoDecodeStopCount == 0)
            return "";

        string pcStatus = _lastCommandFifoDecodeStopPc != 0 ? $"/pc=0x{_lastCommandFifoDecodeStopPc:X}" : "";
        return
            $"cmdstop={_lastCommandFifoDecodeStopReason}/0x{_lastCommandFifoDecodeStopCommand:X8}/" +
            $"{_lastCommandFifoDecodeStopWordsNeeded}/{_lastCommandFifoDecodeStopDepth}/" +
            $"0x{_lastCommandFifoDecodeStopReadIndex * 4:X}/0x{_lastCommandFifoDecodeStopStorageIndex * 4:X}/" +
            $"0x{_lastCommandFifoDecodeStopNext1:X8}/0x{_lastCommandFifoDecodeStopNext2:X8}{pcStatus}/" +
            $"{_commandFifoDecodeStopCount} ";
    }

    public virtual void WriteRegister(uint address, uint value)
    {
        uint register = (address >> 2) & 0xffu;
        _registers[register] = value;
        _registerWriteCount++;
        TraceFastFillSwapOrder("reg", register, value);
        if (IsInterestingEventRegister(register))
            RecordVoodooEvent($"reg[{register:x3}]=0x{value:x8}");
        switch (register)
        {
            case RegCmdFifoBaseAddr:
                if (_fixMameCommandFifoModel && _experimentMameCommandFifoRegisterWindow)
                    ApplyMameCommandFifoRegisterWindow();
                else
                {
                    _cmdFifoRamBase = (int)((value & 0x000003ffu) << 12);
                    _cmdFifoRamEnd = Math.Clamp((int)((((value >> 16) & 0x000003ffu) + 1u) << 12), 4, CmdFifoWords * 4);
                }
                _cmdFifoWriteGenerationBase = 0;
                _cmdFifoWriteQueueIndex = 0;
                _cmdFifoLastWriteStorageIndex = -1;
                TraceCommandFifoModel($"reg base value=0x{value:x8}");
                break;
            case RegTriangleCommand:
                MarkCommandFifoRenderWork();
                DrawIntegerTriangle();
                break;
            case RegFtriangleCommand:
                MarkCommandFifoRenderWork();
                DrawFloatTriangle();
                break;
            case RegFastfillCommand:
                MarkCommandFifoRenderWork();
                FastFill();
                break;
            case RegSwapbufferCommand:
                MarkCommandFifoRenderWork();
                SwapBuffers(value);
                break;
            case RegCmdFifoRdPtr:
                _cmdFifoReadIndex = DecodeCommandFifoReadIndex((int)(value >> 2));
                _cmdFifoReadPointerWritten = true;
                TraceCommandFifoModel($"reg rdptr value=0x{value:x8}");
                if (!_decodingCommandFifo)
                    DecodeCommandFifoPackets("reg-rdptr");
                break;
            case RegCmdFifoAddressMin:
                if (_fixMameCommandFifoModel && _experimentMameCommandFifoRegisterWindow)
                    ApplyMameCommandFifoRegisterWindow();
                else
                    _cmdFifoAddressMin = (int)value;
                TraceCommandFifoModel($"reg amin value=0x{value:x8}");
                DecodeCommandFifoAfterRegisterWrite();
                break;
            case RegCmdFifoAddressMax:
                if (_fixMameCommandFifoModel && _experimentMameCommandFifoRegisterWindow)
                    ApplyMameCommandFifoRegisterWindow();
                else
                    _cmdFifoAddressMax = (int)value;
                TraceCommandFifoModel($"reg amax value=0x{value:x8}");
                DecodeCommandFifoAfterRegisterWrite();
                break;
            case RegCmdFifoDepth:
                _cmdFifoDepth = _fixMameCommandFifoModel && _experimentMameCommandFifoFullDepthHolesRegisters
                    ? unchecked((int)value)
                    : (int)(value & 0xffffu);
                TraceCommandFifoModel($"reg depth value=0x{value:x8}");
                DecodeCommandFifoAfterRegisterWrite();
                break;
            case RegCmdFifoHoles:
                _cmdFifoHoles = _fixMameCommandFifoModel && _experimentMameCommandFifoFullDepthHolesRegisters
                    ? unchecked((int)value)
                    : (int)(value & 0xffffu);
                TraceCommandFifoModel($"reg holes value=0x{value:x8}");
                DecodeCommandFifoAfterRegisterWrite();
                break;
            case 0xa8u:
                MarkCommandFifoRenderWork();
                DrawSetupTriangle();
                break;
            case 0xa9u:
                BeginSetupTriangle();
                break;
        }

        CountCommandFifoRegisterWritePc(register, value);
    }

    private void DecodeCommandFifoAfterRegisterWrite()
    {
        if (!_fixMameCommandFifoModel ||
            !_experimentMameCommandFifoDecodeOnRegisterWrite ||
            _decodingCommandFifo)
        {
            return;
        }

        DecodeCommandFifoPacketsIfNotPending("reg-write");
    }

    private void ApplyMameCommandFifoRegisterWindow()
    {
        uint baseValue = _registers[RegCmdFifoBaseAddr];
        _cmdFifoRamBase = (int)((baseValue & 0x000003ffu) << 12);
        _cmdFifoRamEnd = (int)((((baseValue >> 16) & 0x000003ffu) + 1u) << 12);
        _cmdFifoAddressMin = (int)_registers[RegCmdFifoAddressMin];
        _cmdFifoAddressMax = (int)_registers[RegCmdFifoAddressMax];
    }

    private void MarkCommandFifoRenderWork()
    {
        if (_decodingCommandFifo)
            _commandFifoPacketIssuedRenderWork = true;
    }

    private bool IsCommandFifoOperationPending()
        => _fixMameCommandFifoModel &&
           _experimentMameCommandFifoOperationPendingGate &&
           _commandFifoOperationPending;

    public virtual uint ReadRegister(uint address)
    {
        uint register = (address >> 2) & 0xffu;
        uint value = register switch
        {
            RegCmdFifoRdPtr => (uint)(_cmdFifoReadIndex << 2),
            RegCmdFifoDepth => _fixMameCommandFifoModel && _experimentMameCommandFifoFullDepthHolesRegisters
                ? unchecked((uint)_cmdFifoDepth)
                : (uint)Math.Clamp(_cmdFifoDepth, 0, 0xffff),
            RegCmdFifoHoles => _fixMameCommandFifoModel && _experimentMameCommandFifoFullDepthHolesRegisters
                ? unchecked((uint)_cmdFifoHoles)
                : (uint)Math.Clamp(_cmdFifoHoles, 0, 0xffff),
            _ => _registers[register]
        };
        CountCommandFifoRegisterReadPc(register, value);
        return value;
    }

    public virtual void WriteFifo(uint wordOffset, uint value)
    {
        int index = (int)(wordOffset & CmdFifoMask);
        int storageIndex = _fixMameCommandFifoModel && !_experimentMameCommandFifoWriteQueue
            ? CommandFifoStorageIndex((_cmdFifoRamBase >> 2) + index)
            : index;
        int logicalWriteIndex = _fixMameCommandFifoModel && _experimentMameCommandFifoWriteQueue
            ? DecodeCommandFifoReadIndex(_cmdFifoWriteQueueIndex++)
            : GetMameCommandFifoLogicalWriteIndex(index, storageIndex);
        if (_fixMameCommandFifoModel && _experimentMameCommandFifoWriteQueue)
            storageIndex = CommandFifoStorageIndex(logicalWriteIndex);
        int address = logicalWriteIndex * 4;
        if (_cmdFifoBulkFirstWritePending)
        {
            Array.Clear(_cmdFifoValid);
            _cmdFifoValidCount = 0;
            _cmdFifoReadIndex = _fixMameCommandFifoModel ? DecodeCommandFifoReadIndex(logicalWriteIndex) : storageIndex;
            _cmdFifoDepth = 0;
            _cmdFifoHoles = 0;
            _cmdFifoDepthWordsAdded = 0;
            _cmdFifoDepthWordsDecoded = 0;
            _cmdFifoDepthWordsStreamed = 0;
            _cmdFifoWriteGenerationBase = logicalWriteIndex & ~CmdFifoMask;
            _cmdFifoWriteQueueIndex = logicalWriteIndex;
            _cmdFifoLastWriteStorageIndex = storageIndex;
            _cmdFifoReadPointerWritten = true;
            _cmdFifoJumped = false;
            _cmdFifoBulkFirstWritePending = false;
        }
        if (_cmdFifoBulkWriteDepth > 0)
        {
            if (!_cmdFifoBulkSawWrite)
            {
                _cmdFifoBulkStartIndex = UseMameCommandFifoBulkLogicalWindow() ? logicalWriteIndex : storageIndex;
                _cmdFifoBulkSawWrite = true;
            }
            _cmdFifoBulkLastIndex = UseMameCommandFifoBulkLogicalWindow() ? logicalWriteIndex : storageIndex;
            _cmdFifoBulkWriteWordCount++;
        }

        bool mameWrapInvalidRead =
            _fixMameCommandFifoModel &&
            _experimentMameCommandFifoWrapClearInvalidRead &&
            !_cmdFifoValid[CommandFifoStorageIndex(_cmdFifoReadIndex)];
        if ((!_fixMameCommandFifoModel ||
             _experimentMameCommandFifoWrapClear ||
             mameWrapInvalidRead) &&
            storageIndex == 0 &&
            _cmdFifoReadPointerWritten &&
            _cmdFifoReadIndex != 0)
        {
            Array.Clear(_cmdFifoValid);
            _cmdFifoValidCount = 0;
            _cmdFifoReadIndex = _fixMameCommandFifoModel ? address >> 2 : 0;
            _cmdFifoDepth = 0;
            _cmdFifoHoles = 0;
            _cmdFifoDepthWordsAdded = 0;
            _cmdFifoDepthWordsDecoded = 0;
            _cmdFifoDepthWordsStreamed = 0;
            _cmdFifoAddressMin = _cmdFifoRamBase - 4;
            _cmdFifoAddressMax = _cmdFifoRamBase - 4;
            _cmdFifoWriteGenerationBase = 0;
            _cmdFifoWriteQueueIndex = 0;
            _cmdFifoLastWriteStorageIndex = -1;
            _cmdFifoJumped = false;
        }

        _cmdFifoRam[storageIndex] = value;
        _cmdFifoStorageLogicalIndex[storageIndex] = logicalWriteIndex;
        bool storageWasValid = _cmdFifoValid[storageIndex];
        if (_fixMameCommandFifoModel)
            TrackMameCommandFifoWrite(address, value);
        else if (!storageWasValid)
            _cmdFifoDepth = Math.Min(0xffff, _cmdFifoDepth + 1);
        if (!storageWasValid)
            _cmdFifoValidCount++;
        _cmdFifoValid[storageIndex] = true;
        _fifoWriteCount++;
        TraceCommandFifoValidity("write", storageIndex);

        if (!_cmdFifoReadPointerWritten)
        {
            _cmdFifoReadIndex = _fixMameCommandFifoModel ? DecodeCommandFifoReadIndex(logicalWriteIndex) : storageIndex;
            _cmdFifoReadPointerWritten = true;
        }

        if (_cmdFifoBulkWriteDepth == 0 &&
            (!_fixMameCommandFifoModel || !_experimentMameCommandFifoDeferWriteDecode))
        {
            DecodeCommandFifoPacketsIfNotPending("write");
        }
    }

    private int GetMameCommandFifoLogicalWriteIndex(int localIndex, int storageIndex)
    {
        int baseLocalIndex = (_cmdFifoRamBase >> 2) + localIndex;
        if (_fixMameCommandFifoModel &&
            _experimentMameCommandFifoAlignWritesToReadGeneration &&
            _cmdFifoReadPointerWritten &&
            baseLocalIndex < _cmdFifoReadIndex)
        {
            int generationDelta = _cmdFifoReadIndex - baseLocalIndex;
            int generations = (generationDelta + CmdFifoWords - 1) / CmdFifoWords;
            return baseLocalIndex + generations * CmdFifoWords;
        }

        if (!_fixMameCommandFifoModel || !_experimentMameCommandFifoTrackWriteGeneration)
            return baseLocalIndex;

        if (_cmdFifoLastWriteStorageIndex >= 0 &&
            storageIndex < _cmdFifoLastWriteStorageIndex &&
            _cmdFifoLastWriteStorageIndex - storageIndex > CmdFifoWords / 2)
        {
            _cmdFifoWriteGenerationBase += CmdFifoWords;
        }

        _cmdFifoLastWriteStorageIndex = storageIndex;
        return baseLocalIndex + _cmdFifoWriteGenerationBase;
    }

    private void TraceCommandFifoModel(string message, uint? value = null)
    {
        if (!_traceCommandFifoModel)
            return;
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (_traceCommandFifoModelPcs.Length != 0 && !_traceCommandFifoModelPcs.Contains(pc))
            return;
        if (value.HasValue &&
            _traceCommandFifoModelCommands.Length != 0 &&
            !_traceCommandFifoModelCommands.Contains(value.Value))
        {
            return;
        }
        if (_commandFifoModelTraceCount++ >= _traceCommandFifoModelLimit)
            return;

        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-CMDFIFO] {message} " +
            $"base=0x{_cmdFifoRamBase:x5} end=0x{_cmdFifoRamEnd:x5} rd=0x{_cmdFifoReadIndex * 4:x5} " +
            $"amin=0x{_cmdFifoAddressMin:x5} amax=0x{_cmdFifoAddressMax:x5} depth={_cmdFifoDepth} holes={_cmdFifoHoles} valid={_cmdFifoValidCount} " +
            $"fbi7=0x{_registers[RegFbiInit7]:x8}{pcStatus}");
    }

    private void TraceCommandFifoValidity(string reason, int storageIndex)
    {
        if (!_traceCommandFifoValidity || !_fixMameCommandFifoModel)
            return;

        int readStorage = CommandFifoStorageIndex(_cmdFifoReadIndex);
        bool readValid = _cmdFifoValid[readStorage];
        int excessDepth = _cmdFifoDepth - _cmdFifoValidCount;
        if (_cmdFifoDepth == 0 && _cmdFifoValidCount == 0)
            return;
        if (!readValid && _cmdFifoDepth <= 0)
            return;
        if (readValid && excessDepth <= 64)
            return;
        if (_commandFifoValidityTraceCount++ >= _traceCommandFifoValidityLimit)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-CMDFIFO-VALID] n={_commandFifoValidityTraceCount} reason={reason} " +
            $"rd=0x{_cmdFifoReadIndex * 4:x8} storage=0x{readStorage * 4:x5} readValid={(readValid ? 1 : 0)} " +
            $"touched=0x{CommandFifoStorageIndex(storageIndex) * 4:x5} depth={_cmdFifoDepth} holes={_cmdFifoHoles} valid={_cmdFifoValidCount} excess={excessDepth} " +
            $"amin=0x{_cmdFifoAddressMin:x8} amax=0x{_cmdFifoAddressMax:x8} " +
            $"fifoPackets={_fifoPacketCount} drawPackets={_fifoDrawPacketCount}{pcStatus}");
    }

    private void TrackMameCommandFifoWrite(int address, uint value)
    {
        if (!_experimentMameCommandFifoTrackWriteGeneration && (uint)address >= (uint)_cmdFifoRamEnd)
        {
            CountCommandFifoWritePc(0, 0, 0, address, value);
            return;
        }
        if (((_registers[RegFbiInit7] >> 10) & 1u) != 0)
        {
            CountCommandFifoWritePc(1, 0, 0, address, value);
            return;
        }
        if (_cmdFifoDepth == 0 && _cmdFifoHoles == 0 && _cmdFifoAddressMin < _cmdFifoRamBase)
        {
            _cmdFifoAddressMin = address - 4;
            _cmdFifoAddressMax = address - 4;
        }

        int depthBefore = _cmdFifoDepth;
        int holesBefore = _cmdFifoHoles;
        int mode;
        if (_cmdFifoHoles == 0 && address == _cmdFifoAddressMin + 4)
        {
            mode = 2;
            _cmdFifoAddressMin = address;
            _cmdFifoAddressMax = address;
            _cmdFifoDepth++;
            _cmdFifoDepthWordsAdded++;
        }
        else if (address < _cmdFifoAddressMin)
        {
            mode = 3;
            _cmdFifoHoles += _experimentMameCommandFifoExactHoleAccounting
                ? (address - _cmdFifoRamBase) / 4
                : Math.Max(0, (address - _cmdFifoRamBase) / 4);
            _cmdFifoAddressMin = _cmdFifoRamBase;
            _cmdFifoAddressMax = address;
            _cmdFifoDepth++;
            _cmdFifoDepthWordsAdded++;
        }
        else if (address < _cmdFifoAddressMax)
        {
            mode = 4;
            if (_experimentMameCommandFifoExactHoleAccounting || _cmdFifoHoles > 0)
                _cmdFifoHoles--;
            if (_cmdFifoHoles == 0)
            {
                _cmdFifoDepth += _experimentMameCommandFifoExactHoleAccounting
                    ? (_cmdFifoAddressMax - _cmdFifoAddressMin) / 4
                    : Math.Max(0, (_cmdFifoAddressMax - _cmdFifoAddressMin) / 4);
                _cmdFifoDepthWordsAdded += _experimentMameCommandFifoExactHoleAccounting
                    ? (_cmdFifoAddressMax - _cmdFifoAddressMin) / 4
                    : Math.Max(0, (_cmdFifoAddressMax - _cmdFifoAddressMin) / 4);
                _cmdFifoAddressMin = _cmdFifoAddressMax;
            }
        }
        else
        {
            mode = 5;
            _cmdFifoHoles += _experimentMameCommandFifoExactHoleAccounting
                ? (address - _cmdFifoAddressMax) / 4 - 1
                : Math.Max(0, (address - _cmdFifoAddressMax) / 4 - 1);
            _cmdFifoAddressMax = address;
        }
        CountCommandFifoWritePc(mode, _cmdFifoDepth - depthBefore, _cmdFifoHoles - holesBefore, address, value);
        if (_traceCommandFifoModelStorageOffsets.Length == 0)
            TraceCommandFifoModel($"write addr=0x{address:x5} value=0x{value:x8}", value);
        TraceCommandFifoStorageWrite(address, value);
    }

    private void TraceCommandFifoStorageWrite(int address, uint value)
    {
        if (!_traceCommandFifoModel || _traceCommandFifoModelStorageOffsets.Length == 0)
            return;

        int storageByteOffset = CommandFifoStorageIndex(address >> 2) * 4;
        if (!_traceCommandFifoModelStorageOffsets.Contains((ulong)storageByteOffset))
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (_traceCommandFifoModelPcs.Length != 0 && !_traceCommandFifoModelPcs.Contains(pc))
            return;
        if (_commandFifoModelTraceCount++ >= _traceCommandFifoModelLimit)
            return;

        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-CMDFIFO] storage-write storage=0x{storageByteOffset:x5} " +
            $"addr=0x{address:x8} value=0x{value:x8} " +
            $"base=0x{_cmdFifoRamBase:x5} end=0x{_cmdFifoRamEnd:x5} rd=0x{_cmdFifoReadIndex * 4:x8} " +
            $"amin=0x{_cmdFifoAddressMin:x8} amax=0x{_cmdFifoAddressMax:x8} depth={_cmdFifoDepth} holes={_cmdFifoHoles} valid={_cmdFifoValidCount} " +
            $"fbi7=0x{_registers[RegFbiInit7]:x8}{pcStatus}");
    }

    public void BeginCommandFifoBulkWrite()
    {
        if (_cmdFifoBulkWriteDepth++ == 0 && _experimentResetCommandFifoOnBulkWrite)
            _cmdFifoBulkFirstWritePending = true;
        if (_cmdFifoBulkWriteDepth == 1)
        {
            _cmdFifoBulkSawWrite = false;
            _cmdFifoBulkStartIndex = 0;
            _cmdFifoBulkLastIndex = 0;
            _cmdFifoBulkWriteWordCount = 0;
        }
    }

    public void EndCommandFifoBulkWrite()
    {
        if (_cmdFifoBulkWriteDepth > 0)
            _cmdFifoBulkWriteDepth--;
        if (_cmdFifoBulkWriteDepth == 0)
            _cmdFifoBulkFirstWritePending = false;
        if (_cmdFifoBulkWriteDepth == 0 &&
            _experimentRewindCommandFifoOnBulkWrite &&
            _cmdFifoBulkSawWrite &&
            IsCommandFifoReadIndexInsideBulkWrite() &&
            IsType5TexturePacketHeader(_cmdFifoRam[CommandFifoStorageIndex(_cmdFifoBulkStartIndex)]))
        {
            _cmdFifoReadIndex = _cmdFifoBulkStartIndex;
        }
        if (_cmdFifoBulkWriteDepth == 0 &&
            _fixMameCommandFifoModel &&
            _experimentMameCommandFifoBulkResyncInvalidRead &&
            _cmdFifoBulkSawWrite &&
            _cmdFifoDepth > 0 &&
            !_cmdFifoValid[CommandFifoStorageIndex(_cmdFifoReadIndex)])
        {
            _cmdFifoReadIndex = _cmdFifoBulkStartIndex;
        }
        if (_cmdFifoBulkWriteDepth == 0 &&
            _experimentCommandFifoBulkDecodeWindow &&
            _cmdFifoBulkSawWrite &&
            IsType5TexturePacketHeader(_cmdFifoRam[CommandFifoStorageIndex(_cmdFifoBulkStartIndex)]))
        {
            _cmdFifoReadIndex = _cmdFifoBulkStartIndex;
            _cmdFifoBulkDecodeRemainingWords = _cmdFifoBulkWriteWordCount;
        }
        if (_cmdFifoBulkWriteDepth == 0)
            DecodeCommandFifoPacketsIfNotPending("bulk-end");
        if (_cmdFifoBulkWriteDepth == 0)
            _cmdFifoBulkDecodeRemainingWords = 0;
    }

    private bool IsCommandFifoReadIndexInsideBulkWrite()
    {
        if (!_cmdFifoBulkSawWrite)
            return false;
        if (UseMameCommandFifoBulkLogicalWindow())
            return _cmdFifoReadIndex >= _cmdFifoBulkStartIndex && _cmdFifoReadIndex <= _cmdFifoBulkLastIndex;
        if (_cmdFifoBulkStartIndex <= _cmdFifoBulkLastIndex)
            return _cmdFifoReadIndex >= _cmdFifoBulkStartIndex && _cmdFifoReadIndex <= _cmdFifoBulkLastIndex;
        return _cmdFifoReadIndex >= _cmdFifoBulkStartIndex || _cmdFifoReadIndex <= _cmdFifoBulkLastIndex;
    }

    private bool UseMameCommandFifoBulkLogicalWindow()
        => _fixMameCommandFifoModel && _experimentMameCommandFifoBulkLogicalWindow;

    private static bool IsType5TexturePacketHeader(uint command)
        => (command & 7u) == 5u && (command >> 30) == 3u && ((command >> 3) & 0x7ffffu) > 0;

    public uint ReadStatus(bool vblank)
    {
        _statusReadCount++;
        CountStatusPc();
        if (IsCommandFifoOperationPending())
        {
            _commandFifoOperationPending = false;
            DecodeCommandFifoPacketsIfNotPending("status");
        }
        if (vblank && _pendingSwapCount > 0)
        {
            _pendingSwapCount--;
            ExecuteSwapBuffers(0);
            RecordVoodooEvent($"status swap-drain vblank={(vblank ? 1 : 0)} pend={_pendingSwapCount}");
        }

        uint status = 0x0ffff03fu | ((uint)(_frontBufferIndex & 3) << 10);
        if (vblank)
            status |= 0x40u;
        status |= (uint)Math.Clamp(_pendingSwapCount, 0, 7) << 28;
        if (_recordVoodooEvents && (_statusReadCount <= 16 || _pendingSwapCount > 0 || (_statusReadCount & 0x3ff) == 0))
            RecordVoodooEvent($"status read value=0x{status:x8} vblank={(vblank ? 1 : 0)} pend={_pendingSwapCount}");
        return status;
    }

    public virtual uint ReadLfb32(uint offset)
    {
        uint lfbMode = _registers[RegLfbMode];
        int pixel = GetLfbPixelOffset(offset, IsTwoPixelLfbFormat((int)(lfbMode & 0x0fu)), lfbMode);
        ushort[] buffer = GetLfbReadBuffer(lfbMode);
        ushort low = buffer[pixel & (LfbPixels - 1)];
        ushort high = buffer[(pixel + 1) & (LfbPixels - 1)];
        uint value = (uint)(low | (high << 16));
        if (((lfbMode >> 15) & 1u) != 0)
            value = (value << 16) | (value >> 16);
        if (((lfbMode >> 16) & 1u) != 0)
            value = BinaryPrimitives.ReverseEndianness(value);
        return value;
    }

    public virtual void WriteLfb32(uint offset, uint value)
    {
        MirrorLfbWriteToCommandFifoStorage(offset, value);
        uint lfbMode = _registers[RegLfbMode];
        if (lfbMode == 0x00002011u)
        {
            WriteLfb32Mode2011(offset, value);
            return;
        }

        if (((lfbMode >> 12) & 1u) != 0)
            value = BinaryPrimitives.ReverseEndianness(value);
        if (((lfbMode >> 11) & 1u) != 0)
            value = (value << 16) | (value >> 16);

        int format = (int)(lfbMode & 0x0fu);
        int rgbaLanes = (int)((lfbMode >> 9) & 0x03u);
        bool twoPixels = IsTwoPixelLfbFormat(format);
        int pixel = GetLfbPixelOffset(offset, twoPixels, lfbMode);
        WriteLfbDepth(value, format, pixel);
        if (format == 15)
        {
            _lfbWriteCount++;
            return;
        }

        int bufferIndex = GetLfbWriteBufferIndex(lfbMode);
        InvalidateFastFillCache(bufferIndex);
        ushort[] buffer = _colorBuffers[bufferIndex];

        if (TryExpandLfbPixel(value, format, rgbaLanes, highHalf: false, out ushort first))
            buffer[pixel & (LfbPixels - 1)] = first;
        if (twoPixels && TryExpandLfbPixel(value, format, rgbaLanes, highHalf: true, out ushort second))
            buffer[(pixel + 1) & (LfbPixels - 1)] = second;
        _lfbWriteCount++;
    }

    private void WriteLfb32Mode2011(uint offset, uint value)
    {
        uint pixelOffset = ((offset & (LfbBytes - 1u)) >> 2) << 1;
        int x = (int)(pixelOffset & (LfbRowPixels - 1));
        int sourceY = (int)((pixelOffset >> 10) & 0x3ff);
        int origin = (int)((_registers[RegFbiInit3] >> 22) & 0x3ff);
        int y = (origin > 0 ? Math.Min(origin, LfbRows - 1) : 479) - sourceY;
        if ((uint)y >= LfbRows)
            y = y < 0 ? 0 : LfbRows - 1;

        int bufferIndex = _backBufferIndex;
        _lastFastFillValid[bufferIndex] = false;
        ushort[] buffer = _colorBuffers[bufferIndex];
        int pixel = y * LfbRowPixels + x;
        buffer[pixel & (LfbPixels - 1)] = ConvertXrgb1555Lane0((ushort)value);
        buffer[(pixel + 1) & (LfbPixels - 1)] = ConvertXrgb1555Lane0((ushort)(value >> 16));
        _lfbWriteCount++;
    }

    private void MirrorLfbWriteToCommandFifoStorage(uint offset, uint value)
    {
        if (!_fixMameCommandFifoModel ||
            !_experimentMameCommandFifoFramebufferStorage ||
            !_experimentMameCommandFifoMirrorLfbWrites)
        {
            return;
        }

        _cmdFifoRam[CommandFifoStorageIndex((int)(offset >> 2))] = value;
    }

    public virtual void WriteTexture32(uint offset, uint value)
        => WriteTexturePort32((offset >> 2) & (TextureWords - 1), value);

    private void WriteTexturePort32(uint wordOffset, uint value)
    {
        uint lod = (wordOffset >> 15) & 0x0fu;
        if (lod > 8)
            return;

        uint mode = ReadTextureRegister(RegTextureMode);
        uint texLod = ReadTextureRegister(RegTextureLod);
        if (((texLod >> 25) & 1u) != 0)
            value = BinaryPrimitives.ReverseEndianness(value);
        if (((texLod >> 26) & 1u) != 0)
            value = (value >> 16) | (value << 16);

        int bytesPerTexel = ((mode >> 8) & 0x0fu) < 8 ? 1 : 2;
        if (_fixLinearTextureDownloadAddressing)
        {
            WriteTextureLinear32(wordOffset, value, bytesPerTexel);
            _textureWriteCount++;
            return;
        }

        bool seq8Downld = ((mode >> 31) & 1u) != 0 || (_fixSequential8BitTextureDownload && bytesPerTexel == 1);
        uint tt = (wordOffset >> 7) & 0xffu;
        uint ts = (wordOffset << ((seq8Downld && bytesPerTexel == 1) ? 2 : 1)) & 0xffu;
        uint width = GetTextureWidth();
        uint height = GetTextureHeight();
        uint xMask = Math.Max(1u, width >> (int)lod) - 1u;
        uint yMask = Math.Max(1u, height >> (int)lod) - 1u;
        uint texel = (tt & yMask) * (xMask + 1u) + (ts & xMask);
        uint byteOffset = (GetTextureLodOffset((int)lod, bytesPerTexel) + texel * (uint)bytesPerTexel) & (TextureBytes - 1u);

        if (bytesPerTexel == 1)
        {
            bool previousSuppressZero = _suppressZeroTextureBytesForCurrentWrite;
            _suppressZeroTextureBytesForCurrentWrite = _fixSparse8BitTextureUpload;
            try
            {
                WriteTextureByte(byteOffset + 0u, (byte)value);
                WriteTextureByte(byteOffset + 1u, (byte)(value >> 8));
                WriteTextureByte(byteOffset + 2u, (byte)(value >> 16));
                WriteTextureByte(byteOffset + 3u, (byte)(value >> 24));
            }
            finally
            {
                _suppressZeroTextureBytesForCurrentWrite = previousSuppressZero;
            }
        }
        else
        {
            WriteTextureUInt16(byteOffset + 0u, (ushort)value);
            WriteTextureUInt16(byteOffset + 2u, (ushort)(value >> 16));
        }

        _textureWriteCount++;
    }

    private void WriteTextureLinear32(uint wordOffset, uint value, int bytesPerTexel)
    {
        uint byteOffset = (wordOffset << 2) & (TextureBytes - 1u);
        if (bytesPerTexel == 1)
        {
            bool previousSuppressZero = _suppressZeroTextureBytesForCurrentWrite;
            _suppressZeroTextureBytesForCurrentWrite = _fixSparse8BitTextureUpload;
            try
            {
                WriteTextureByte(byteOffset + 0u, (byte)value);
                WriteTextureByte(byteOffset + 1u, (byte)(value >> 8));
                WriteTextureByte(byteOffset + 2u, (byte)(value >> 16));
                WriteTextureByte(byteOffset + 3u, (byte)(value >> 24));
            }
            finally
            {
                _suppressZeroTextureBytesForCurrentWrite = previousSuppressZero;
            }
        }
        else
        {
            WriteTextureUInt16(byteOffset + 0u, (ushort)value);
            WriteTextureUInt16(byteOffset + 2u, (ushort)(value >> 16));
        }
    }

    private void WriteTextureByte(uint byteOffset, byte value)
    {
        uint wordOffset = (byteOffset & (TextureBytes - 1u)) >> 2;
        int shift = (int)((byteOffset & 3u) * 8u);
        uint mask = 0xffu << shift;
        if ((_preserveNonZeroTextureBytes || _suppressZeroTextureBytesForCurrentWrite) &&
            value == 0 &&
            (_textureMemory[wordOffset] & mask) != 0)
        {
            TrackTextureMappedWrite((int)wordOffset, value);
            return;
        }

        _textureMemory[wordOffset] = (_textureMemory[wordOffset] & ~mask) | ((uint)value << shift);
        TrackTextureMappedWrite((int)wordOffset, value);
    }

    private void TrackTextureMappedWrite(int wordOffset, uint value)
    {
        _textureMappedWriteCount++;
        if (value == 0)
            _textureMappedZeroWriteCount++;
        else
            _textureMappedNonZeroWriteCount++;

        if (!_textureTouchedWords[wordOffset])
        {
            _textureTouchedWords[wordOffset] = true;
            _textureTouchedWordCount++;
            if (_textureTouchedFirstWord < 0 || wordOffset < _textureTouchedFirstWord)
                _textureTouchedFirstWord = wordOffset;
            if (wordOffset > _textureTouchedLastWord)
                _textureTouchedLastWord = wordOffset;
        }
    }

    private void WriteTextureUInt16(uint byteOffset, ushort value)
    {
        uint aligned = byteOffset & ~1u;
        WriteTextureByte(aligned, (byte)value);
        WriteTextureByte(aligned + 1u, (byte)(value >> 8));
    }

    public virtual uint ReadTexture32(uint offset)
        => _textureMemory[(offset >> 2) & (TextureWords - 1)];

    public void RenderFrame(EutherFrameTarget target)
    {
        if (!HasVideoActivity || target.Buffer is null || target.Width <= 0 || target.Height <= 0 || target.Stride < target.Width * 4)
            return;

        _renderFrame++;
        if (!TryRenderLfb(target))
        {
            Clear(target, 0xff080b0fu);
            DrawRegisterBands(target);
        }
        if (_showDebugOverlay)
            DrawViewportOverlay(target);
    }

    private bool TryRenderLfb(EutherFrameTarget target)
    {
        if (_lfbWriteCount == 0)
            return false;

        int copyWidth = Math.Min(target.Width, 640);
        int copyHeight = Math.Min(target.Height, 480);
        int renderBufferIndex = ChooseRenderBufferIndex();
        _lastRenderBufferIndex = renderBufferIndex;
        if (ShouldMaterializePendingClearForRender(renderBufferIndex))
            MaterializePendingClear(renderBufferIndex);
        ushort[] front = _colorBuffers[renderBufferIndex];
        for (int y = 0; y < copyHeight; y++)
        {
            int src = y * 1024;
            int dst = y * target.Stride;
            for (int x = 0; x < copyWidth; x++)
            {
                ushort rgb = front[(src + x) & (LfbPixels - 1)];
                uint bgra = Rgb565ToBgra(rgb);
                target.Buffer[dst + 0] = (byte)(bgra & 0xff);
                target.Buffer[dst + 1] = (byte)((bgra >> 8) & 0xff);
                target.Buffer[dst + 2] = (byte)((bgra >> 16) & 0xff);
                target.Buffer[dst + 3] = 0xff;
                dst += 4;
            }
        }

        return _lfbWriteCount > 0;
    }

    private int ChooseRenderBufferIndex()
    {
        if (!_fixDisplayBufferSelection)
            return _frontBufferIndex;

        int frontCount = GetBufferNonZeroCount(_frontBufferIndex);
        int frontActiveCount = GetVisibleBufferActiveColorCount(_frontBufferIndex);
        int frontWhiteCount = GetVisibleBufferWhiteCount(_frontBufferIndex);
        bool frontIsWhiteClearDominated = frontWhiteCount > 240_000 && frontActiveCount < 32_000;
        if (!frontIsWhiteClearDominated && frontCount > 1024 && frontActiveCount > 1024)
            return _frontBufferIndex;

        int bestIndex = _frontBufferIndex;
        int bestCount = frontCount;
        int bestActiveCount = frontActiveCount;
        int count = GetColorBufferCount();
        for (int i = 0; i < count; i++)
        {
            if (i == _frontBufferIndex)
                continue;

            int candidateCount = GetBufferNonZeroCount(i);
            int candidateActiveCount = GetVisibleBufferActiveColorCount(i);
            if (IsPendingClearBuffer(i) && candidateActiveCount <= 1024)
                continue;

            if (candidateCount > 1024 &&
                candidateActiveCount > 1024 &&
                (candidateActiveCount > bestActiveCount ||
                 bestActiveCount <= 1024 && candidateCount > bestCount ||
                 frontIsWhiteClearDominated && candidateActiveCount >= bestActiveCount * 3 / 4))
            {
                bestIndex = i;
                bestCount = candidateCount;
                bestActiveCount = candidateActiveCount;
                frontIsWhiteClearDominated = false;
            }
        }

        return bestIndex;
    }

    private bool ShouldMaterializePendingClearForRender(int bufferIndex)
    {
        if ((uint)bufferIndex >= (uint)_pendingClearValid.Length || !_pendingClearValid[bufferIndex])
            return false;

        return GetBufferNonZeroCount(bufferIndex) == 0;
    }

    private bool IsPendingClearBuffer(int bufferIndex)
        => (uint)bufferIndex < (uint)_pendingClearValid.Length && _pendingClearValid[bufferIndex];

    private void DrawRegisterBands(EutherFrameTarget target)
    {
        int bandHeight = Math.Max(6, target.Height / 64);
        for (int i = 0; i < 32; i++)
        {
            uint register = i < 16
                ? (0x100u >> 2) + (uint)i
                : (0x200u >> 2) + (uint)(i - 16);
            uint value = _registers[register];
            uint color = 0xff000000u |
                ((value << 3) & 0x00ff0000u) |
                ((value >> 5) & 0x0000ff00u) |
                ((value >> 13) & 0x000000ffu);
            FillRect(target, 0, i * bandHeight, target.Width, bandHeight, color);
        }
    }

    private void DrawViewportOverlay(EutherFrameTarget target)
    {
        uint clipX = _registers[(0x118u >> 2) & 0x3ffu];
        uint clipY = _registers[(0x11cu >> 2) & 0x3ffu];
        int x0 = (int)((clipX >> 16) & 0x7ff);
        int x1 = (int)(clipX & 0x7ff);
        int y0 = (int)((clipY >> 16) & 0x7ff);
        int y1 = (int)(clipY & 0x7ff);
        if (x1 <= x0 || x1 > target.Width)
        {
            uint dimensions = _registers[(0x20cu >> 2) & 0x3ffu];
            x0 = 0;
            x1 = dimensions != 0
                ? Math.Clamp((int)(dimensions & 0x7ff) + 1, 1, target.Width)
                : target.Width;
        }
        if (y1 <= y0 || y1 > target.Height)
        {
            uint dimensions = _registers[(0x20cu >> 2) & 0x3ffu];
            y0 = 0;
            y1 = dimensions != 0
                ? Math.Clamp((int)((dimensions >> 16) & 0x7ff), 1, target.Height)
                : target.Height;
        }

        DrawRect(target, x0, y0, x1 - x0, y1 - y0, 0xffffffffu);

        int sweep = _renderFrame % Math.Max(1, target.Width);
        FillRect(target, sweep, y0, 4, y1 - y0, 0xff00d7ffu);
        FillRect(target, 16, target.Height - 28, Math.Min(target.Width - 32, _registerWriteCount / 32), 8, 0xff39d353u);
        FillRect(target, 16, target.Height - 18, Math.Min(target.Width - 32, (int)Math.Min(int.MaxValue, _lfbWriteCount / 64)), 8, 0xfff7b955u);
        FillRect(target, 16, target.Height - 8, Math.Min(target.Width - 32, (_fifoWriteCount + _fifoPacketCount * 8 + _textureWriteCount) / 256), 6, 0xffc678ddU);
        FillRect(target, target.Width - 24, 16, 8, Math.Min(target.Height - 32, _fifoDrawPacketCount * 4), 0xffff6b6bu);
        FillRect(target, target.Width - 40, 16, 8, Math.Min(target.Height - 32, _fastFillCount * 4), 0xff39d353u);
        FillRect(target, target.Width - 56, 16, 8, Math.Min(target.Height - 32, _swapBufferCount * 4), 0xfff7b955u);
    }

    private void FastFill()
    {
        uint clipX = _registers[0x46];
        uint clipY = _registers[0x47];
        int x0 = Math.Clamp((int)((clipX >> 16) & 0x7ff), 0, 1024);
        int x1 = Math.Clamp((int)(clipX & 0x7ff), 0, 1024);
        int y0 = Math.Clamp((int)((clipY >> 16) & 0x7ff), 0, 1024);
        int y1 = Math.Clamp((int)(clipY & 0x7ff), 0, 1024);
        if (x1 <= x0)
        {
            x0 = 0;
            x1 = 640;
        }
        if (y1 <= y0)
        {
            y0 = 0;
            y1 = 480;
        }

        x1 = Math.Min(x1, 1024);
        y1 = Math.Min(y1, LfbRows);
        ushort color = ArgbToRgb565(_registers[RegColor1]);
        if (color == 0)
            color = ArgbToRgb565(_registers[RegColor0]);
        if (color == 0)
            color = (ushort)_registers[RegZaColor];

        TraceDraw($"fastfill clip=({x0},{y0})-({x1},{y1}) color=0x{color:X4} c0=0x{_registers[RegColor0]:X8} c1=0x{_registers[RegColor1]:X8} fbz=0x{_registers[RegFbzMode]:X8}");
        if (_traceNonNeutralFastFill && color != 0 && color != 0xffff && _nonNeutralFastFillTraceCount++ < 64)
        {
            ulong pc = CpuPcProvider?.Invoke() ?? 0;
            string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
            Console.WriteLine(
                $"[GAUNTDL:VOODOO-FILL] clip=({x0},{y0})-({x1},{y1}) color=0x{color:X4} " +
                $"c0=0x{_registers[RegColor0]:X8} c1=0x{_registers[RegColor1]:X8} za=0x{_registers[RegZaColor]:X8} " +
                $"fbz=0x{_registers[RegFbzMode]:X8}{pcStatus}");
        }

        if (_fixFastFillColorWriteMask && (_registers[RegFbzMode] & 0x400U) == 0)
        {
            TraceFastFillSwapOrder("fastfill-suppressed", RegFastfillCommand, color);
            if (color == 0xffff)
                _fastFillSuppressedWhiteCount++;
            else if (color == 0)
                _fastFillSuppressedBlackCount++;
            else
                _fastFillSuppressedOtherCount++;
            CountFastFillPc(color, suppressed: true, bufferIndex: -1);
            _fastFillCount++;
            return;
        }

        int bufferIndex = GetDrawBufferIndex();
        TraceFastFillSwapOrder("fastfill", RegFastfillCommand, color);
        CountFastFillPc(color, suppressed: false, bufferIndex);
        if ((uint)bufferIndex < (uint)_fastFillBufferCounts.Length)
        {
            _fastFillBufferCounts[bufferIndex]++;
            if (color == 0xffff)
                _fastFillWhiteBufferCounts[bufferIndex]++;
            else if (color == 0)
                _fastFillBlackBufferCounts[bufferIndex]++;
            else
                _fastFillOtherBufferCounts[bufferIndex]++;
        }

        int width = x1 - x0;
        if (!IsCachedFastFill(bufferIndex, x0, x1, y0, y1, color))
        {
            SetPendingClear(bufferIndex, x0, x1, y0, y1, color);
            CacheFastFill(bufferIndex, x0, x1, y0, y1, color);
        }

        _fastFillCount++;
        _lfbWriteCount += Math.Max(1, (width * (y1 - y0) + 1) / 2);
    }

    private void DecodeCommandFifoPackets(string trigger = "direct")
    {
        if (_decodingCommandFifo)
            return;

        _decodingCommandFifo = true;
        string previousTrigger = _commandFifoDecodeTrigger;
        _commandFifoDecodeTrigger = trigger;
        try
        {
        int guard = 0;
        int decodedThisCall = 0;
        ulong decodeCallPc = CpuPcProvider?.Invoke() ?? 0;
        int decodeCallStartReadIndex = _cmdFifoReadIndex;
        int decodeCallStartDepth = _cmdFifoDepth;
        uint decodeCallFirstCommand = 0;
        uint decodeCallLastCommand = 0;
        uint decodeCallTypeMask = 0;
        int packetLimit = _fixMameCommandFifoModel && _experimentMameCommandFifoDecodePacketLimit > 0
            ? _experimentMameCommandFifoDecodePacketLimit
            : 2048;
        while (guard++ < 2048 && decodedThisCall < packetLimit && IsCommandFifoPacketReady())
        {
            int packetStart = _cmdFifoReadIndex;
            uint command = _cmdFifoRam[CommandFifoStorageIndex(packetStart)];
            if (_fixMameCommandFifoModel &&
                _experimentMameCommandFifoYieldOnType5Boundary &&
                decodedThisCall > 0 &&
                decodeCallTypeMask == (1u << 5) &&
                (command & 7u) != 5u)
            {
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "type5-boundary");
                return;
            }
            if (decodedThisCall == 0)
                decodeCallFirstCommand = command;
            decodeCallLastCommand = command;
            decodeCallTypeMask |= 1u << (int)(command & 7u);
            if (_fixMameCommandFifoModel &&
                _experimentMameCommandFifoStopOnUnknown &&
                (command & 7u) > 5u)
            {
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "unknown");
                TraceCommandFifoDecodeStop("unknown", command, 1);
                return;
            }

            int wordsNeeded = GetFifoPacketWordsNeeded(command);
            if (IsKnownGauntletRuntimeMisalignedFifoWord(command, wordsNeeded))
                wordsNeeded = 1;
            if (wordsNeeded <= 0)
                wordsNeeded = 1;
            if (_fixMameCommandFifoModel && _cmdFifoDepth < wordsNeeded)
            {
                if (TryTruncateMameCommandFifoPartialType4(command, wordsNeeded, out int truncatedWordsNeeded))
                    wordsNeeded = truncatedWordsNeeded;
                else if (_experimentMameCommandFifoAllowValidPacketDepthShort &&
                         HasCommandFifoWords(packetStart, wordsNeeded))
                {
                    TraceCommandFifoDecodeStop("depth-short-valid-window", command, wordsNeeded);
                }
                else
                {
                if (TryResyncMameCommandFifoOnPartialType5(command, packetStart, wordsNeeded))
                    continue;

                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "depth");
                TraceCommandFifoDecodeStop("depth", command, wordsNeeded);
                return;
                }
            }
            if (_cmdFifoBulkDecodeRemainingWords > 0 && wordsNeeded > _cmdFifoBulkDecodeRemainingWords)
            {
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "bulk-window");
                TraceCommandFifoDecodeStop("bulk-window", command, wordsNeeded);
                return;
            }
            if (_fixMameCommandFifoModel &&
                _experimentMameCommandFifoRequirePacketInAddressWindow &&
                _cmdFifoAddressMin >= _cmdFifoRamBase &&
                !IsMameCommandFifoPacketInsideAddressWindow(packetStart, wordsNeeded))
            {
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "packet-outside-window");
                TraceCommandFifoDecodeStop("packet-outside-window", command, wordsNeeded);
                return;
            }
            if (_fixMameCommandFifoModel &&
                _experimentMameCommandFifoRequireValidPacketWindow &&
                !HasCommandFifoWords(packetStart, wordsNeeded))
            {
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "invalid-packet-window");
                TraceCommandFifoDecodeStop("invalid-packet-window", command, wordsNeeded);
                return;
            }
            if (!_fixMameCommandFifoModel && !HasCommandFifoWords(packetStart, wordsNeeded))
            {
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "invalid-standard-window");
                return;
            }

            _fifoBuffer.Clear();
            for (int i = 0; i < wordsNeeded; i++)
            {
                int index = CommandFifoStorageIndex(packetStart + i);
                _fifoBuffer.Add(_cmdFifoRam[index]);
            }

            _cmdFifoJumped = false;
            _commandFifoPacketIssuedRenderWork = false;
            _currentCommandFifoCommand = command;
            _currentCommandFifoPacketStart = packetStart;
            _currentCommandFifoWordsNeeded = wordsNeeded;
            CountCommandFifoPacketPc(command, wordsNeeded, packetStart);
            bool packetConsumedByHandler = false;
            if (_fixMameCommandFifoModel &&
                _experimentMameCommandFifoType5Streaming &&
                (command & 7u) == 5u)
            {
                _cmdFifoReadIndex = DecodeCommandFifoReadIndex(packetStart + 1);
                _cmdFifoDepth = Math.Max(0, _cmdFifoDepth - 1);
                _cmdFifoDepthWordsStreamed++;
                packetConsumedByHandler = true;
            }
            DecodeFifoPacket(command, wordsNeeded);
            _currentCommandFifoCommand = 0;
            _currentCommandFifoPacketStart = 0;
            _currentCommandFifoWordsNeeded = 0;
            bool packetDidWork = IsCommandFifoPacketWork(command);
            _fifoPacketCount++;
            decodedThisCall++;
            for (int i = 0; i < wordsNeeded; i++)
            {
                int validIndex = CommandFifoStorageIndex(packetStart + i);
                if (_cmdFifoValid[validIndex])
                {
                    _cmdFifoValid[validIndex] = false;
                    _cmdFifoValidCount = Math.Max(0, _cmdFifoValidCount - 1);
                }
            }
            if (!packetConsumedByHandler)
            {
                _cmdFifoDepth = Math.Max(0, _cmdFifoDepth - wordsNeeded);
                _cmdFifoDepthWordsDecoded += wordsNeeded;
            }
            TraceCommandFifoValidity("decode", CommandFifoStorageIndex(packetStart));
            if (_cmdFifoBulkDecodeRemainingWords > 0)
                _cmdFifoBulkDecodeRemainingWords = Math.Max(0, _cmdFifoBulkDecodeRemainingWords - wordsNeeded);
            if (!_cmdFifoJumped && !packetConsumedByHandler)
                _cmdFifoReadIndex = DecodeCommandFifoReadIndex(packetStart + wordsNeeded);
            if (_fixMameCommandFifoModel &&
                _experimentMameCommandFifoOperationPendingGate &&
                _commandFifoPacketIssuedRenderWork)
            {
                _commandFifoOperationPending = true;
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "operation-pending");
                return;
            }
            if (_fixMameCommandFifoModel && _experimentMameCommandFifoYieldOnRenderWork && _commandFifoPacketIssuedRenderWork)
            {
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "yield-render");
                return;
            }
            if (_fixMameCommandFifoModel && _experimentMameCommandFifoYieldOnWork && packetDidWork)
            {
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "yield-work");
                return;
            }
        }
        CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, guard >= 2048 ? "guard" : "ready-empty");
        }
        finally
        {
            _commandFifoDecodeTrigger = previousTrigger;
            _decodingCommandFifo = false;
        }
    }

    private void DecodeCommandFifoPacketsIfNotPending(string trigger = "direct")
    {
        if (IsCommandFifoOperationPending())
            return;

        DecodeCommandFifoPackets(trigger);
    }

    private bool IsCommandFifoPacketReady()
    {
        if (!_fixMameCommandFifoModel)
            return _cmdFifoValid[_cmdFifoReadIndex & CmdFifoMask];

        if (_cmdFifoDepth <= 0)
            return false;

        if (_experimentMameCommandFifoRequireReadInAddressWindow &&
            _cmdFifoAddressMin >= _cmdFifoRamBase &&
            !IsMameCommandFifoReadInsideAddressWindow())
        {
            TraceCommandFifoDecodeStop("read-outside-window", PeekCommandFifoWord(), 1);
            return false;
        }

        if (_experimentMameCommandFifoRequireStorageGeneration &&
            !IsCommandFifoWordValidForRead(_cmdFifoReadIndex))
        {
            TraceCommandFifoDecodeStop("storage-generation", PeekCommandFifoWord(), 1);
            return false;
        }

        if ((_experimentMameCommandFifoSkipWrapGapInvalidRead ||
             _experimentMameCommandFifoConsumeWrapGapInvalidRead) &&
            !IsCommandFifoWordValidForRead(_cmdFifoReadIndex))
        {
            int readStorage = CommandFifoStorageIndex(_cmdFifoReadIndex);
            int gapToBase = CmdFifoWords - readStorage;
            if (readStorage != 0 &&
                gapToBase <= 64 &&
                IsCommandFifoWordValidForRead(_cmdFifoReadIndex + gapToBase))
            {
                _cmdFifoReadIndex = DecodeCommandFifoReadIndex(_cmdFifoReadIndex + gapToBase);
                if (_experimentMameCommandFifoConsumeWrapGapInvalidRead)
                    _cmdFifoDepth = Math.Max(0, _cmdFifoDepth - gapToBase);
            }
        }

        if (_experimentMameCommandFifoSkipInvalidStorage)
        {
            int skipped = 0;
            while (_cmdFifoDepth > 0 && !IsCommandFifoWordValidForRead(_cmdFifoReadIndex) && skipped++ < CommandFifoStorageWords())
            {
                _cmdFifoReadIndex = DecodeCommandFifoReadIndex(_cmdFifoReadIndex + 1);
                _cmdFifoDepth--;
            }
            if (_cmdFifoDepth <= 0 || !IsCommandFifoWordValidForRead(_cmdFifoReadIndex))
            {
                TraceCommandFifoDecodeStop("skip-invalid-storage", PeekCommandFifoWord(), 1);
                return false;
            }
        }

        if (_experimentMameCommandFifoRequireValidStorage && !IsCommandFifoWordValidForRead(_cmdFifoReadIndex))
        {
            if (_experimentMameCommandFifoResyncInvalidStorageToAddressMin && _cmdFifoAddressMin >= _cmdFifoRamBase)
            {
                int addressMinIndex = DecodeCommandFifoReadIndex(_cmdFifoAddressMin >> 2);
                if (IsCommandFifoWordValidForRead(addressMinIndex))
                {
                    TraceCommandFifoDecodeStop("invalid-storage-resync-amin", PeekCommandFifoWord(), 1);
                    _cmdFifoReadIndex = addressMinIndex;
                    return true;
                }
            }

            TraceCommandFifoDecodeStop("invalid-storage", PeekCommandFifoWord(), 1);
            return false;
        }

        return true;
    }

    private bool IsMameCommandFifoReadInsideAddressWindow()
        => IsMameCommandFifoWordInsideAddressWindow(_cmdFifoReadIndex);

    private bool IsMameCommandFifoPacketInsideAddressWindow(int start, int wordsNeeded)
    {
        for (int i = 0; i < wordsNeeded; i++)
        {
            if (!IsMameCommandFifoWordInsideAddressWindow(start + i))
                return false;
        }

        return true;
    }

    private bool IsMameCommandFifoWordInsideAddressWindow(int wordIndex)
    {
        int readByte = wordIndex * 4;
        if (_cmdFifoAddressMin <= _cmdFifoAddressMax)
            return readByte >= _cmdFifoAddressMin && readByte <= _cmdFifoAddressMax;

        int readStorageByte = CommandFifoStorageIndex(wordIndex) * 4;
        int minStorageByte = CommandFifoStorageIndex(_cmdFifoAddressMin >> 2) * 4;
        int maxStorageByte = CommandFifoStorageIndex(_cmdFifoAddressMax >> 2) * 4;
        return readStorageByte >= minStorageByte || readStorageByte <= maxStorageByte;
    }

    private bool TryResyncMameCommandFifoOnPartialType5(uint command, int packetStart, int wordsNeeded)
    {
        if (!_experimentMameCommandFifoResyncAddressMinOnPartialType5 ||
            !IsType5TexturePacketHeader(command) ||
            _cmdFifoAddressMin < _cmdFifoRamBase)
        {
            return false;
        }

        int addressMinIndex = _cmdFifoAddressMin >> 2;
        if (CommandFifoStorageIndex(addressMinIndex) == CommandFifoStorageIndex(packetStart))
            return false;

        TraceCommandFifoDecodeStop("partial-type5-resync-amin", command, wordsNeeded);
        _cmdFifoReadIndex = DecodeCommandFifoReadIndex(addressMinIndex);
        return true;
    }

    private bool TryTruncateMameCommandFifoPartialType4(uint command, int wordsNeeded, out int truncatedWordsNeeded)
    {
        truncatedWordsNeeded = wordsNeeded;
        if (!_experimentMameCommandFifoTruncatePartialType4 ||
            (command & 7u) != 4u ||
            _cmdFifoDepth <= 1 ||
            _cmdFifoDepth >= wordsNeeded)
        {
            return false;
        }

        truncatedWordsNeeded = _cmdFifoDepth;
        TraceCommandFifoDecodeStop("partial-type4-truncate", command, wordsNeeded);
        return true;
    }

    private int DecodeCommandFifoReadIndex(int value)
        => _fixMameCommandFifoModel && !_experimentMameCommandFifoMaskReadIndex
            ? value
            : CommandFifoStorageIndex(value);

    private int CommandFifoStorageIndex(int value)
        => value & CommandFifoStorageMask();

    private int CommandFifoStorageMask()
        => _fixMameCommandFifoModel && _experimentMameCommandFifoFramebufferStorage
            ? CmdFifoFramebufferMask
            : CmdFifoMask;

    private int CommandFifoStorageWords()
        => _fixMameCommandFifoModel && _experimentMameCommandFifoFramebufferStorage
            ? CmdFifoFramebufferWords
            : CmdFifoWords;

    private void TraceCommandFifoDecodeStop(string reason, uint command, int wordsNeeded)
    {
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        _lastCommandFifoDecodeStopReason = reason;
        _lastCommandFifoDecodeStopCommand = command;
        _lastCommandFifoDecodeStopWordsNeeded = wordsNeeded;
        _lastCommandFifoDecodeStopDepth = _cmdFifoDepth;
        _lastCommandFifoDecodeStopReadIndex = _cmdFifoReadIndex;
        _lastCommandFifoDecodeStopStorageIndex = CommandFifoStorageIndex(_cmdFifoReadIndex);
        _lastCommandFifoDecodeStopNext1 = _cmdFifoRam[CommandFifoStorageIndex(_lastCommandFifoDecodeStopStorageIndex + 1)];
        _lastCommandFifoDecodeStopNext2 = _cmdFifoRam[CommandFifoStorageIndex(_lastCommandFifoDecodeStopStorageIndex + 2)];
        _lastCommandFifoDecodeStopPc = pc;
        _commandFifoDecodeStopCount++;

        if (!_traceCommandFifoModel)
            return;

        if (_traceCommandFifoModelPcs.Length != 0 && !_traceCommandFifoModelPcs.Contains(pc))
            return;
        if (_traceCommandFifoModelCommands.Length != 0 && !_traceCommandFifoModelCommands.Contains(command))
            return;
        if (_commandFifoModelStallTraceCount++ >= 160)
            return;

        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        int readStorage = CommandFifoStorageIndex(_cmdFifoReadIndex);
        uint next1 = _cmdFifoRam[CommandFifoStorageIndex(readStorage + 1)];
        uint next2 = _cmdFifoRam[CommandFifoStorageIndex(readStorage + 2)];
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-CMDFIFO] stop reason={reason} cmd=0x{command:x8} type={command & 7u} " +
            $"words={wordsNeeded} rd=0x{_cmdFifoReadIndex * 4:x8} storage=0x{readStorage * 4:x5} " +
            $"next=0x{next1:x8}/0x{next2:x8} depth={_cmdFifoDepth} holes={_cmdFifoHoles} valid={_cmdFifoValidCount} " +
            $"amin=0x{_cmdFifoAddressMin:x8} amax=0x{_cmdFifoAddressMax:x8} " +
            $"fifoPackets={_fifoPacketCount} drawPackets={_fifoDrawPacketCount}{pcStatus}");
    }

    private bool HasCommandFifoWords(int start, int count)
    {
        for (int i = 0; i < count; i++)
        {
            if (!IsCommandFifoWordValidForRead(start + i))
                return false;
        }

        return true;
    }

    private bool IsCommandFifoWordValidForRead(int logicalIndex)
    {
        int storageIndex = CommandFifoStorageIndex(logicalIndex);
        if (!_cmdFifoValid[storageIndex])
            return false;
        return !_fixMameCommandFifoModel ||
               !_experimentMameCommandFifoRequireStorageGeneration ||
               _cmdFifoStorageLogicalIndex[storageIndex] == logicalIndex;
    }

    private uint ReadCommandFifoStreamingWord()
    {
        uint value = _cmdFifoRam[CommandFifoStorageIndex(_cmdFifoReadIndex)];
        _cmdFifoReadIndex = DecodeCommandFifoReadIndex(_cmdFifoReadIndex + 1);
        _cmdFifoDepth = Math.Max(0, _cmdFifoDepth - 1);
        _cmdFifoDepthWordsStreamed++;
        return value;
    }

    private static bool IsCommandFifoPacketWork(uint command)
        => (command & 7u) is 1u or 2u or 3u or 4u or 5u;

    private void DecodeFifoPacket(uint command, int wordsNeeded)
    {
        _fifoPacketTypeCounts[command & 7u]++;
        TraceOddFifoPacket(command, wordsNeeded);
        RecordInterestingFifoEvent(command, wordsNeeded);
        if (IsKnownGauntletRuntimeNoopFifoPacket(command, wordsNeeded))
            return;

        switch (command & 7u)
        {
            case 0:
                DecodeFifoType0(command);
                break;
            case 1:
                DecodeFifoType1(command);
                break;
            case 2:
                DecodeFifoType2(command);
                break;
            case 3:
                MarkCommandFifoRenderWork();
                _fifoDrawPacketCount++;
                DecodeFifoType3(command, wordsNeeded);
                break;
            case 4:
                DecodeFifoType4(command);
                break;
            case 5:
                DecodeFifoType5(command, wordsNeeded);
                break;
        }
    }

    private void TraceOddFifoPacket(uint command, int wordsNeeded)
    {
        uint type = command & 7u;
        if (!_traceOddFifoPackets || type is not (2u or 6u or 7u) || _oddFifoPacketTraceCount++ >= 96)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        uint w1 = _fifoBuffer.Count > 1 ? _fifoBuffer[1] : 0;
        uint w2 = _fifoBuffer.Count > 2 ? _fifoBuffer[2] : 0;
        uint w3 = _fifoBuffer.Count > 3 ? _fifoBuffer[3] : 0;
        uint w4 = _fifoBuffer.Count > 4 ? _fifoBuffer[4] : 0;
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-ODD-FIFO] n={_oddFifoPacketTraceCount} type={type} " +
            $"cmd=0x{command:x8} words={wordsNeeded} rd=0x{_cmdFifoReadIndex:x4} " +
            $"fifoPackets={_fifoPacketCount} drawPackets={_fifoDrawPacketCount} " +
            $"w=0x{w1:x8}/0x{w2:x8}/0x{w3:x8}/0x{w4:x8} " +
            $"mame={(_fixMameCommandFifoModel ? 1 : 0)} depth={_cmdFifoDepth} holes={_cmdFifoHoles} " +
            $"base=0x{_cmdFifoRamBase:x5} amin=0x{_cmdFifoAddressMin:x8} amax=0x{_cmdFifoAddressMax:x8} " +
            $"fbz=0x{_registers[RegFbzMode]:x8} lfb=0x{_registers[RegLfbMode]:x8} " +
            $"tmode=0x{ReadTextureRegister(RegTextureMode):x8} tlod=0x{ReadTextureRegister(RegTextureLod):x8} " +
            $"tbase=0x{ReadTextureRegister(RegTextureBaseAddr):x8}{pcStatus}");
    }

    private bool IsKnownGauntletRuntimeNoopFifoPacket(uint command, int wordsNeeded)
        => command == 0x00010241U &&
           wordsNeeded == 2 &&
           _fifoBuffer.Count >= 2 &&
           _fifoBuffer[1] == 0 &&
           _registers[0x48] == 0;

    private bool IsKnownGauntletRuntimeMisalignedFifoWord(uint command, int wordsNeeded)
        => command == _registers[0x41] &&
           command == 0x0c482435U &&
           (command & 7u) == 5u &&
           wordsNeeded > 0x10000;

    private void DecodeFifoType0(uint command)
    {
        int function = (int)((command >> 3) & 7u);
        int target = (int)((command >> 6) & 0x7fffffu);
        int readBefore = _cmdFifoReadIndex;
        int readAfter = readBefore;
        if (function == 3)
        {
            readAfter = DecodeCommandFifoLocalJumpTarget(target);
            _cmdFifoReadIndex = readAfter;
            _cmdFifoJumped = true;
            _cmdFifoLocalJumpCount++;
        }

        TraceType0Packet(command, function, target, readBefore, readAfter);
    }

    private int DecodeCommandFifoLocalJumpTarget(int target)
        => _fixMameCommandFifoModel && _experimentMameCommandFifoMaskLocalJump
            ? CommandFifoStorageIndex(target)
            : DecodeCommandFifoReadIndex(target);

    private void TraceType0Packet(uint command, int function, int target, int readBefore, int readAfter)
    {
        if (!_traceType0Packets || _type0PacketTraceCount++ >= _traceType0PacketsLimit)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-TYPE0] n={_type0PacketTraceCount} cmd=0x{command:x8} fn={function} " +
            $"target=0x{target:x6} rdBefore=0x{readBefore * 4:x8} rdAfter=0x{readAfter * 4:x8} " +
            $"storageBefore=0x{CommandFifoStorageIndex(readBefore) * 4:x5} storageAfter=0x{CommandFifoStorageIndex(readAfter) * 4:x5} " +
            $"mame={(_fixMameCommandFifoModel ? 1 : 0)} depth={_cmdFifoDepth} holes={_cmdFifoHoles} " +
            $"base=0x{_cmdFifoRamBase:x5} amin=0x{_cmdFifoAddressMin:x8} amax=0x{_cmdFifoAddressMax:x8} " +
            $"fifoPackets={_fifoPacketCount} drawPackets={_fifoDrawPacketCount}{pcStatus}");
    }

    private void DecodeFifoType1(uint command)
    {
        int count = (int)(command >> 16);
        int increment = ((command >> 15) & 1u) != 0 ? 1 : 0;
        uint target = (command >> 3) & 0xfffu;
        int available = Math.Min(count, Math.Max(0, _fifoBuffer.Count - 1));
        for (int i = 0; i < available; i++, target += (uint)increment)
        {
            uint value = _fifoBuffer[1 + i];
            WriteCmdFifoRegister(target, value);
        }
    }

    private void DecodeFifoType2(uint command)
    {
        int source = 1;
        for (uint regbit = 3; regbit <= 31 && source < _fifoBuffer.Count; regbit++)
        {
            if (((command >> (int)regbit) & 1u) != 0)
                WriteCmdFifoRegister(RegBltSrcBaseAddr + regbit - 3u, _fifoBuffer[source++]);
        }
    }

    private void DecodeFifoType4(uint command)
    {
        uint target = (command >> 3) & 0xfffu;
        int source = 1;
        for (int bit = 15; bit <= 28; bit++, target++)
        {
            if (((command >> bit) & 1u) == 0)
                continue;

            if (source >= _fifoBuffer.Count)
                return;

            uint value = _fifoBuffer[source++];
            WriteCmdFifoRegister(target, value);
        }
    }

    private void WriteCmdFifoRegister(uint target, uint value)
    {
        uint register = target & 0xffu;
        TraceCommandFifoRegisterValue(target, value);
        if (_traceTmuRegisterWrites &&
            _tmuRegisterWriteTraceCount < 160 &&
            IsTmuTextureRegister(register))
        {
            ulong pc = CpuPcProvider?.Invoke() ?? 0;
            string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
            Console.WriteLine($"[GAUNTDL:VOODOO-TMU] target=0x{target:x3} reg=0x{register:x2} value=0x{value:x8}{pcStatus}");
            _tmuRegisterWriteTraceCount++;
        }

        if (_fixTmuRegisterBanks && TryWriteTmuRegister(target, value))
            return;

        WriteRegister(register << 2, value);
    }

    private void TraceCommandFifoRegisterValue(uint target, uint value)
    {
        if (!_traceCommandFifoModel ||
            _traceCommandFifoModelCommands.Length == 0 ||
            !_traceCommandFifoModelCommands.Contains(value) ||
            _commandFifoRegisterValueTraceCount++ >= 80)
        {
            return;
        }

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-CMDFIFO] reg-value target=0x{target:x3} reg=0x{target & 0xffu:x2} " +
            $"value=0x{value:x8} packet=0x{_currentCommandFifoCommand:x8} " +
            $"packetType={_currentCommandFifoCommand & 7u} packetStart=0x{_currentCommandFifoPacketStart * 4:x8} " +
            $"words={_currentCommandFifoWordsNeeded} rd=0x{_cmdFifoReadIndex * 4:x8} " +
            $"depth={_cmdFifoDepth} holes={_cmdFifoHoles} amin=0x{_cmdFifoAddressMin:x8} amax=0x{_cmdFifoAddressMax:x8}{pcStatus}");
    }

    private bool TryWriteTmuRegister(uint target, uint value)
    {
        uint register = target & 0xffu;
        if (!IsTmuTextureRegister(register))
            return false;

        int tmu = DecodeTmuIndex(target);
        if (tmu < 0)
            return false;

        int index = (int)register;
        _tmuRegisters[tmu][index] = value;
        _tmuRegisterValid[tmu][index] = true;
        _registerWriteCount++;
        RecordVoodooEvent($"tmu{tmu}[{register:x2}]=0x{value:x8}");
        return true;
    }

    private static bool IsTmuTextureRegister(uint register)
        => register == (uint)RegTextureMode ||
           register == (uint)RegTextureLod ||
           register == (uint)RegTextureBaseAddr;

    private static int DecodeTmuIndex(uint target)
    {
        if ((target & 0x400u) != 0)
            return 1;
        if ((target & 0x200u) != 0)
            return 0;
        return -1;
    }

    private uint ReadTextureRegister(int register)
    {
        if (_fixTmuRegisterBanks)
        {
            if (_tmuRegisterValid[0][register])
                return _tmuRegisters[0][register];
            if (_tmuRegisterValid[1][register])
                return _tmuRegisters[1][register];
        }

        return _registers[register];
    }

    private void RecordInterestingFifoEvent(uint command, int wordsNeeded)
    {
        if (!_recordVoodooEvents)
            return;

        uint type = command & 7u;
        switch (type)
        {
            case 0:
                RecordVoodooEvent($"fifo type0 cmd=0x{command:x8} words={wordsNeeded} rd=0x{_cmdFifoReadIndex:x4}");
                break;
            case 1:
            {
                int count = (int)(command >> 16);
                uint target = (command >> 3) & 0xfffu;
                if (TouchesInterestingEventRegister(target, (uint)Math.Max(0, count)))
                    RecordVoodooEvent($"fifo type1 cmd=0x{command:x8} target=0x{target:x3} count={count} inc={(command >> 15) & 1u} words={wordsNeeded} rd=0x{_cmdFifoReadIndex:x4}");
                break;
            }
            case 3:
            {
                uint w1 = _fifoBuffer.Count > 1 ? _fifoBuffer[1] : 0;
                uint w2 = _fifoBuffer.Count > 2 ? _fifoBuffer[2] : 0;
                uint w3 = _fifoBuffer.Count > 3 ? _fifoBuffer[3] : 0;
                uint w4 = _fifoBuffer.Count > 4 ? _fifoBuffer[4] : 0;
                uint w5 = _fifoBuffer.Count > 5 ? _fifoBuffer[5] : 0;
                uint w6 = _fifoBuffer.Count > 6 ? _fifoBuffer[6] : 0;
                RecordVoodooEvent(
                    $"fifo type3 cmd=0x{command:x8} count={(command >> 6) & 0xfu} code={(command >> 3) & 7u} " +
                    $"words={wordsNeeded} data=0x{w1:x8}/0x{w2:x8}/0x{w3:x8}/0x{w4:x8}/0x{w5:x8}/0x{w6:x8} rd=0x{_cmdFifoReadIndex:x4}");
                break;
            }
            case 4:
            {
                uint target = (command >> 3) & 0xfffu;
                uint mask = (command >> 15) & 0x3fffu;
                if (TouchesInterestingType4Register(target, mask))
                    RecordVoodooEvent($"fifo type4 cmd=0x{command:x8} target=0x{target:x3} mask=0x{mask:x4} words={wordsNeeded} rd=0x{_cmdFifoReadIndex:x4}");
                break;
            }
            case 5:
            {
                uint target = _fifoBuffer.Count > 1 ? _fifoBuffer[1] : 0;
                uint first = _fifoBuffer.Count > 2 ? _fifoBuffer[2] : 0;
                uint second = _fifoBuffer.Count > 3 ? _fifoBuffer[3] : 0;
                RecordVoodooEvent($"fifo type5 cmd=0x{command:x8} count={(command >> 3) & 0x7ffffu} space={command >> 30} target=0x{target:x8} data=0x{first:x8}/0x{second:x8} words={wordsNeeded} rd=0x{_cmdFifoReadIndex:x4}");
                break;
            }
        }
    }

    private void RecordVoodooEvent(string description)
    {
        if (!_recordVoodooEvents)
            return;

        int sequence = _recentVoodooEventSequence++;
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        _recentVoodooEvents[sequence & (_recentVoodooEvents.Length - 1)] = $"{sequence}:{description}{pcStatus}";
    }

    private string FormatRecentVoodooEvents()
    {
        int count = Math.Min(_recentVoodooEventSequence, _recentVoodooEvents.Length);
        if (count == 0)
            return "none";

        int start = _recentVoodooEventSequence - count;
        return string.Join(" | ", Enumerable.Range(0, count).Select(i => _recentVoodooEvents[(start + i) & (_recentVoodooEvents.Length - 1)]));
    }

    private void CountFastFillPc(ushort color, bool suppressed, int bufferIndex)
    {
        if (!_profileFastFillSwapPcs)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (pc == 0)
            return;

        if (!_fastFillPcStats.TryGetValue(pc, out FastFillPcStats? stats))
        {
            stats = new FastFillPcStats();
            _fastFillPcStats[pc] = stats;
        }

        stats.Total++;
        if (suppressed)
            stats.Suppressed++;
        if (color == 0xffff)
            stats.White++;
        else if (color == 0)
            stats.Black++;
        else
            stats.Other++;
        if ((uint)bufferIndex < (uint)stats.BufferCounts.Length)
            stats.BufferCounts[bufferIndex]++;
        stats.LastColor = color;
        stats.LastFbzMode = _registers[RegFbzMode];
        stats.LastColor0 = _registers[RegColor0];
        stats.LastColor1 = _registers[RegColor1];
        stats.LastZaColor = _registers[RegZaColor];
        stats.LastCommandFifoReadIndex = _cmdFifoReadIndex;
        stats.LastBufferIndex = bufferIndex;
        stats.LastSuppressed = suppressed;
    }

    private void TraceFastFillSwapOrder(string kind, uint register, uint value)
    {
        if (!_traceFastFillSwapOrder || _fastFillSwapOrderTraceCount >= _traceFastFillSwapOrderLimit)
            return;

        if (kind == "reg" && !IsFastFillSwapOrderRegister(register))
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (_traceFastFillSwapOrderPcs.Length != 0 && !_traceFastFillSwapOrderPcs.Contains(pc))
            return;

        Console.WriteLine(
            $"[GAUNTDL:VOODOO-FILL-SWAP] n={++_fastFillSwapOrderTraceCount} kind={kind} " +
            $"pc=0x{pc:x16} reg=0x{register:x3} value=0x{value:x8} " +
            $"c0=0x{_registers[RegColor0]:x8} c1=0x{_registers[RegColor1]:x8} za=0x{_registers[RegZaColor]:x8} " +
            $"fbz=0x{_registers[RegFbzMode]:x8} lfb=0x{_registers[RegLfbMode]:x8} " +
            $"front={_frontBufferIndex} back={_backBufferIndex} rd=0x{_cmdFifoReadIndex:x6} " +
            $"depth={_cmdFifoDepth} holes={_cmdFifoHoles} fifoPackets={_fifoPacketCount} draws={_fifoDrawPacketCount} " +
            $"fills={_fastFillCount} swaps={_swapBufferCount}");
    }

    private static bool IsFastFillSwapOrderRegister(uint register)
        => register is RegFbzMode or RegLfbMode or RegFastfillCommand or RegSwapbufferCommand or
            RegZaColor or RegColor0 or RegColor1 or RegClipLeftRight or RegClipLowYHighY;

    private static ulong[] ParseOptionalHexUlongList(string? raw)
    {
        if (string.IsNullOrWhiteSpace(raw))
            return [];

        return raw.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Select(item => item.StartsWith("0x", StringComparison.OrdinalIgnoreCase) ? item[2..] : item)
            .Select(item => ulong.TryParse(item, System.Globalization.NumberStyles.HexNumber, null, out ulong value) ? value : 0)
            .Where(value => value != 0)
            .Distinct()
            .ToArray();
    }

    private static int ParseOptionalPositiveInt(string? raw, int fallback)
        => int.TryParse(raw, out int parsed) && parsed > 0 ? parsed : fallback;

    private void CountSwapPc(uint command, bool dontSwap, bool clearBackBuffer)
    {
        if (!_profileFastFillSwapPcs)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (pc == 0)
            return;

        if (!_swapPcStats.TryGetValue(pc, out SwapPcStats? stats))
        {
            stats = new SwapPcStats();
            _swapPcStats[pc] = stats;
        }

        stats.Total++;
        if (clearBackBuffer)
            stats.Clear++;
        if (dontSwap)
            stats.DontSwap++;
        stats.LastCommand = command;
    }

