    {
        if (!_profileCommandFifoPacketPcs)
            return "";

        return $"cmdpc={FormatCommandFifoPacketPcStats()} cmdw={FormatCommandFifoWritePcStats()} cmdreg={FormatCommandFifoRegisterReadPcStats()} cmdwr={FormatCommandFifoRegisterWritePcStats()} ";
