    private void CountCommandFifoDecodeCallPc(
        ulong pc,
        int decodedPackets,
        int startReadIndex,
        int startDepth,
        int endReadIndex,
        uint firstCommand,
        uint lastCommand,
        uint typeMask,
        string stopReason)
    {
        if (!_profileCommandFifoPacketPcs || pc == 0)
            return;

        if (!_commandFifoDecodeCallPcStats.TryGetValue(pc, out CommandFifoDecodeCallPcStats? stats))
        {
            stats = new CommandFifoDecodeCallPcStats();
            _commandFifoDecodeCallPcStats[pc] = stats;
        }

        stats.Calls++;
        stats.Packets += decodedPackets;
        stats.MaxPackets = Math.Max(stats.MaxPackets, decodedPackets);
        if (decodedPackets <= 0)
            stats.EmptyCalls++;
        else if (typeMask == (1u << 5))
            stats.Type5OnlyCalls++;
        else if ((typeMask & ~(1u << 5)) != 0 && (typeMask & (1u << 5)) != 0)
            stats.MixedWithType5Calls++;
        else
            stats.NonType5Calls++;
        stats.LastPackets = decodedPackets;
        stats.LastStartReadIndex = startReadIndex;
        stats.LastStartDepth = startDepth;
        stats.LastEndReadIndex = endReadIndex;
        stats.LastFirstCommand = firstCommand;
        stats.LastLastCommand = lastCommand;
        stats.LastTypeMask = typeMask;
        stats.LastStopReason = stopReason;

        string triggerKey = $"{_commandFifoDecodeTrigger}@0x{pc:x16}";
        if (!_commandFifoDecodeTriggerStats.TryGetValue(triggerKey, out CommandFifoDecodeTriggerStats? triggerStats))
        {
            triggerStats = new CommandFifoDecodeTriggerStats();
            _commandFifoDecodeTriggerStats[triggerKey] = triggerStats;
        }
        triggerStats.Calls++;
        triggerStats.Packets += decodedPackets;
        if (decodedPackets <= 0)
            triggerStats.EmptyCalls++;
        else if (typeMask == (1u << 5))
            triggerStats.Type5OnlyCalls++;
        else if ((typeMask & ~(1u << 5)) != 0 && (typeMask & (1u << 5)) != 0)
            triggerStats.MixedWithType5Calls++;
        else
            triggerStats.NonType5Calls++;
        triggerStats.LastPackets = decodedPackets;
        triggerStats.LastStopReason = stopReason;
    }

